def _bootstrap_runtime_tools() -> None:
    exe_ext = ".exe" if os.name == "nt" else ""
    cand_dirs = [
        CODE_DIR.parent / "runtime" / "ffmpeg" / "bin",
        CODE_DIR.parent.parent / "runtime" / "ffmpeg" / "bin",
        CODE_DIR.parent / "ffmpeg" / "bin",
    ]
    for env_key in ("V16_FFMPEG_EXE", "V16_FFPROBE_EXE"):
        val = os.environ.get(env_key, "").strip().strip('"')
        if val and Path(val).is_file():
            cand_dirs.insert(0, Path(val).resolve().parent)
    valid_dirs = []
    for d in cand_dirs:
        if d.is_dir():
            s = str(d.resolve())
            if s not in valid_dirs:
                valid_dirs.append(s)
            if not os.environ.get("V16_FFMPEG_EXE") and (d / f"ffmpeg{exe_ext}").is_file():
                os.environ["V16_FFMPEG_EXE"] = str((d / f"ffmpeg{exe_ext}").resolve())
            if not os.environ.get("V16_FFPROBE_EXE") and (d / f"ffprobe{exe_ext}").is_file():
                os.environ["V16_FFPROBE_EXE"] = str((d / f"ffprobe{exe_ext}").resolve())
    if valid_dirs:
        os.environ["PATH"] = os.pathsep.join(
            p for p in [*valid_dirs, *os.environ.get("PATH", "").split(os.pathsep)] if p
        )


_bootstrap_runtime_tools()

if os.name == "nt":
    _orig_web_subprocess_run = subprocess.run

    def _web_quiet_subprocess_run(*args, **kwargs):
        kwargs["creationflags"] = int(kwargs.get("creationflags", 0)) | getattr(
            subprocess, "CREATE_NO_WINDOW", 0x08000000
        )
        if kwargs.get("text"):
            kwargs.setdefault("encoding", "utf-8")
            kwargs.setdefault("errors", "replace")
        return _orig_web_subprocess_run(*args, **kwargs)

    subprocess.run = _web_quiet_subprocess_run

