def _acquire_instance_lock(file_descriptor):
    """Acquire one non-blocking lifetime lock on POSIX or Windows."""
    if _fcntl is not None:
        _fcntl.flock(file_descriptor, _fcntl.LOCK_EX | _fcntl.LOCK_NB)
        return
    if _msvcrt is not None:
        os.lseek(file_descriptor, 0, os.SEEK_SET)
        if os.fstat(file_descriptor).st_size < 1:
            os.write(file_descriptor, b"\0")
            os.fsync(file_descriptor)
        os.lseek(file_descriptor, 0, os.SEEK_SET)
        _msvcrt.locking(file_descriptor, _msvcrt.LK_NBLCK, 1)
        return
    raise OSError("当前系统不支持文件锁")


