    instance_lock = BASE_DIR / ".v17_instance.lock"
    _INSTANCE_LOCK_FD = os.open(instance_lock, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        _acquire_instance_lock(_INSTANCE_LOCK_FD)
    except OSError as exc:
        os.close(_INSTANCE_LOCK_FD)
        _INSTANCE_LOCK_FD = None
        raise RuntimeError("该独立数据目录已被另一个页面实例占用。") from exc
    os.ftruncate(_INSTANCE_LOCK_FD, 0)
    os.write(_INSTANCE_LOCK_FD, f"{INSTANCE_ID}\n".encode("utf-8"))
    os.fsync(_INSTANCE_LOCK_FD)
