def natural_tail_allowance(reference_duration):
    """Bound the one permitted natural story-block overrun for a reference."""
    reference = float(reference_duration or MIN_TARGET_SECONDS)
    if not math.isfinite(reference) or reference < MIN_TARGET_SECONDS:
        reference = MIN_TARGET_SECONDS
    return round(
        min(
            MAX_NATURAL_TAIL_SECONDS,
            max(MIN_NATURAL_TAIL_SECONDS, reference * NATURAL_TAIL_RATIO),
        ),
        3,
    )


