def format_gib(byte_count):
    return f"{max(0, int(byte_count)) / GIB_BYTES:.2f} GiB"


def _existing_disk_probe(path):
    candidate = Path(path).expanduser()
    if candidate.exists() and candidate.is_file():
        candidate = candidate.parent
    while not candidate.exists() and candidate.parent != candidate:
        candidate = candidate.parent
    if not candidate.exists():
        candidate = Path.cwd()
    return candidate


def disk_space_snapshot(path):
    probe = _existing_disk_probe(path)
    usage = shutil.disk_usage(probe)
    return {
        "probe": probe,
        "total_bytes": int(usage.total),
        "used_bytes": int(usage.used),
        "free_bytes": int(usage.free),
    }


def ensure_additional_disk_space(path, required_bytes, operation):
    required = max(1, int(required_bytes))
    snapshot = disk_space_snapshot(path)
    if snapshot["free_bytes"] < required:
        raise OSError(
            f"{operation}需要至少 {format_gib(required)} 可用空间，"
            f"当前仅 {format_gib(snapshot['free_bytes'])}；已在启动前安全停止，"
            "不会删除原素材或已验收成片。"
        )
    snapshot["required_bytes"] = required
    return snapshot


def required_candidate_working_bytes(target_seconds, remaining_outputs=1):
    try:
        seconds = max(MIN_TARGET_SECONDS, float(target_seconds))
    except (TypeError, ValueError):
        seconds = MIN_TARGET_SECONDS
    try:
        count = max(1, min(5, int(remaining_outputs)))
    except (TypeError, ValueError):
        count = 1
    estimated = DISK_RESERVE_BYTES + math.ceil(
        seconds * DISK_CANDIDATE_BYTES_PER_TARGET_SECOND
        + seconds * count * DISK_FINAL_BYTES_PER_TARGET_SECOND
    )
    return max(MIN_WORKING_FREE_BYTES, estimated)


def ensure_candidate_working_space(target_seconds, remaining_outputs=1):
    return ensure_additional_disk_space(
        BASE_DIR,
        required_candidate_working_bytes(target_seconds, remaining_outputs),
        "本批视频制作",
    )


