def _validated_renderer_working_root():
    """Return the renderer temp root only when it is a direct, real child."""
    try:
        base_root = BASE_DIR.resolve()
        candidate = BASE_DIR / "tmp_process_v16_enhanced"
        if candidate.is_symlink():
            return None
        resolved = candidate.resolve()
        if (
            resolved.parent != base_root
            or resolved.name != "tmp_process_v16_enhanced"
        ):
            return None
        return resolved
    except OSError:
        return None


def cleanup_renderer_job_tmp_path(job_tmp_path, run_id):
    """Remove only one renderer attempt directory owned by ``run_id``.

    A normal task completion must never remove the shared renderer temp root:
    another same-page worker can be writing a sibling directory at that exact
    moment.  Both the direct-child boundary and the run-id prefix are verified
    before recursively deleting anything.
    """
    root = _validated_renderer_working_root()
    if root is None:
        return False
    run_id = str(run_id or "")
    if not run_id or Path(run_id).name != run_id:
        return False
    try:
        candidate = Path(job_tmp_path)
        if candidate.is_symlink():
            return False
        resolved = candidate.resolve()
        if resolved.parent != root or not resolved.name.startswith(f"{run_id}-"):
            return False
    except (OSError, TypeError, ValueError):
        return False
    for attempt in range(6):
        try:
            if resolved.exists():
                shutil.rmtree(resolved)
            return True
        except OSError:
            if attempt == 5:
                return False
            time.sleep(0.2 * (attempt + 1))
    return False


def cleanup_renderer_working_root_if_idle():
    """Cold-start cleanup for stale attempts; refuse while any task is owned."""
    root = _validated_renderer_working_root()
    if root is None:
        return False
    with task_queue_control_lock:
        if (
            task_queue_renderer_processes
            or task_queue_renderer_jobs
            or task_queue_suspended_process_ids
            or task_queue_suspended_run_ids
            or task_queue_disk_reservations
        ):
            return False
        for attempt in range(6):
            try:
                if root.exists():
                    shutil.rmtree(root)
                return True
            except OSError:
                if attempt == 5:
                    return False
                time.sleep(0.2 * (attempt + 1))
    return False


def renderer_working_directory_cleanup_safe(run_id, proc):
    """Never remove shared work files while any owned process tree may live."""
    run_id = str(run_id)
    with task_queue_control_lock:
        return (
            run_id not in task_queue_renderer_processes
            and run_id not in task_queue_renderer_jobs
            and run_id not in task_queue_suspended_process_ids
            and run_id not in task_queue_suspended_run_ids
        )


def renderer_upload_guard_active():
    with task_queue_control_lock:
        return bool(
            task_queue_renderer_processes
            or task_queue_renderer_jobs
            or task_queue_suspended_process_ids
            or task_queue_suspended_run_ids
            or task_queue_disk_reservations
        )


def _task_upload_peak_bytes(content_length):
    """Conservatively cover request spooling plus the durable task copy."""
    try:
        request_bytes = int(content_length)
    except (TypeError, ValueError):
        return None
    if request_bytes <= 0:
        return None
    return request_bytes * 2 + TASK_UPLOAD_PEAK_OVERHEAD_BYTES


def begin_renderer_sensitive_upload(content_length=None):
    """Atomically admit and reserve one upload before multipart parsing.

    Every material upload must declare Content-Length and reserve its complete
    request-spool-plus-durable-copy peak.  At most two requests are admitted;
    their reservations are aggregated under the same condition lock before a
    byte of multipart data is parsed.  During rendering the active render floor
    remains protected; while idle the normal working-space floor is protected.
    The positive return value is the reservation token for the matching finish.
    """
    global task_draft_uploads_in_flight, task_draft_upload_bytes_in_flight
    with task_queue_disk_condition:
        reservation_run_ids = set(task_queue_disk_reservations)
        if (
            task_queue_upload_admission_closed
            or int(task_draft_uploads_in_flight)
            >= MAX_CONCURRENT_MATERIAL_UPLOADS
        ):
            return 0
        renderer_owned = bool(
            task_queue_renderer_processes
            or task_queue_renderer_jobs
            or task_queue_suspended_process_ids
            or task_queue_suspended_run_ids
        )
        # A renderer without the matching disk-floor record is an inconsistent
        # safety state.  Do not parse another large request until it clears.
        renderer_run_ids = {
            *(str(item) for item in task_queue_renderer_processes),
            *(str(item) for item in task_queue_renderer_jobs),
            *(str(item) for item in task_queue_suspended_run_ids),
            *(str(item) for item in task_queue_suspended_process_ids),
        }
        if renderer_owned and not renderer_run_ids.issubset(reservation_run_ids):
            return 0

        reserved_bytes = _task_upload_peak_bytes(content_length)
        protected_bytes = (
            sum(max(0, int(value)) for value in task_queue_disk_reservations.values())
            if task_queue_disk_reservations
            else int(MIN_WORKING_FREE_BYTES)
        )
        if reserved_bytes is None or protected_bytes <= 0:
            return 0
        try:
            free_bytes = int(disk_space_snapshot(BASE_DIR)["free_bytes"])
        except OSError:
            return 0
        remaining = (
            free_bytes
            - int(task_draft_upload_bytes_in_flight)
            - int(reserved_bytes)
        )
        if remaining < protected_bytes:
            return 0

        task_draft_uploads_in_flight += 1
        task_draft_upload_bytes_in_flight += int(reserved_bytes)
        return int(reserved_bytes)


def finish_renderer_sensitive_upload(reservation_token=0):
    global task_draft_uploads_in_flight, task_draft_upload_bytes_in_flight
    try:
        reserved_bytes = int(reservation_token or 0)
    except (TypeError, ValueError):
        reserved_bytes = 0
    if reserved_bytes <= 0:
        reserved_bytes = 0
    with task_queue_disk_condition:
        task_draft_uploads_in_flight = max(
            0,
            int(task_draft_uploads_in_flight) - 1,
        )
        task_draft_upload_bytes_in_flight = max(
            0,
            int(task_draft_upload_bytes_in_flight) - reserved_bytes,
        )
        task_queue_disk_condition.notify_all()


def acquire_renderer_disk_reservation(run_id):
    """Create this run's reservation and drain uploads for disk preflight."""
    global task_queue_upload_admission_closed
    run_id = str(run_id)
    with task_queue_disk_condition:
        task_queue_disk_reservations.setdefault(run_id, 0)
        task_queue_upload_admission_closed = True
        try:
            while task_draft_uploads_in_flight:
                if task_queue_shutdown_event.is_set():
                    raise QueueControlError("服务正在关闭，未等待上传完成")
                task_queue_disk_condition.wait(timeout=0.5)
        except BaseException:
            if run_id in task_queue_disk_reservations:
                task_queue_disk_reservations.pop(run_id, None)
                task_queue_upload_admission_closed = any(
                    int(value) <= 0
                    for value in task_queue_disk_reservations.values()
                )
                task_queue_disk_condition.notify_all()
            raise


def publish_renderer_disk_reservation(run_id, required_bytes):
    """Publish this run's floor; uploads see the aggregate of every run."""
    global task_queue_upload_admission_closed
    run_id = str(run_id)
    required = max(1, int(required_bytes))
    with task_queue_disk_condition:
        if run_id not in task_queue_disk_reservations:
            raise QueueControlError("制作磁盘预留归属已变化，未开放新素材上传")
        aggregate_required = required + sum(
            max(0, int(value))
            for owner, value in task_queue_disk_reservations.items()
            if owner != run_id
        )
        try:
            free_bytes = int(disk_space_snapshot(BASE_DIR)["free_bytes"])
        except OSError as exc:
            raise QueueControlError("无法核对制作磁盘的聚合预留") from exc
        if free_bytes < aggregate_required:
            raise QueueControlError(
                f"并发制作共需保留 {format_gib(aggregate_required)} 可用空间，"
                f"当前仅 {format_gib(free_bytes)}；本任务已在启动渲染前安全停止。"
            )
        task_queue_disk_reservations[run_id] = required
        task_queue_upload_admission_closed = any(
            int(value) <= 0 for value in task_queue_disk_reservations.values()
        )
        task_queue_disk_condition.notify_all()


def release_renderer_disk_reservation(run_id):
    global task_queue_upload_admission_closed
    run_id = str(run_id)
    with task_queue_disk_condition:
        if run_id in task_queue_disk_reservations:
            task_queue_disk_reservations.pop(run_id, None)
            task_queue_upload_admission_closed = any(
                int(value) <= 0 for value in task_queue_disk_reservations.values()
            )
            task_queue_disk_condition.notify_all()

