def existing_35_http_compatibility_enabled():
    """Compatibility hook: the retired service cannot be enabled in this product."""
    return False


def existing_erp_direct_endpoint_enabled():
    """Accept only the approved on-LAN ERP PageReqLog endpoint."""
    try:
        endpoint = urllib.parse.urlsplit(ERP_ENDPOINT)
        origin = (
            endpoint.scheme.lower(),
            endpoint.hostname.lower().rstrip("."),
            endpoint.port or 80,
        )
    except (AttributeError, ValueError):
        return False
    return bool(
        origin == EXISTING_ERP_HTTP_ORIGIN
        and endpoint.path == EXISTING_ERP_DIRECT_PATH
        and not endpoint.username
        and not endpoint.password
        and not endpoint.query
        and not endpoint.fragment
    )


def strict_erp_configuration_error():
    """Validate only local ERP configuration/tenant identity, never an old relay."""
    if not STRICT_ERP_RELAY:
        return ""
    if LOCAL_NO_VALIDATION:
        return "严格传输模式禁止本机免验证，已禁止提交制作任务。"
    if ERP_DIRECT_ENABLED and not existing_erp_direct_endpoint_enabled():
        return "ERP直传地址不是批准的内网固定路径，已禁止提交制作任务。"
    if TENANT_BACKEND_MODE and (
        not re.fullmatch(r"[0-9a-f]{32}", TENANT_USER_ID)
        or not re.fullmatch(r"[0-9a-f]{32}", TENANT_ID)
    ):
        return "当前独立空间缺少有效用户或租户身份，已禁止提交制作任务。"
    return ""


