def discover_latest_completed_fission(root=None):
    root = Path(root or FISSION_OUTPUT_ROOT)
    if not root.is_dir():
        return None
    try:
        run_dirs = sorted(
            (
                path
                for path in root.iterdir()
                if path.is_dir() and re.fullmatch(r"[0-9a-f]{32}", path.name)
            ),
            key=lambda path: path.stat().st_mtime_ns,
            reverse=True,
        )
    except OSError:
        return None
    for run_dir in run_dirs:
        report_path = run_dir / "裂变相似度报告.json"
        zip_path = run_dir / "V17页面裂变成片_同时间轴相似度40以下.zip"
        try:
            report = json.loads(report_path.read_text(encoding="utf-8"))
            count = int(report.get("video_count", 0))
        except (OSError, ValueError, TypeError):
            continue
        if count not in {3, 4, 5}:
            continue
        # Do not restore a legacy dedup-only batch into the new three-pool UI.
        # Historical files remain on disk and their explicit download routes are
        # untouched, but only a report produced under the current shuffle-track
        # contract may populate the live 8018 state.
        if (
            report.get("metric_version") != FISSION_METRIC_VERSION
            or report.get("duration_rules") != list(DURATION_RULES)
            or report.get("protected_materials_excluded") != ["核心素材"]
        ):
            continue
        expected_names = [
            f"V17裂变成片_第{index:02d}条.mp4"
            for index in range(1, count + 1)
        ]
        output_paths = [run_dir / name for name in expected_names]
        duration_policy = str(report.get("duration_policy") or "legacy-unknown-v0")
        try:
            reference_duration = float(
                report.get("reference_duration_seconds", MIN_TARGET_SECONDS)
            )
            duration_multiplier = float(
                report.get("duration_multiplier", DEFAULT_DURATION_MULTIPLIER)
            )
            natural_tail_limit = float(
                report.get(
                    "natural_tail_limit_seconds",
                    natural_tail_allowance(reference_duration),
                )
            )
            natural_boundary_fallback_extra = float(
                report.get("natural_boundary_fallback_extra_seconds", 0.0)
            )
        except (TypeError, ValueError):
            reference_duration = float(MIN_TARGET_SECONDS)
            duration_multiplier = DEFAULT_DURATION_MULTIPLIER
            natural_tail_limit = natural_tail_allowance(reference_duration)
            natural_boundary_fallback_extra = 0.0
        fallback_variant_values = report.get(
            "natural_boundary_fallback_extended_variants", []
        )
        valid_fallback_variants = (
            isinstance(fallback_variant_values, list)
            and all(
                isinstance(value, int) and not isinstance(value, bool)
                and 1 <= value <= count
                for value in fallback_variant_values
            )
            and len(set(fallback_variant_values)) == len(fallback_variant_values)
        )
        fallback_variant_indices = (
            set(fallback_variant_values) if valid_fallback_variants else set()
        )
        tail_ceiling = (
            8.0
            if duration_policy == "reference-natural-tail-v1"
            else MAX_NATURAL_TAIL_SECONDS
        )
        valid_duration_policy = (
            math.isfinite(reference_duration)
            and reference_duration >= MIN_TARGET_SECONDS
            and DURATION_MULTIPLIER_MIN
            <= duration_multiplier
            <= DURATION_MULTIPLIER_MAX
            and 0.0 <= natural_tail_limit <= tail_ceiling
            and math.isfinite(natural_boundary_fallback_extra)
            and 0.0
            <= natural_boundary_fallback_extra
            <= min(natural_tail_limit, 18.0) + 0.001
            and valid_fallback_variants
        )
        if duration_policy == NATURAL_TAIL_POLICY:
            valid_duration_policy = valid_duration_policy and math.isclose(
                natural_tail_limit,
                natural_tail_allowance(reference_duration),
                abs_tol=0.001,
            )
        if duration_policy in {"reference-natural-tail-v1", NATURAL_TAIL_POLICY} and not valid_duration_policy:
            continue
        if not valid_duration_policy:
            reference_duration = float(MIN_TARGET_SECONDS)
            natural_tail_limit = natural_tail_allowance(reference_duration)
        output_durations = report.get("output_durations_seconds", [])
        valid_output_durations = (
            isinstance(output_durations, list)
            and len(output_durations) == count
            and all(
                isinstance(value, (int, float))
                and math.isfinite(float(value))
                and float(value) > 0.0
                and reference_duration - 0.15
                <= float(value)
                <= reference_duration
                + natural_tail_limit
                + (
                    natural_boundary_fallback_extra
                    if index in fallback_variant_indices
                    else 0.0
                )
                + 0.15
                for index, value in enumerate(output_durations, 1)
            )
        )
        if duration_policy in {"reference-natural-tail-v1", NATURAL_TAIL_POLICY} and not valid_output_durations:
            continue
        if not valid_output_durations:
            output_durations = []
        if (
            report.get("run_id") != run_dir.name
            or report.get("passed") is not True
            or report.get("outputs") != expected_names
            or not zip_path.is_file()
            or not all(path.is_file() for path in output_paths)
        ):
            continue
        return {
            "run_id": run_dir.name,
            "count": count,
            "completed": count,
            "max_similarity": report.get("max_similarity_percent"),
            "output_paths": [str(path) for path in output_paths],
            "output_durations": [float(value) for value in output_durations],
            "reference_duration": reference_duration,
            "duration_multiplier": duration_multiplier,
            "duration_policy": duration_policy,
            "natural_tail_limit": natural_tail_limit,
            "zip_path": str(zip_path),
            "finished_at": time.strftime(
                "%Y-%m-%d %H:%M:%S", time.localtime(zip_path.stat().st_mtime)
            ),
        }
    return None


