def _load_or_create_local_web_secrets():
    token_file = BASE_DIR / ".v17_csrf_token.json"
    try:
        if token_file.is_file() and not token_file.is_symlink():
            payload = json.loads(token_file.read_text(encoding="utf-8"))
            sk = str(payload.get("secret_key") or "").strip()
            ct = str(payload.get("csrf_token") or "").strip()
            if len(sk) >= 32 and len(ct) >= 32:
                return sk, ct
    except (OSError, ValueError, TypeError):
        pass
    sk = secrets.token_hex(32)
    ct = secrets.token_urlsafe(32)
    try:
        BASE_DIR.mkdir(parents=True, exist_ok=True)
        tmp_path = BASE_DIR / f".v17_csrf_token.{uuid.uuid4().hex[:8]}.tmp"
        fd = os.open(str(tmp_path), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump({"secret_key": sk, "csrf_token": ct}, fh)
        os.replace(tmp_path, token_file)
    except OSError:
        pass
    return sk, ct


_PERSISTED_SECRET_KEY, _PERSISTED_CSRF_TOKEN = _load_or_create_local_web_secrets()

