@app.post(INTERNAL_ERP_SESSION_PATH)
def install_internal_erp_session():
    """Install this tenant's short-lived ERP token in process memory only."""
    if not TENANT_BACKEND_MODE or request.remote_addr not in {"127.0.0.1", "::1"}:
        abort(404)
    supplied_gateway_token = request.headers.get(
        "X-Kuaishou-Gateway-Token", ""
    )
    supplied_user_id = request.headers.get(INTERNAL_ERP_USER_HEADER, "")
    if (
        not TENANT_GATEWAY_TOKEN
        or not hmac.compare_digest(supplied_gateway_token, TENANT_GATEWAY_TOKEN)
        or not hmac.compare_digest(supplied_user_id, TENANT_USER_ID)
    ):
        abort(403)
    if not ERP_DIRECT_ENABLED:
        return jsonify(ok=False, error="ERP直传当前未启用"), 409
    token = request.headers.get(INTERNAL_ERP_TOKEN_HEADER, "").strip()
    raw_expires_at = request.headers.get(INTERNAL_ERP_EXPIRY_HEADER, "").strip()
    try:
        expires_at = int(raw_expires_at)
    except (TypeError, ValueError):
        abort(400)
    if (
        not 20 <= len(token) <= 10_000
        or not re.fullmatch(r"[A-Za-z0-9._~+/=-]+", token)
        or expires_at <= int(time.time())
    ):
        abort(400)
    global _tenant_erp_bearer_token, _tenant_erp_token_expires_at
    with _tenant_erp_token_lock:
        _tenant_erp_bearer_token = token
        _tenant_erp_token_expires_at = expires_at
    scheduler = globals().get("schedule_deferred_erp_flush")
    if callable(scheduler):
        scheduler()
    return jsonify(ok=True, token_present=True)


