# Rendering state used to be one process-global dictionary.  That silently
# mixed two queue jobs as soon as two workers ran in the same process: the
# second initializer replaced the first job's run_id, and the first worker's
# later progress/log/finalization writes were then discarded or applied to the
# wrong task.  Keep the public/default state for old request paths, while every
# claimed queue run gets its own state dictionary selected by worker-local
# binding.  A small proxy preserves all existing state[...] call sites in the
# renderer without making the Flask request threads inherit a worker binding.
task_run_states = OrderedDict()
task_run_state_context = threading.local()
task_run_state_bound_ids = set()
TASK_RUN_STATE_RETENTION = 32


def _clone_task_state(source):
    return copy.deepcopy(dict(source))


def _task_state_for_run_locked(run_id=None, *, fallback_to_base=True):
    if run_id is not None:
        selected = task_run_states.get(str(run_id))
        if selected is not None:
            return selected
        return _base_state if fallback_to_base else None
    bound_run_id = getattr(task_run_state_context, "run_id", None)
    if bound_run_id:
        selected = task_run_states.get(str(bound_run_id))
        if selected is not None:
            return selected
    return _base_state


def _representative_task_state_locked():
    """Return one legacy top-level state without losing per-task queue data."""
    bound_run_id = getattr(task_run_state_context, "run_id", None)
    if bound_run_id:
        bound_state = task_run_states.get(str(bound_run_id))
        if bound_state is not None:
            return bound_state
    for run_state in task_run_states.values():
        if run_state.get("running"):
            return run_state
    if task_run_states:
        return next(reversed(task_run_states.values()))
    return _base_state


def _prune_task_run_states_locked():
    while len(task_run_states) > TASK_RUN_STATE_RETENTION:
        removable_run_id = next(
            (
                candidate_run_id
                for candidate_run_id, candidate_state in task_run_states.items()
                if (
                    not candidate_state.get("running")
                    and candidate_run_id not in task_run_state_bound_ids
                )
            ),
            None,
        )
        if removable_run_id is None:
            return
        task_run_states.pop(removable_run_id, None)


def bind_task_run_state(run_id):
    run_id = str(run_id)
    with state_lock:
        if run_id not in task_run_states:
            raise RuntimeError(f"任务状态尚未初始化：{run_id}")
        task_run_state_bound_ids.add(run_id)
        task_run_state_context.run_id = run_id


def unbind_task_run_state(run_id=None):
    bound_run_id = getattr(task_run_state_context, "run_id", None)
    if bound_run_id is None:
        return
    if run_id is None or str(run_id) == str(bound_run_id):
        with state_lock:
            task_run_state_bound_ids.discard(str(bound_run_id))
            try:
                del task_run_state_context.run_id
            except AttributeError:
                pass


class _TaskScopedState:
    """Dict-compatible view of the state bound to the current worker thread."""

    def _target(self):
        return _task_state_for_run_locked()

    def __getitem__(self, key):
        return self._target()[key]

    def __setitem__(self, key, value):
        self._target()[key] = value

    def __delitem__(self, key):
        del self._target()[key]

    def __contains__(self, key):
        return key in self._target()

    def __iter__(self):
        return iter(tuple(self._target()))

    def __len__(self):
        return len(self._target())

    def get(self, key, default=None):
        return self._target().get(key, default)

    def keys(self):
        return self._target().keys()

    def items(self):
        return self._target().items()

    def values(self):
        return self._target().values()

    def update(self, *args, **kwargs):
        self._target().update(*args, **kwargs)


