def _normalized_cleanup_scope(owner_user_id=None, tenant_id=None):
    """Validate an optional owner scope without ever inventing an identity."""
    if owner_user_id is None:
        if tenant_id is not None:
            raise ValueError(
                "tenant_id cannot scope cleanup without owner_user_id"
            )
        return None, None

    def normalized(value, field_name, required):
        result = str(value or "").strip()
        if not result:
            if required:
                raise ValueError(f"{field_name} is required")
            return None
        if len(result) > 256:
            raise ValueError(f"{field_name} is too long")
        if any(ord(character) < 32 or ord(character) == 127 for character in result):
            raise ValueError(f"{field_name} contains control characters")
        return result

    return (
        normalized(owner_user_id, "owner_user_id", True),
        normalized(tenant_id, "tenant_id", False),
    )


def _current_cleanup_scope_kwargs():
    """Make tenant and trusted-legacy maintenance scope explicit at call sites."""
    if TENANT_BACKEND_MODE:
        return {
            "owner_user_id": TENANT_USER_ID,
            "tenant_id": TENANT_ID,
        }
    # Trusted legacy maintenance intentionally includes old NULL-owner rows.
