def _path_is_within(path, root):
    try:
        Path(path).relative_to(Path(root))
        return True
    except ValueError:
        return False


def _path_is_reparse_point(path):
    try:
        attributes = int(getattr(os.lstat(path), "st_file_attributes", 0))
    except OSError:
        return True
    return Path(path).is_symlink() or bool(attributes & 0x400)


def _ensure_plain_directory_tree(path, label):
    """Create one trusted directory tree without crossing a reparse point."""
    candidate = Path(os.path.abspath(str(Path(path).expanduser())))
    if not candidate.is_absolute() or not candidate.anchor:
        raise RuntimeError(f"{label}必须是本机完整路径")
    anchor = Path(candidate.anchor)
    if (
        not anchor.is_dir()
        or _path_is_reparse_point(anchor)
    ):
        raise RuntimeError(f"{label}所在磁盘不可用或不安全")
    current = anchor
    for part in candidate.parts[1:]:
        current = current / part
        if os.path.lexists(current):
            if _path_is_reparse_point(current) or not current.is_dir():
                raise RuntimeError(f"{label}不能经过符号链接或重解析点")
            continue
        try:
            current.mkdir()
        except OSError as exc:
            raise RuntimeError(f"{label}无法创建") from exc
        if _path_is_reparse_point(current) or not current.is_dir():
            raise RuntimeError(f"{label}创建后安全校验失败")
    return candidate.resolve(strict=True)



def _storage_root_options():
    return {"primary_base": TENANT_EXPORT_BASE,
            "secondary_base": Path("E:/快手自动化GPU服务器8020成片")}


def _allowed_tenant_export_roots(*, existing_only=False):
    import storage_roots
    roots = storage_roots.tenant_output_roots(TENANT_USER_ID, **_storage_root_options())
    if not existing_only:
        return roots
    result = []
    for root in roots:
        try:
            result.append(storage_roots.validate_tenant_output_root(
                root, TENANT_USER_ID, **_storage_root_options()))
        except (OSError, RuntimeError, ValueError):
            continue
    return tuple(result)


