def normalize_subtitle_masks(raw, *, strict=False):
    return hardcut_audio.normalize_subtitle_masks(raw, strict=strict)


def clone_subtitle_masks(raw):
    clean = hardcut_audio.normalize_subtitle_masks(raw, strict=False)
    return {
        "enabled": bool(clean["enabled"]),
        "style": str(clean["style"]),
        "strength": int(clean["strength"]),
        "boxes": [dict(b) for b in clean["boxes"]],
    }


def parse_subtitle_masks_form():
    raw_val = request.form.get("subtitle_masks", "")
    if not str(raw_val or "").strip():
        return clone_subtitle_masks(None)
    return hardcut_audio.normalize_subtitle_masks(raw_val, strict=True)


def allocate_timeline_budgets(
    target_duration,
    core_duration,
    quality_duration,
    dedup_duration,
    slice_seconds=None,
    use_hardcut=None,
):
    """Allocate the timeline budgets (supports both Original 8018 and V2 whole-core hardcut)."""
    target = float(target_duration)
    core_source = max(0.0, float(core_duration or 0.0))
    shuffle = max(0.0, float(quality_duration or 0.0)) + max(
        0.0, float(dedup_duration or 0.0)
    )
    if not math.isfinite(target) or target < MIN_TARGET_SECONDS:
        raise ValueError("参考成片时长超出允许范围。")
    if core_source <= 0.0:
        raise ValueError("没有可读取的核心素材，请重新选择或上传有效视频。")
    if shuffle <= 0.0:
        raise ValueError("没有可读取的打乱素材，请重新选择或上传有效视频。")
    effective_hardcut = HARDCUT_DUB_MODE if use_hardcut is None else bool(use_hardcut)
    if effective_hardcut:
        core_effective = core_source
        min_allowed = min(
            core_source + min(shuffle, 0.5),
            core_effective * DURATION_MULTIPLIER_MIN,
        )
        max_allowed = core_effective * DURATION_MULTIPLIER_MAX + max(shuffle, 10.0)
        if target + 0.001 < min_allowed:
            raise ValueError(
                f"时长条件未满足：T={target:.1f}秒，必须 ≥ {min_allowed:.1f}秒。"
            )
        if target > max_allowed + 0.001:
            raise ValueError(
                f"时长条件未满足：T={target:.1f}秒，不能超过 {max_allowed:.1f}秒。"
            )
        core_budget = core_source
        shuffle_budget = max(
            min(shuffle, 0.5),
            min(shuffle, max(0.0, target - core_budget)),
        )
        slice_s = hardcut_audio.parse_slice_seconds(
            slice_seconds
            if slice_seconds is not None
            else hardcut_audio.DEFAULT_SLICE_SECONDS
        )
        return {
            "target": round(core_budget + shuffle_budget, 3),
            "core": core_budget,
            "core_source": core_source,
            "core_effective": core_effective,
            "core_budget": core_budget,
            "core_trimmed": 0.0,
            "quality": 0.0,
            "dedup": shuffle_budget,
            "shuffle": shuffle_budget,
            "shuffle_source": shuffle,
            "minimum_shuffle": min(shuffle, slice_s),
            "fixed_prefix": core_budget,
        }
    core_effective = min(
        core_source,
        shuffle / SHUFFLE_TO_CORE_MIN_RATIO,
    )
    if core_effective <= 0.0:
        raise ValueError("核心或打乱素材的有效时长不足。")
    if target + 0.001 < core_effective * DURATION_MULTIPLIER_MIN:
        raise ValueError(
            f"时长条件未满足：T={target:.1f}秒，必须 ≥ C×1="
            f"{core_effective:.1f}秒。"
        )
    if target > core_effective * DURATION_MULTIPLIER_MAX + 0.001:
        raise ValueError(
            f"时长条件未满足：T={target:.1f}秒，不能超过 C×10="
            f"{core_effective * 10:.1f}秒。"
        )
    core_budget = min(core_effective, target * CORE_TO_OUTPUT_MAX_RATIO)
    shuffle_budget = max(0.0, target - core_budget)
    return {
        "target": target,
        "core": core_budget,
        "core_source": core_source,
        "core_effective": core_effective,
        "core_budget": core_budget,
        "core_trimmed": max(0.0, core_source - core_budget),
        "quality": 0.0,
        "dedup": shuffle_budget,
        "shuffle": shuffle_budget,
        "shuffle_source": shuffle,
        "minimum_shuffle": core_effective * SHUFFLE_TO_CORE_MIN_RATIO,
        "fixed_prefix": core_budget,
    }


def _selected_pool_duration(selected_materials, pool, material_root=None):
    names = list(selected_materials.get(pool, []))
    if not names:
        return 0.0
    total = 0.0
    for name in names:
        duration = _media_duration(Path(material_root or BASE_DIR) / pool / name)
        if duration <= 0.0:
            raise ValueError(f"{POOL_LABELS.get(pool, pool)}中的“{name}”无法读取有效时长。")
        total += duration
    return total


def selected_timeline_budgets(
    selected_materials,
    duration_multiplier,
    material_root=None,
    slice_seconds=None,
    use_hardcut=None,
):
    core_duration = _selected_pool_duration(
        selected_materials, "核心素材", material_root
    )
    shuffle_duration = _selected_pool_duration(
        selected_materials, "打乱素材池", material_root
    )
    multiplier = float(duration_multiplier)
    if core_duration <= 0.0:
        raise ValueError("没有可读取的核心素材，请重新选择或上传有效视频。")
    if shuffle_duration <= 0.0:
        raise ValueError("没有可读取的打乱素材，请重新选择或上传有效视频。")
    effective_hardcut = HARDCUT_DUB_MODE if use_hardcut is None else bool(use_hardcut)
    if effective_hardcut:
        slice_s = hardcut_audio.parse_slice_seconds(
            slice_seconds
            if slice_seconds is not None
            else hardcut_audio.DEFAULT_SLICE_SECONDS
        )
        desired_shuffle = max(
            min(shuffle_duration, slice_s),
            core_duration * multiplier - core_duration,
        )
        shuffle_budget = max(
            min(shuffle_duration, 0.5),
            min(shuffle_duration, desired_shuffle),
        )
        target_duration = round(core_duration + shuffle_budget, 3)
        budgets = allocate_timeline_budgets(
            target_duration,
            core_duration,
            0.0,
            shuffle_duration,
            slice_seconds=slice_s,
            use_hardcut=True,
        )
        budgets["multiplier"] = round(multiplier, 1)
        budgets["slice_seconds"] = slice_s
        return budgets
    effective_core_duration = min(
        core_duration,
        shuffle_duration / SHUFFLE_TO_CORE_MIN_RATIO,
    )
    target_duration = round(effective_core_duration * multiplier, 3)
    budgets = allocate_timeline_budgets(
        target_duration,
        core_duration,
        0.0,
        shuffle_duration,
        use_hardcut=False,
    )
    budgets["multiplier"] = round(multiplier, 1)
    budgets["minimum_shuffle"] = round(
        effective_core_duration * SHUFFLE_TO_CORE_MIN_RATIO, 3
    )
    return budgets


def build_fission_plan_key(
    selected_materials,
    planning_options=None,
    material_root=None,
):
    """Return a stable seed for identical material and render settings.

    A queue run id is intentionally excluded.  Previously two otherwise
    identical jobs explored unrelated candidate windows, so one could finish
    while the other exhausted its four random attempts.  The stable plan key
    makes retries reproducible while variant/attempt numbers still provide a
    deterministic sequence of distinct candidates inside the batch.
    """
    root = Path(material_root or BASE_DIR).resolve()
    material_identity = {}
    for pool in (*POOLS, *DISABLED_MATERIAL_POOLS):
        pool_items = []
        pool_root = (root / pool).resolve()
        for raw_name in selected_materials.get(pool, []):
            name = str(raw_name)
            candidate = pool_root / name
            size = None
            try:
                resolved = candidate.resolve(strict=False)
                if resolved.parent == pool_root and resolved.is_file():
                    size = int(resolved.stat().st_size)
            except OSError:
                size = None
            pool_items.append({"name": name, "size": size})
        material_identity[pool] = pool_items
    payload = {
        "policy": FISSION_PLAN_POLICY,
        "materials": material_identity,
        "options": dict(planning_options or {}),
    }
    encoded = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _fission_seed(plan_key, variant_index, attempt, label):
    digest = hashlib.sha256(
        f"{plan_key}:{variant_index}:{attempt}:{label}".encode("utf-8")
    ).digest()
    return int.from_bytes(digest[:8], "big")


def fission_material_capacity(selected_materials):
    shuffle_orders = math.factorial(
        len(selected_materials.get("打乱素材池", []))
    )
    return max(
        1,
        shuffle_orders
        * (FISSION_ATTEMPTS_PER_OUTPUT + FISSION_BATCH_EXTRA_ATTEMPTS),
    )


def fission_batch_candidate_budget(fission_count):
    count = max(1, int(fission_count))
    if count <= 1:
        return 1
    return count * FISSION_ATTEMPTS_PER_OUTPUT + FISSION_BATCH_EXTRA_ATTEMPTS


def fission_candidate_limit(fission_count, variant_index):
    """Return the cumulative cap while reserving base attempts for later outputs."""
    count = max(1, int(fission_count))
    index = max(1, min(count, int(variant_index)))
    remaining_outputs = count - index
    return fission_batch_candidate_budget(count) - (
        remaining_outputs * FISSION_ATTEMPTS_PER_OUTPUT
    )


def fission_material_error(selected_materials, fission_count):
    # The two duration equations are the only material gates requested for
    # 8018. One long shuffle source can still yield multiple natural blocks and
    # fast visual styles, so do not add a hidden file-count requirement here.
    return ""


def _permutation_by_rank(items, rank):
    remaining = list(items)
    if len(remaining) < 2:
        return remaining
    rank = int(rank) % math.factorial(len(remaining))
    ordered = []
    while remaining:
        block = math.factorial(len(remaining) - 1)
        index, rank = divmod(rank, block)
        ordered.append(remaining.pop(index))
    return ordered


def build_fission_materials(
    selected_materials, plan_key, variant_index, attempt=0, plan_index=None
):
    """Keep every core, rotate its opener, and permute the shuffle pool."""
    variant = {
        pool: list(selected_materials.get(pool, []))
        for pool in (*POOLS, *DISABLED_MATERIAL_POOLS)
    }
    core_files = list(selected_materials.get("核心素材", []))
    if len(core_files) > 1:
        base_rank = _fission_seed(
            plan_key,
            0,
            0,
            "materials:核心素材",
        ) % math.factorial(len(core_files))
        core_files = _permutation_by_rank(core_files, base_rank)
        opener_index = (
            max(1, int(variant_index)) - 1
        )
        opener_index %= len(core_files)
        core_files = core_files[opener_index:] + core_files[:opener_index]
    variant["核心素材"] = core_files
    if plan_index is None:
        plan_index = max(0, int(variant_index) - 1) + max(0, int(attempt))
    plan_index = max(0, int(plan_index))
    for pool in POOLS:
        if pool != "打乱素材池":
            continue
        files = list(variant.get(pool, []))
        if len(files) > 1:
            permutation_count = math.factorial(len(files))
            base_rank = _fission_seed(
                plan_key, 0, 0, f"materials:{pool}"
            ) % permutation_count
            # Rotate every opener, but independently spread its entire suffix.
            # Adjacent factoradic ranks changed only the last few items; even
            # switching opener blocks kept most of the suffix identical.
            block = math.factorial(len(files) - 1)
            opener = (base_rank // block + plan_index % len(files)) % len(files)
            cycle = plan_index // len(files)
            suffix_base = _fission_seed(plan_key, opener, 0, "shuffle-suffix") % block
            step = 1 + _fission_seed(plan_key, opener, 0, "shuffle-step") % block
            while math.gcd(step, block) != 1:
                step += 1
            rank = opener * block + (suffix_base + cycle * step) % block
            files = _permutation_by_rank(files, rank)
        variant[pool] = files
    for pool in DISABLED_MATERIAL_POOLS:
        variant[pool] = []
    return variant


def choose_shuffle_mask_name(selected_names, plan_key, variant_index, attempt=0):
    """Choose a stable, path-free mask source from the validated shuffle list."""
    names = sorted(dict.fromkeys(str(name) for name in selected_names if name))
    if not names:
        return ""
    base = _fission_seed(plan_key, 0, 0, "shuffle-mask") % len(names)
    index = (base + max(1, int(variant_index)) - 1 + max(0, int(attempt))) % len(names)
    return names[index]


def build_fission_stickers(sticker_settings, variant_index, attempt=0):
    settings = sticker_settings if isinstance(sticker_settings, dict) else {}
    result = {
        "size_percent": int(settings.get("size_percent", 100)),
        "corners": dict(settings.get("corners", {})),
        "fullscreen": dict(settings.get("fullscreen", {})),
    }
    if result["corners"]:
        keys = [key for key, _label in STICKER_CORNERS]
        values = [result["corners"].get(key) for key in keys]
        shift = (max(1, int(variant_index)) - 1 + max(0, int(attempt))) % len(keys)
        values = values[shift:] + values[:shift]
        result["corners"] = {
            key: value for key, value in zip(keys, values) if value
        }
    return result


def build_fission_effects(face_effects, variant_index, attempt=0):
    """Keep only effects explicitly selected by the user.

    Automatic retries use the fast dedup-only FFmpeg styles below.  They must
    never wake the expensive full-video face renderer.
    """
    effects = [effect for effect in face_effects if effect in FACE_EFFECTS and effect != "none"]
    return [effect for effect in FACE_EFFECT_RENDER_ORDER if effect in effects][:FACE_EFFECT_MAX]


def build_fission_dedup_style(style_plan, variant_index, attempt=0):
    # Legacy silhouette/ink/comic retries destroyed colour and texture merely
    # to lower a local dHash score. Every candidate now keeps natural pixels;
    # retries still rotate source windows, arrangements, masks and seeds.
    return "clean"


def load_dedup_hash_file(path, expected_style):
    path = Path(path)
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError) as exc:
        raise RuntimeError("剪辑程序未返回有效的打乱轨道相似度指纹。") from exc
    hashes = payload.get("hashes")
    if (
        payload.get("version") != 2
        or payload.get("track") != "shuffle"
        or payload.get("style") != expected_style
        or not isinstance(hashes, list)
        or not 8 <= len(hashes) <= 72
        or any(
            not isinstance(value, int) or value < 0 or value >= (1 << 64)
            for value in hashes
        )
    ):
        raise RuntimeError("剪辑程序返回的打乱轨道相似度指纹格式无效。")
    try:
        duration = float(payload.get("duration", 0.0))
    except (TypeError, ValueError) as exc:
        raise RuntimeError("打乱轨道相似度指纹缺少有效时长。") from exc
    if not math.isfinite(duration) or duration < 0.35:
        raise RuntimeError("打乱轨道相似度指纹缺少有效时长。")
    return [int(value) for value in hashes]


def _video_frame_hashes(path, start_seconds=0.0, sample_count=48):
    """Return compact dHashes sampled only from the variable dedup section."""
    path = Path(path)
    duration = _media_duration(path)
    start = max(0.0, float(start_seconds or 0.0))
    remaining = duration - start
    if remaining < 0.35:
        raise RuntimeError(
            "固定核心/优质片段已占满成片，没有足够的去重画面可做裂变检测。"
        )
    samples = max(16, min(72, int(sample_count)))
    fps = samples / remaining
    result = subprocess.run(
        [
            "ffmpeg",
            "-v",
            "error",
            "-ss",
            f"{start:.3f}",
            "-i",
            str(path),
            "-vf",
            f"fps={fps:.8f},scale=9:8:flags=area,format=gray",
            "-frames:v",
            str(samples),
            "-f",
            "rawvideo",
            "-pix_fmt",
            "gray",
            "pipe:1",
        ],
        capture_output=True,
        timeout=90,
    )
    if result.returncode != 0:
        raise RuntimeError("无法读取裂变成片画面进行相似度检测。")
    frame_size = 9 * 8
    hashes = []
    for offset in range(0, len(result.stdout) - frame_size + 1, frame_size):
        frame = result.stdout[offset : offset + frame_size]
        value = 0
        for row in range(8):
            row_offset = row * 9
            for column in range(8):
                value = (value << 1) | int(
                    frame[row_offset + column] > frame[row_offset + column + 1]
                )
        hashes.append(value)
        if len(hashes) >= samples:
            break
    if not hashes:
        raise RuntimeError("裂变成片没有可用于相似度检测的画面。")
    return hashes


def load_source_window_audit(path, allowed_sources=None):
    """Read path-free source-window evidence from the runner sidecar."""
    path = Path(path)
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError) as exc:
        raise RuntimeError("剪辑程序未返回有效的素材窗口记录。") from exc
    windows = payload.get("source_windows")
    if windows is None:
        # Compatibility for an already-started pre-v14 runner. New runners
        # always publish the list, including an empty list when appropriate.
        return []
    if not isinstance(windows, list) or len(windows) > 128:
        raise RuntimeError("素材窗口记录格式无效。")
    allowed = (
        {str(name) for name in allowed_sources if name}
        if allowed_sources is not None
        else None
    )
    allowed_boundaries = {
        "source-end",
        "source-start+source-end",
        "natural-start+source-end",
        "source-start+natural-end-after",
        "natural-start+natural-end-after",
        "source-start+natural-end-before",
        "natural-start+natural-end-before",
        "source-start+frame-boundary-fallback",
        "natural-start+frame-boundary-fallback",
        "deterministic-start-fallback+source-end",
        "deterministic-start-fallback+natural-end-after",
        "deterministic-start-fallback+natural-end-before",
        "deterministic-start-fallback+frame-boundary-fallback",
    }
    validated = []
    for item in windows:
        if not isinstance(item, dict):
            raise RuntimeError("素材窗口记录格式无效。")
        source = item.get("source")
        role = item.get("role")
        boundary = item.get("boundary")
        if (
            not isinstance(source, str)
            or not source
            or Path(source).name != source
            or (allowed is not None and source not in allowed)
            or role not in {"core", "shuffle", "timeline"}
            or not isinstance(boundary, str)
            or boundary not in allowed_boundaries
        ):
            raise RuntimeError("素材窗口记录格式无效。")
        try:
            start = float(item.get("start_seconds"))
            end = float(item.get("end_seconds"))
            duration = float(item.get("duration_seconds"))
            window_index = int(item.get("window_index"))
        except (TypeError, ValueError) as exc:
            raise RuntimeError("素材窗口记录格式无效。") from exc
        if (
            not all(math.isfinite(value) for value in (start, end, duration))
            or start < 0.0
            or end <= start
            or duration <= 0.0
            or abs((end - start) - duration) > 0.2
            or window_index < 0
        ):
            raise RuntimeError("素材窗口记录格式无效。")
        validated.append(
            {
                "role": role,
                "source": source,
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "duration_seconds": round(duration, 3),
                "window_index": window_index,
                "boundary": boundary,
            }
        )
    return validated


def load_visual_quality_gate(path):
    """Load the runner's path-free clean-style and output-contract evidence."""

    def square_pixel_ratio(value):
        text = str(value or "").strip()
        separator = ":" if ":" in text else "/" if "/" in text else ""
        if not separator:
            return False
        try:
            numerator, denominator = (
                float(part) for part in text.split(separator, 1)
            )
        except (TypeError, ValueError):
            return False
        return (
            math.isfinite(numerator)
            and math.isfinite(denominator)
            and numerator > 0.0
            and math.isclose(numerator, denominator, abs_tol=1e-9)
        )

    path = Path(path)
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError) as exc:
        raise RuntimeError("剪辑程序未返回有效的成片画质验收证据。") from exc
    gate = payload.get("visual_quality_gate")
    if (
        not isinstance(gate, dict)
        or gate.get("version") != VISUAL_QUALITY_GATE_VERSION
        or gate.get("gate_kind") != "clean-style-invariant"
        or gate.get("status") != "passed"
        or gate.get("passed") is not True
        or gate.get("policy") != VISUAL_QUALITY_POLICY
        or gate.get("requested_style") != "clean"
        or gate.get("effective_style") != "clean"
        or gate.get("style_filters") != []
        or not isinstance(gate.get("candidate_contract"), dict)
    ):
        raise RuntimeError("剪辑程序未返回已通过的 clean-only 渲染配置验收证据。")
    checked_filters = gate.get("dedup_filters_checked")
    source_window_count = gate.get("source_window_count")
    if (
        type(checked_filters) is not int
        or checked_filters != 32
        or type(source_window_count) is not int
        or not 0 <= source_window_count <= 128
    ):
        raise RuntimeError("clean-only 渲染配置验收证据计数无效。")
    contract = gate["candidate_contract"]
    width = contract.get("width")
    height = contract.get("height")
    if type(width) is not int or type(height) is not int:
        raise RuntimeError("成片输出合同证据无效。")
    if (
        contract.get("codec_name") != "h264"
        or contract.get("codec_tag_string") not in {"avc1", "avc3"}
        or contract.get("profile")
        not in {"Constrained Baseline", "Baseline", "Main", "High"}
        or contract.get("pix_fmt") != "yuv420p"
        or (width, height) != (720, 1280)
        or not square_pixel_ratio(contract.get("sample_aspect_ratio"))
        or not isinstance(contract.get("rotation"), list)
    ):
        raise RuntimeError("成片输出合同证据无效。")
    for value in contract["rotation"]:
        if isinstance(value, bool):
            raise RuntimeError("成片旋转合同证据无效。")
        try:
            rotation = float(value)
        except (TypeError, ValueError) as exc:
            raise RuntimeError("成片旋转合同证据无效。") from exc
        if not math.isfinite(rotation) or not math.isclose(
            rotation % 360.0, 0.0, abs_tol=1e-6
        ):
            raise RuntimeError("成片旋转合同证据无效。")
    # The gate schema intentionally contains statistics and basenames only.
    # Reject path-shaped strings defensively before adding it to reports.
    serialized = json.dumps(gate, ensure_ascii=False, separators=(",", ":"))
    if str(BASE_DIR) in serialized or str(CODE_DIR) in serialized:
        raise RuntimeError("成片画质验收证据不应包含本地路径。")
    return gate


def summarize_source_window_durations(source_windows):
    """Return role-specific totals from an already validated window list."""
    return {
        "actual_core_duration_seconds": round(
            math.fsum(
                float(item["duration_seconds"])
                for item in source_windows
                if item.get("role") == "core"
            ),
            3,
        ),
        "shuffle_source_window_duration_seconds": round(
            math.fsum(
                float(item["duration_seconds"])
                for item in source_windows
                if item.get("role") == "shuffle"
            ),
            3,
        ),
    }


def frame_hash_similarity_percent(first_hashes, second_hashes):
    pairs = min(len(first_hashes), len(second_hashes))
    if pairs <= 0:
        return 100.0
    raw_similarity = sum(
        (64 - (int(first_hashes[index]) ^ int(second_hashes[index])).bit_count()) / 64.0
        for index in range(pairs)
    ) / pairs
    # Random unrelated dHashes average around 50%. Rebase that noise floor to
    # 0% so the user-facing percentage reads 0=unrelated and 100=identical.
    calibrated = max(0.0, min(1.0, (raw_similarity - 0.5) / 0.5))
    return round(calibrated * 100.0, 2)


def video_similarity_percent(first_path, second_path, fixed_prefix_seconds=0.0):
    return frame_hash_similarity_percent(
        _video_frame_hashes(first_path, fixed_prefix_seconds),
        _video_frame_hashes(second_path, fixed_prefix_seconds),
    )


def build_fission_bundle(run_dir, output_paths, report):
    """Publish primary artifacts without keeping a second full-size ZIP.

    v1.0.x stored every MP4 twice (standalone and inside an uncompressed ZIP),
    which was the largest avoidable C-drive consumer.  v1.1 streams a ZIP only
    when somebody explicitly downloads one, so the durable artifact here is
    the small report only.  The historical function name is kept because old
    in-flight workers call it during restart recovery.
    """
    del output_paths
    publish_fission_report(run_dir, report)
    return None


def publish_fission_report(run_dir, report):
    """Publish a report atomically even when ZIP creation is unavailable."""
    report_path = Path(run_dir) / "裂变相似度报告.json"
    partial_report_path = report_path.with_suffix(".partial.json")
    try:
        partial_report_path.write_text(
            json.dumps(report, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        os.replace(partial_report_path, report_path)
        return report_path
    finally:
        partial_report_path.unlink(missing_ok=True)


def build_partial_fission_report(
    run_id,
    requested_count,
    accepted_paths,
    accepted_durations,
    pair_results,
    variant_plans,
    failure_summary,
    target_duration,
    timeline_budgets,
    natural_tail_limit,
    dedup_style_plan,
    dedup_style_source,
    timepin_zoom,
    corner_mask_reveal,
    plan_policy="",
    plan_key="",
    candidate_budget=None,
    candidate_attempts_used=None,
):
    requested_count = int(requested_count)
    completed_count = len(accepted_paths)
    if requested_count not in {3, 4, 5}:
        raise ValueError("裂变目标数量无效，无法保存部分成片。")
    if not 1 <= completed_count < requested_count:
        raise ValueError("部分成片数量无效，无法保存。")
    if len(accepted_durations) != completed_count:
        raise ValueError("部分成片时长清单不完整，无法保存。")
    max_similarity = max(
        (float(item["similarity_percent"]) for item in pair_results),
        default=0.0,
    )
    return {
        "metric_version": FISSION_METRIC_VERSION,
        "runtime_stability": runtime_stability_metadata(),
        "plan_policy": str(plan_policy or ""),
        "plan_key": str(plan_key or ""),
        "candidate_budget": int(candidate_budget or 0),
        "candidate_attempts_used": int(candidate_attempts_used or 0),
        "delivery_state": "partial",
        "batch_complete": False,
        "passed": False,
        "accepted_outputs_passed": True,
        "threshold_percent": FISSION_SIMILARITY_LIMIT,
        "definition": (
            "列出的成片均已逐条通过时长与打乱轨相似度验收；"
            "自动补做按新批次，仅比较同轮补做内的成片，不保证跨轮相似度；"
            "但本次请求的全部数量没有完成，所以整批不标记为通过。"
        ),
        "similarity_scope": "within_retry_batch",
        "run_id": str(run_id),
        "video_count": requested_count,
        "requested_count": requested_count,
        "completed_count": completed_count,
        "failed_variant": completed_count + 1,
        "failure_summary": str(failure_summary or "后续成片未通过验收"),
        "duration_policy": NATURAL_TAIL_POLICY,
        "reference_duration_seconds": round(float(target_duration), 3),
        "duration_multiplier": round(float(timeline_budgets["multiplier"]), 1),
        "core_duration_seconds": round(float(timeline_budgets["core"]), 3),
        "core_source_duration_seconds": round(
            float(timeline_budgets["core_source"]), 3
        ),
        "core_effective_duration_seconds": round(
            float(timeline_budgets["core_effective"]), 3
        ),
        "core_inclusion_budget_seconds": round(
            float(timeline_budgets["core_budget"]), 3
        ),
        "shuffle_source_duration_seconds": round(
            float(timeline_budgets["shuffle_source"]), 3
        ),
        "minimum_shuffle_duration_seconds": round(
            float(timeline_budgets["minimum_shuffle"]), 3
        ),
        "duration_rules": list(DURATION_RULES),
        "core_window_policy": CORE_WINDOW_POLICY,
        "shuffle_window_policy": SHUFFLE_WINDOW_POLICY,
        "visual_quality_policy": VISUAL_QUALITY_POLICY,
        "reference_is_hard_cap": False,
        "natural_tail_limit_seconds": round(float(natural_tail_limit), 3),
        "natural_boundary_fallback_extra_seconds": round(
            min(float(natural_tail_limit), 18.0), 3
        ),
        "natural_boundary_fallback_extended_variants": [
            int(plan["index"])
            for plan in variant_plans
            if plan.get("natural_boundary_fallback_extended")
        ],
        "output_durations_seconds": [
            round(float(value), 3) for value in accepted_durations
        ],
        "actual_duration_min_seconds": round(min(accepted_durations), 3),
        "actual_duration_max_seconds": round(max(accepted_durations), 3),
        "protected_materials_excluded": ["核心素材"],
        "shuffle_scope": [
            "每个打乱源按有界自然时间窗取材并连贯重组",
            "长核心按预算和自然边界取窗，裂变错开窗口",
            "所有候选均通过 clean-only 渲染配置约束",
            "蒙版从打乱素材中自动选择且不移除主轨素材",
        ],
        "core_opener_policy": (
            variant_plans[0].get("core_opener_policy", "single-core-legacy")
            if variant_plans
            else "single-core-legacy"
        ),
        "core_openers": [
            str(plan.get("core_opener") or "") for plan in variant_plans
        ],
        "shuffle_reference_seconds": round(
            float(timeline_budgets["shuffle"]), 3
        ),
        "model_style_plan": list(dedup_style_plan),
        "model_style_source": str(dedup_style_source),
        "timepin_zoom": clone_timepin_zoom_settings(timepin_zoom),
        "corner_mask_reveal": clone_corner_mask_reveal_settings(
            corner_mask_reveal
        ),
        "max_similarity_percent": max_similarity,
        "pairs": list(pair_results),
        "outputs": [Path(path).name for path in accepted_paths],
        "variants": list(variant_plans),
    }


def cleanup_incomplete_fission_artifacts(run_dir, run_id):
    """Best-effort removal of unaccepted files; validated outputs always win."""
    if not run_dir or not re.fullmatch(r"[0-9a-f]{32}", run_id or ""):
        return 0
    try:
        root = FISSION_OUTPUT_ROOT.resolve()
        candidate = Path(run_dir)
        if candidate.is_symlink() or not candidate.is_dir():
            return 0
        resolved = candidate.resolve()
    except OSError:
        return 0
    if resolved.parent != root or resolved.name != run_id:
        return 0
    removed = 0
    temporary_patterns = (
        ".裂变候选_*.mp4",
        ".合规候选_*.json",
        ".去重指纹_*.json",
        "*.partial.json",
    )
    for pattern in temporary_patterns:
        try:
            matches = list(resolved.glob(pattern))
        except OSError:
            continue
        for path in matches:
            try:
                removable = path.is_file() or path.is_symlink()
            except OSError:
                removable = False
            if path.parent != resolved or not removable:
                continue
            try:
                path.unlink(missing_ok=True)
                removed += 1
            except OSError:
                # Windows scanners and indexers may hold a short-lived handle.
                # A locked temporary file must never revoke accepted MP4 files.
                continue
    fixed_cache_dir = resolved / ".fixed-stage-cache"
    try:
        if fixed_cache_dir.is_symlink():
            fixed_cache_dir.unlink(missing_ok=True)
            removed += 1
        elif fixed_cache_dir.is_dir():
            shutil.rmtree(fixed_cache_dir)
            removed += 1
    except OSError:
        pass
    return removed


def cleanup_failed_fission_run(run_dir, run_id):
    if not run_dir or not re.fullmatch(r"[0-9a-f]{32}", run_id or ""):
        return False
    root = FISSION_OUTPUT_ROOT.resolve()
    candidate = Path(run_dir)
    if candidate.is_symlink() or not candidate.exists():
        return False
    resolved = candidate.resolve()
    if resolved.parent != root or resolved.name != run_id:
        return False
    shutil.rmtree(resolved)
    return True


def renderer_diagnostic_from_line(line):
    """Return a path-redacted, bounded child diagnostic for durable task errors."""
    markers = {
        "[VisualQualityBlocked]": "visual_quality_blocked",
        "[VisualQualityEvidenceError]": "visual_quality_evidence",
        "[RenderProcessError]": "render_process_error",
    }
    raw = str(line or "").strip()
    for marker, key in markers.items():
        marker_at = raw.find(marker)
        if marker_at < 0:
            continue
        message = raw[marker_at + len(marker) :].strip()
        message = re.sub(r"[\x00-\x1f\x7f]+", " ", message)
        message = redact_local_paths(message).strip()
        return key, message[:800] or "剪辑子进程未返回详细原因"
    return None, ""


def stream_renderer_output(
    proc,
    run_id,
    timeout_seconds=RENDER_TIMEOUT_SECONDS,
    stall_timeout_seconds=DEFAULT_QUEUE_STALL_MINUTES * 60,
    activity_paths=(),
    diagnostics=None,
):
    lines = queue.Queue()

    def read_stdout():
        try:
            for line in proc.stdout or []:
                lines.put(line)
        finally:
            lines.put(None)

    register_queue_renderer(run_id, proc)
    try:
        reader = threading.Thread(target=read_stdout, daemon=True)
        reader.start()
        deadline = time.monotonic() + max(1.0, float(timeout_seconds))
        stall_timeout_seconds = max(1.0, float(stall_timeout_seconds))
        stall_deadline = time.monotonic() + stall_timeout_seconds
    except Exception:
        # The renderer already exists at this point.  If the monitor cannot
        # start, stop and unregister it immediately so the queue can never
        # advance while an unobserved old renderer keeps working.
        terminate_queue_renderer(proc, run_id)
        unregister_queue_renderer(run_id, proc)
        raise

    def activity_signature():
        newest_mtime = 0
        total_size = 0
        file_count = 0
        for raw_path in activity_paths or ():
            root = Path(raw_path)
            try:
                candidates = [root] if root.is_file() else root.rglob("*")
                for candidate in candidates:
                    try:
                        if not candidate.is_file():
                            continue
                        stat = candidate.stat()
                    except OSError:
                        continue
                    newest_mtime = max(newest_mtime, int(stat.st_mtime_ns))
                    total_size += int(stat.st_size)
                    file_count += 1
            except OSError:
                continue
        return newest_mtime, total_size, file_count

    try:
        last_activity_signature = activity_signature()
        next_activity_probe = time.monotonic() + 5.0
    except Exception:
        terminate_queue_renderer(proc, run_id)
        unregister_queue_renderer(run_id, proc)
        raise

    try:
        finished_reading = False
        while not finished_reading:
            if queue_skip_requested(run_id):
                terminate_queue_renderer(proc, run_id)
                raise QueueTaskSkipped("用户已跳过本条任务，队列将继续下一条")

            paused_seconds = wait_at_queue_pause_checkpoint(run_id, proc)
            if paused_seconds > 0:
                deadline += paused_seconds
                stall_deadline += paused_seconds
                next_activity_probe += paused_seconds
                last_activity_signature = activity_signature()

            remaining = deadline - time.monotonic()
            if remaining <= 0:
                terminate_queue_renderer(proc, run_id)
                raise TimeoutError(
                    f"单条渲染超过 {timeout_seconds / 3600:.1f} 小时，已停止本次批次"
                )
            stall_remaining = stall_deadline - time.monotonic()
            if stall_remaining <= 0:
                terminate_queue_renderer(proc, run_id)
                raise TimeoutError(
                    f"连续 {stall_timeout_seconds / 60:.0f} 分钟没有新的制作进展，"
                    "已停止本条并继续队列"
                )
            try:
                item = lines.get(timeout=min(0.5, remaining, stall_remaining))
            except queue.Empty:
                now = time.monotonic()
                if now >= next_activity_probe:
                    current_signature = activity_signature()
                    if current_signature != last_activity_signature:
                        last_activity_signature = current_signature
                        stall_deadline = now + stall_timeout_seconds
                    next_activity_probe = now + 5.0
                continue
            if item is None:
                finished_reading = True
            else:
                stall_deadline = time.monotonic() + stall_timeout_seconds
                diagnostic_key, diagnostic_message = renderer_diagnostic_from_line(item)
                if diagnostic_key and isinstance(diagnostics, dict):
                    diagnostics[diagnostic_key] = diagnostic_message
                if isinstance(diagnostics, dict):
                    tail = diagnostics.setdefault("output_tail", [])
                    tail.append(str(item)[-2000:])
                    del tail[:-16]
                append_log(item, run_id)

        paused_seconds = wait_at_queue_pause_checkpoint(run_id, proc)
        if paused_seconds > 0:
            deadline += paused_seconds
            stall_deadline += paused_seconds
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            terminate_queue_renderer(proc, run_id)
            raise TimeoutError(
                f"单条渲染超过 {timeout_seconds / 3600:.1f} 小时，已停止本次批次"
            )
        try:
            rc = proc.wait(timeout=remaining)
            if (
                rc != 0
                and isinstance(diagnostics, dict)
                and not diagnostics.get("render_process_error")
            ):
                for raw_tail in reversed(diagnostics.get("output_tail") or []):
                    cleaned = re.sub(r"[\x00-\x1f\x7f]+", " ", str(raw_tail or "")).strip()
                    if not cleaned or cleaned.startswith(
                        (
                            "V16_ENCODER_SUMMARY",
                            "V16_PERF_SUMMARY",
                            "Traceback (most recent call last):",
                            'File "',
                        )
                    ):
                        continue
                    redacted = redact_local_paths(cleaned).strip()
                    if redacted:
                        diagnostics["render_process_error"] = redacted[:800]
                        break
            return rc
        except subprocess.TimeoutExpired as exc:
            terminate_queue_renderer(proc, run_id)
            raise TimeoutError(
                f"单条渲染超过 {timeout_seconds / 3600:.1f} 小时，已停止本次批次"
            ) from exc
    finally:
        try:
            resume_queue_renderer(run_id, proc)
        except Exception as exc:
            terminate_queue_renderer(proc, run_id)
            raise QueueControlError(
                "制作监控退出时无法安全恢复暂停进程，已停止本条"
            ) from exc
        finally:
            unregister_queue_renderer(run_id, proc)


def queue_result_for_outputs(
    run_id,
    fission_count,
    output_path,
    accepted_paths,
    accepted_durations,
    bundle_exists=True,
):
    if int(fission_count) > 1:
        requested_count = int(fission_count)
        completed_count = len(accepted_paths)
        return {
            "kind": "fission",
            "delivery_state": (
                "complete"
                if completed_count == requested_count
                else "partial"
            ),
            # The bundle is generated as a non-persistent stream on demand.
            "bundle_url": (
                f"/download-fission/{run_id}/bundle" if completed_count else ""
            ),
            "outputs": [
                {
                    "index": index,
                    "name": path.name,
                    "url": f"/download-fission/{run_id}/{index}",
                    "duration_seconds": (
                        round(float(accepted_durations[index - 1]), 3)
                        if index <= len(accepted_durations)
                        else None
                    ),
                }
                for index, path in enumerate(accepted_paths, 1)
            ],
            "count": requested_count,
            "requested_count": requested_count,
            "completed_count": completed_count,
        }
    return {
        "kind": "single",
        "download_url": f"/queue/download/{run_id}",
        "compliance_url": f"/queue/compliance/{run_id}",
        "name": Path(output_path).name,
        "duration_seconds": (
            round(float(accepted_durations[0]), 3)
            if accepted_durations
            else None
        ),
    }


def checkpoint_running_fission_result(
    run_id,
    requested_count,
    accepted_paths,
    accepted_durations,
):
    """Persist accepted outputs while later variants are still rendering."""
    completed_count = len(accepted_paths)
    requested_count = int(requested_count)
    if not 1 <= completed_count < requested_count:
        return False
    store = get_task_queue_store(create=False)
    if store is None or not hasattr(store, "update_running_result"):
        return False
    checkpoint = queue_result_for_outputs(
        run_id,
        requested_count,
        accepted_paths[0],
        accepted_paths,
        accepted_durations,
        bundle_exists=False,
    )
    checkpoint["checkpoint"] = {
        "state": "in_progress",
        "next_variant": completed_count + 1,
    }
    stage = (
        f"已验收 {completed_count}/{requested_count} 条，"
        f"正在制作第 {completed_count + 1} 条"
    )
    try:
        saved = store.update_running_result(
            run_id,
            checkpoint,
            stage=stage,
        )
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        append_log(
            "-> 已验收成片的重启恢复检查点暂时无法写入；"
            f"后续成片验收时会再试：{redact_local_paths(exc)}",
            run_id,
        )
        return False
    if saved:
        append_log(
            f"-> 已保存 {completed_count}/{requested_count} 条成片检查点；"
            "即使服务中断，这些已验收成片也不会丢。",
            run_id,
        )
    return bool(saved)


def pending_auto_save_metadata(directory):
    normalized = str(directory or "").strip()
    if not normalized:
        return {
            "enabled": False,
            "status": "off",
            "location_label": "",
            "folder_name": "",
            "files": [],
            "message": "未设置额外自动保存位置。",
        }
    tenant_message = (
        "成片已生成，正在准备当前账号的浏览器下载。"
        if TENANT_BACKEND_MODE
        else "成片已生成，正在复制到所选文件夹。"
    )
    return {
        "enabled": True,
        "status": "pending",
        "location_label": (
            "当前电脑" if TENANT_BACKEND_MODE else Path(normalized).name or "所选位置"
        ),
        "folder_name": "",
        "files": [],
        "message": tenant_message,
    }


def build_auto_save_artifact_manifest(
    run_id,
    config,
    result,
    source_overrides=None,
):
    if not re.fullmatch(r"[0-9a-f]{32}", str(run_id or "")):
        raise ValueError("任务编号无效，无法自动保存。")
    if not isinstance(config, dict) or not isinstance(result, dict):
        raise ValueError("任务保存信息不完整。")
    root = validate_auto_save_directory(
        config.get("auto_save_directory"),
        allow_legacy_tenant_root=True,
    )
    folder_scheme = int(config.get("auto_save_folder_scheme") or 0)
    direct_files = (
        folder_scheme >= 3
        or config.get("delivery_policy") == DELIVERY_POLICY_DIRECT_FILES_V3
    )
    if folder_scheme >= 2:
        folder_name = task_auto_save_folder_name(
            config.get("task_name"),
            run_id,
        )
    else:
        # Existing queued/finalizing jobs must keep their pre-upgrade target so
        # a restart remains idempotent and never publishes a second folder.
        folder_name = f"V17成片_{run_id}"
    destination_dir = root / folder_name
    if destination_dir.parent.resolve() != root:
        raise ValueError("自动保存位置校验失败。")

    artifacts = []
    kind = str(result.get("kind") or "")
    if direct_files:
        # New direct-delivery tasks may have already released their private
        # C-drive copy after a verified export.  Resolve the prior SHA-256
        # anchored export as a retry/move source instead of making the user
        # regenerate the video.  Explicit overrides are supplied by the batch
        # route before it changes the saved destination in the queue record.
        _spec_run_id, _spec_config, _spec_result, specs = _queue_delivery_specs(
            {"task_id": run_id, "config": config, "result": result},
            include_reports=True,
        )
        overrides = source_overrides if isinstance(source_overrides, dict) else {}
        exported = _validated_published_auto_save_files(run_id, config, result)
        sources = []
        for spec in specs:
            resolved_source = None
            override = overrides.get(spec["internal_name"])
            if override is not None:
                candidate = Path(override)
                try:
                    if (
                        not candidate.is_symlink()
                        and candidate.is_file()
                        and candidate.stat().st_size > 0
                    ):
                        resolved_source = candidate.resolve(strict=True)
                except OSError:
                    resolved_source = None
            if resolved_source is None:
                internal = Path(spec["root"]) / run_id / spec["internal_name"]
                resolved_source = _safe_internal_task_artifact(
                    internal,
                    spec["root"],
                    run_id,
                )
            if resolved_source is None:
                resolved_source = exported.get(spec["delivery_name"]) or exported.get(
                    spec["internal_name"]
                )
            if resolved_source is None:
                if spec.get("optional"):
                    continue
                raise FileNotFoundError(
                    f"等待自动保存的文件不存在：{spec['internal_name']}"
                )
            sources.append((Path(resolved_source), spec["delivery_name"]))
        if not sources:
            raise FileNotFoundError("没有可直接保存的成片文件。")
        source_dir = None
    elif kind == "single":
        source_dir = QUEUE_OUTPUT_ROOT / run_id
        sources = [
            (
                source_dir / "V17排队成片.mp4",
                delivery_video_name(config.get("task_name"), run_id)
                if direct_files
                else "V17排队成片.mp4",
            )
        ]
        optional_report = source_dir / "V17排队成片_合规报告.json"
        if optional_report.is_file():
            sources.append(
                (
                    optional_report,
                    delivery_report_name(
                        config.get("task_name"), run_id, fission=False
                    )
                    if direct_files
                    else optional_report.name,
                )
            )
    elif kind == "fission":
        source_dir = FISSION_OUTPUT_ROOT / run_id
        output_names = []
        for item in result.get("outputs") or []:
            name = item.get("name") if isinstance(item, dict) else ""
            if not isinstance(name, str) or Path(name).name != name:
                raise ValueError("裂变成片清单无效，无法自动保存。")
            output_names.append(name)
        if not output_names:
            raise ValueError("裂变成片清单为空，无法自动保存。")
        sources = [
            (
                source_dir / name,
                delivery_video_name(
                    config.get("task_name"), run_id, index=index
                )
                if direct_files
                else name,
            )
            for index, name in enumerate(output_names, 1)
        ]
        report_path = source_dir / "裂变相似度报告.json"
        sources.append(
            (
                report_path,
                delivery_report_name(
                    config.get("task_name"), run_id, fission=True
                )
                if direct_files
                else report_path.name,
            )
        )
        legacy_zip = source_dir / "V17页面裂变成片_同时间轴相似度40以下.zip"
        if not direct_files:
            sources.insert(-1, (legacy_zip, legacy_zip.name))
    else:
        raise ValueError("未知的成片类型，无法自动保存。")

    expected_root = source_dir.parent.resolve() if source_dir is not None else None
    destination_names = set()
    for source, destination_name in sources:
        if (
            not isinstance(destination_name, str)
            or Path(destination_name).name != destination_name
            or destination_name in destination_names
        ):
            raise ValueError("自动保存交付文件名无效。")
        destination_names.add(destination_name)
        if source.is_symlink():
            raise ValueError("成片文件校验失败，无法自动保存。")
        resolved_source = source.resolve(strict=True)
        if source_dir is None:
            if not resolved_source.is_file() or resolved_source.stat().st_size <= 0:
                raise FileNotFoundError(
                    f"等待自动保存的文件不存在：{source.name}"
                )
        elif (
            resolved_source.parent != source_dir.resolve()
            or source_dir.resolve().parent != expected_root
            or not resolved_source.is_file()
        ):
            raise FileNotFoundError(f"等待自动保存的文件不存在：{source.name}")
        destination = destination_dir / destination_name
        if destination.parent != destination_dir:
            raise ValueError("自动保存目标文件校验失败。")
        artifacts.append((resolved_source, destination))
    return destination_dir, artifacts


AUTO_SAVE_MANIFEST_NAME = ".v17-auto-save-manifest.json"


def _sha256_file(path, chunk_size=4 * 1024 * 1024):
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        while True:
            chunk = handle.read(chunk_size)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


# Exported files are immutable application artifacts.  A completed publish
# already hashes every byte, so later downloads can safely reuse that proof as
# long as the exact NTFS identity and timestamps still match.  This keeps five
# concurrent users from re-reading several gigabytes before the first download
# byte is sent, while any replacement or edit invalidates the cache.
PUBLISHED_EXPORT_VERIFICATION_CACHE_MAX_ENTRIES = 512
_published_export_verification_cache = OrderedDict()
_published_export_verification_cache_lock = threading.Lock()


def _published_export_file_signature(path, expected_size, expected_sha256):
    candidate = Path(path)
    if candidate.is_symlink():
        return None
    try:
        resolved = candidate.resolve(strict=True)
        metadata = resolved.stat()
    except OSError:
        return None
    if not resolved.is_file() or int(metadata.st_size) != int(expected_size):
        return None
    return (
        os.path.normcase(str(resolved)),
        int(getattr(metadata, "st_dev", 0) or 0),
        int(getattr(metadata, "st_ino", 0) or 0),
        int(metadata.st_size),
        int(getattr(metadata, "st_mtime_ns", 0) or 0),
        int(getattr(metadata, "st_ctime_ns", 0) or 0),
        str(expected_sha256 or "").lower(),
    )


def _verified_published_export_file(path, expected_size, expected_sha256):
    expected_sha256 = str(expected_sha256 or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_sha256):
        return None
    signature = _published_export_file_signature(
        path,
        expected_size,
        expected_sha256,
    )
    if signature is None:
        return None
    with _published_export_verification_cache_lock:
        cached = _published_export_verification_cache.get(signature)
        if cached is not None:
            _published_export_verification_cache.move_to_end(signature)
            return Path(cached)
    candidate = Path(signature[0])
    if not hmac.compare_digest(_sha256_file(candidate), expected_sha256):
        return None
    if _published_export_file_signature(
        candidate,
        expected_size,
        expected_sha256,
    ) != signature:
        return None
    with _published_export_verification_cache_lock:
        _published_export_verification_cache[signature] = str(candidate)
        _published_export_verification_cache.move_to_end(signature)
        while (
            len(_published_export_verification_cache)
            > PUBLISHED_EXPORT_VERIFICATION_CACHE_MAX_ENTRIES
        ):
            _published_export_verification_cache.popitem(last=False)
    return candidate


def _auto_save_manifest_digest(payload):
    encoded = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _auto_save_manifest_payload(run_id, artifacts):
    return {
        "version": 2,
        "task_id": str(run_id),
        "files": sorted(
            [
                {
                    "name": Path(destination).name,
                    "size_bytes": int(Path(source).stat().st_size),
                    "sha256": _sha256_file(source),
                }
                for source, destination in artifacts
            ],
            key=lambda item: item["name"],
        ),
    }


def _published_auto_save_paths(
    destination_dir,
    run_id,
    artifacts,
    expected_payload=None,
):
    destination_dir = Path(destination_dir)
    if not os.path.lexists(destination_dir):
        return None
    if _path_is_reparse_point(destination_dir) or not destination_dir.is_dir():
        raise FileExistsError(
            "同一任务的自动保存位置已被占用，系统没有覆盖任何内容。"
        )
    marker = destination_dir / AUTO_SAVE_MANIFEST_NAME
    try:
        if _path_is_reparse_point(marker) or not marker.is_file():
            raise OSError("自动保存清单不是普通文件")
        payload = json.loads(marker.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise FileExistsError(
            "同名成片文件夹已经存在，系统没有覆盖其中任何内容。"
        ) from exc
    expected = expected_payload or _auto_save_manifest_payload(run_id, artifacts)
    if payload != expected:
        raise FileExistsError(
            "同名成片文件夹已经存在，系统没有覆盖其中任何内容。"
        )
    expected_names = {AUTO_SAVE_MANIFEST_NAME}
    saved_paths = []
    expected_files = {
        entry["name"]: entry
        for entry in expected.get("files", [])
        if isinstance(entry, dict) and isinstance(entry.get("name"), str)
    }
    for _source, destination in artifacts:
        saved = destination_dir / Path(destination).name
        expected_entry = expected_files.get(saved.name, {})
        if (
            _path_is_reparse_point(saved)
            or not saved.is_file()
            or saved.stat().st_size != expected_entry.get("size_bytes")
            or _verified_published_export_file(
                saved,
                expected_entry.get("size_bytes"),
                expected_entry.get("sha256"),
            )
            is None
        ):
            raise FileExistsError("已有自动保存文件夹不完整，系统没有改动它。")
        expected_names.add(saved.name)
        saved_paths.append(saved)
    try:
        actual_names = {entry.name for entry in destination_dir.iterdir()}
    except OSError as exc:
        raise FileExistsError("已有自动保存文件夹无法校验。") from exc
    if actual_names != expected_names:
        raise FileExistsError("已有自动保存文件夹含有未知内容，系统没有改动它。")
    return saved_paths


def _fsync_directory(directory):
    descriptor = -1
    try:
        descriptor = os.open(
            directory,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        os.fsync(descriptor)
    except OSError:
        # Some network volumes and Windows do not allow directory fsync.  All
        # file contents have already been fsynced before publication.
        pass
    finally:
        if descriptor >= 0:
            os.close(descriptor)


def _atomic_publish_directory_no_replace(source, destination):
    source = Path(source)
    destination = Path(destination)
    if os.name == "nt":
        # Unlike POSIX rename, Windows MoveFile fails when the destination
        # already exists.  Keep the explicit check for a clear error and avoid
        # ctypes.CDLL(None), which is not a valid Windows library handle.
        if os.path.lexists(destination):
            raise FileExistsError(str(destination))
        os.rename(source, destination)
        return
    source_bytes = os.fsencode(source)
    destination_bytes = os.fsencode(destination)
    libc = ctypes.CDLL(None, use_errno=True)
    if sys.platform == "darwin" and hasattr(libc, "renamex_np"):
        rename_exclusive = 0x00000004
        result = libc.renamex_np(
            ctypes.c_char_p(source_bytes),
            ctypes.c_char_p(destination_bytes),
            ctypes.c_uint(rename_exclusive),
        )
        if result != 0:
            error_number = ctypes.get_errno()
            raise OSError(error_number, os.strerror(error_number), str(destination))
        return
    if sys.platform.startswith("linux") and hasattr(libc, "renameat2"):
        at_fdcwd = -100
        rename_noreplace = 1
        result = libc.renameat2(
            ctypes.c_int(at_fdcwd),
            ctypes.c_char_p(source_bytes),
            ctypes.c_int(at_fdcwd),
            ctypes.c_char_p(destination_bytes),
            ctypes.c_uint(rename_noreplace),
        )
        if result != 0:
            error_number = ctypes.get_errno()
            raise OSError(error_number, os.strerror(error_number), str(destination))
        return
    if os.path.lexists(destination):
        raise FileExistsError(str(destination))
    os.rename(source, destination)


def atomic_copy_artifact_set(
    destination_dir,
    artifacts,
    run_id,
    timeout_seconds=None,
):
    destination_dir = Path(destination_dir)
    artifacts = [(Path(source), Path(destination)) for source, destination in artifacts]
    if not artifacts:
        raise ValueError("没有可自动保存的成片文件。")
    root = destination_dir.parent.resolve(strict=True)
    if destination_dir.parent.resolve() != root:
        raise ValueError("自动保存位置校验失败。")
    manifest_payload = _auto_save_manifest_payload(run_id, artifacts)
    published = _published_auto_save_paths(
        destination_dir,
        run_id,
        artifacts,
        expected_payload=manifest_payload,
    )
    if published is not None:
        return published
    required_copy_bytes = sum(source.stat().st_size for source, _ in artifacts)
    ensure_additional_disk_space(
        root,
        required_copy_bytes + DISK_COPY_RESERVE_BYTES,
        "自动保存",
    )
    staging_dir = root / f".{destination_dir.name}.{uuid.uuid4().hex}.partial"
    staging_dir.mkdir(mode=0o700, parents=False, exist_ok=False)
    pairs = []
    for source, destination in artifacts:
        if destination.parent != destination_dir:
            raise ValueError("自动保存文件不属于同一任务目录。")
        pairs.append(
            {
                "source": str(source),
                "target": str(staging_dir / destination.name),
            }
        )
    copy_program = r"""
import json
import os
import shutil
import sys

for item in json.loads(sys.argv[1]):
    source = item["source"]
    target = item["target"]
    with open(source, "rb") as source_handle, open(target, "xb") as target_handle:
        shutil.copyfileobj(source_handle, target_handle, length=8 * 1024 * 1024)
        target_handle.flush()
        os.fsync(target_handle.fileno())
    try:
        shutil.copystat(source, target)
    except OSError:
        pass
"""
    timeout = float(timeout_seconds or AUTO_SAVE_COPY_TIMEOUT_SECONDS)
    published_successfully = False
    try:
        try:
            completed = subprocess.run(
                [
                    sys.executable or "python3",
                    "-c",
                    copy_program,
                    json.dumps(pairs, ensure_ascii=False, separators=(",", ":")),
                ],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="ignore",
                timeout=timeout,
            )
        except subprocess.TimeoutExpired as exc:
            raise TimeoutError(
                f"复制超过 {timeout / 60:.0f} 分钟，已停止自动保存；系统成片仍保留。"
            ) from exc
        if completed.returncode != 0:
            detail = (completed.stderr or completed.stdout or "复制失败").strip()[-400:]
            raise OSError(detail)
        expected_files = {
            entry["name"]: entry for entry in manifest_payload["files"]
        }
        for source, destination in artifacts:
            staged = staging_dir / destination.name
            expected_entry = expected_files.get(destination.name, {})
            if (
                staged.is_symlink()
                or not staged.is_file()
                or staged.stat().st_size != expected_entry.get("size_bytes")
                or not hmac.compare_digest(
                    _sha256_file(staged),
                    str(expected_entry.get("sha256") or ""),
                )
            ):
                raise OSError(f"{source.name} 复制后校验失败")
        marker = staging_dir / AUTO_SAVE_MANIFEST_NAME
        with marker.open("x", encoding="utf-8") as handle:
            json.dump(
                manifest_payload,
                handle,
                ensure_ascii=False,
                separators=(",", ":"),
            )
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        _fsync_directory(staging_dir)
        with auto_save_publish_lock:
            published = _published_auto_save_paths(
                destination_dir,
                run_id,
                artifacts,
                expected_payload=manifest_payload,
            )
            if published is not None:
                return published
            _atomic_publish_directory_no_replace(staging_dir, destination_dir)
            published_successfully = True
        _fsync_directory(root)
        return [destination_dir / destination.name for _source, destination in artifacts]
    finally:
        if (
            not published_successfully
            and staging_dir.parent.resolve() == root
            and staging_dir.name.endswith(".partial")
            and staging_dir.is_dir()
            and not _path_is_reparse_point(staging_dir)
        ):
            shutil.rmtree(staging_dir)


def best_effort_auto_save_task(
    run_id,
    config,
    result,
    source_overrides=None,
):
    directory = str((config or {}).get("auto_save_directory") or "").strip()
    if not directory:
        return pending_auto_save_metadata("")
    try:
        _pin_task_output_placement(run_id, config, result)
        directory = str(config.get("auto_save_directory") or "")
        destination_dir, artifacts = build_auto_save_artifact_manifest(
            run_id,
            config,
            result,
            source_overrides=source_overrides,
        )
        saved_paths = atomic_copy_artifact_set(
            destination_dir,
            artifacts,
            run_id,
        )
        manifest_payload = json.loads(
            (destination_dir / AUTO_SAVE_MANIFEST_NAME).read_text(encoding="utf-8")
        )
        if (
            manifest_payload.get("version") != 2
            or manifest_payload.get("task_id") != str(run_id)
        ):
            raise OSError("自动保存完整性清单无效。")
        metadata = {
            "enabled": True,
            "status": "saved",
            "manifest_version": 2,
            "manifest_sha256": _auto_save_manifest_digest(manifest_payload),
            "location_label": (
                "当前电脑"
                if TENANT_BACKEND_MODE
                else Path(directory).name or "所选位置"
            ),
            "folder_name": destination_dir.name,
            "files": [path.name for path in saved_paths],
            "message": (
                f"已准备 {len(saved_paths)} 个文件，可从任务记录保存到当前电脑；"
                "服务器副本只按临时交付期限保留。"
                if TENANT_BACKEND_MODE
                else f"已按任务名直接保存 {len(saved_paths)} 个独立文件，无需解压。"
            ),
        }
        append_log(
            (
                f"-> 成片已进入当前账号临时交付缓存：{destination_dir.name}"
                if TENANT_BACKEND_MODE
                else f"-> 成片已自动保存：{destination_dir.name}"
            ),
            run_id,
        )
        return metadata
    except Exception as exc:
        detail = redact_local_paths(exc, directory)
        append_log(
            (
                f"-> 当前账号临时交付缓存准备未完成：{detail}。"
                "应用内成片仍安全保留，可稍后保存到当前电脑。"
                if TENANT_BACKEND_MODE
                else f"-> 自动保存到所选文件夹未完成：{detail}。"
                "系统成片仍安全保留，可手动下载。"
            ),
            run_id,
        )
        return {
            "enabled": True,
            "status": "failed",
            "location_label": (
                "当前电脑"
                if TENANT_BACKEND_MODE
                else Path(directory).name or "所选位置"
            ),
            "folder_name": "",
            "files": [],
            "message": (
                f"临时交付准备未完成：{detail}"
                if TENANT_BACKEND_MODE
                else f"自动保存未完成：{detail}"
            ),
        }


def _validated_published_auto_save_files(
    run_id,
    config,
    result,
    required_names=None,
    verify_hash=True,
):
    """Return requested manifest-verified exports, keyed by delivered name.

    ``required_names`` is trusted server-generated data.  Metadata for the
    complete manifest is still validated, but only files needed by the current
    response are opened.  Normal downloads trust the SQLite-anchored manifest,
    immutable path, file identity and exact size so streaming can start at once.
    Publishing, moving and destructive cleanup keep ``verify_hash=True`` and
    therefore still prove every byte before changing or deleting anything.
    """
    metadata = result.get("auto_save") if isinstance(result, dict) else None
    if not isinstance(metadata, dict) or metadata.get("status") != "saved":
        return {}
    try:
        root = validate_auto_save_directory(
            (config or {}).get("auto_save_directory"),
            verify_write=False,
            allow_legacy_tenant_root=True,
        )
    except ValueError:
        return {}
    folder_name = str(metadata.get("folder_name") or "")
    if not folder_name or Path(folder_name).name != folder_name:
        return {}
    destination_dir = root / folder_name
    try:
        if (
            _path_is_reparse_point(destination_dir)
            or destination_dir.resolve(strict=True).parent != root
            or not destination_dir.is_dir()
        ):
            return {}
        marker = destination_dir / AUTO_SAVE_MANIFEST_NAME
        if _path_is_reparse_point(marker) or not marker.is_file():
            return {}
        payload = json.loads(marker.read_text(encoding="utf-8"))
        manifest_digest = str(metadata.get("manifest_sha256") or "").lower()
        if (
            payload.get("version") != 2
            or payload.get("task_id") != str(run_id)
            or metadata.get("manifest_version") != 2
            or not re.fullmatch(r"[0-9a-f]{64}", manifest_digest)
            or not hmac.compare_digest(
                _auto_save_manifest_digest(payload),
                manifest_digest,
            )
        ):
            return {}
        raw_files = payload.get("files")
        if not isinstance(raw_files, list) or not raw_files:
            return {}
        requested = None
        if required_names is not None:
            requested = {
                str(name)
                for name in required_names
                if isinstance(name, str) and Path(name).name == name
            }
            if not requested:
                return {}
        manifest_entries = {}
        for entry in raw_files:
            name = entry.get("name") if isinstance(entry, dict) else None
            size_bytes = entry.get("size_bytes") if isinstance(entry, dict) else None
            sha256 = entry.get("sha256") if isinstance(entry, dict) else None
            if (
                not isinstance(name, str)
                or Path(name).name != name
                or name in manifest_entries
                or not isinstance(size_bytes, int)
                or size_bytes <= 0
                or not isinstance(sha256, str)
                or not re.fullmatch(r"[0-9a-f]{64}", sha256)
            ):
                return {}
            manifest_entries[name] = {
                "size_bytes": size_bytes,
                "sha256": sha256,
            }
        actual_names = {entry.name for entry in destination_dir.iterdir()}
        if actual_names != {AUTO_SAVE_MANIFEST_NAME, *manifest_entries.keys()}:
            return {}
        verified = {}
        names_to_verify = (
            set(manifest_entries)
            if requested is None
            else set(manifest_entries).intersection(requested)
        )
        for name in names_to_verify:
            entry = manifest_entries[name]
            candidate = destination_dir / name
            if (
                _path_is_reparse_point(candidate)
                or candidate.resolve(strict=True).parent != destination_dir
                or not candidate.is_file()
                or candidate.stat().st_size != entry["size_bytes"]
            ):
                return {}
            resolved = (
                _verified_published_export_file(
                    candidate,
                    entry["size_bytes"],
                    entry["sha256"],
                )
                if verify_hash
                else candidate.resolve(strict=True)
            )
            if resolved is None:
                return {}
            verified[name] = resolved
        return verified
    except (OSError, UnicodeError, ValueError, TypeError, json.JSONDecodeError):
        return {}


def _safe_internal_task_artifact(path, root, run_id):
    candidate = Path(path)
    try:
        resolved_root = Path(root).resolve(strict=True)
        task_dir = resolved_root / str(run_id)
        if task_dir.is_symlink() or task_dir.resolve(strict=True).parent != resolved_root:
            return None
        if candidate.is_symlink() or candidate.resolve(strict=True).parent != task_dir:
            return None
        if not candidate.is_file() or candidate.stat().st_size <= 0:
            return None
        return candidate
    except OSError:
        return None


def _queue_delivery_specs(item, include_reports=True):
    """Describe internal names and customer-facing names without opening files."""
    if not isinstance(item, dict):
        raise ValueError("任务记录无效。")
    run_id = str(item.get("task_id") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", run_id):
        raise ValueError("任务编号无效。")
    config = item.get("config") if isinstance(item.get("config"), dict) else {}
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    task_name = config.get("task_name") or item.get("title") or "视频制作任务"
    kind = str(result.get("kind") or "")
    specs = []
    if kind == "single":
        specs.append(
            {
                "role": "video",
                "root": QUEUE_OUTPUT_ROOT,
                "internal_name": "V17排队成片.mp4",
                "delivery_name": delivery_video_name(task_name, run_id),
                "mimetype": "video/mp4",
            }
        )
        if include_reports:
            specs.append(
                {
                    "role": "report",
                    "root": QUEUE_OUTPUT_ROOT,
                    "internal_name": "V17排队成片_合规报告.json",
                    "delivery_name": delivery_report_name(
                        task_name, run_id, fission=False
                    ),
                    "mimetype": "application/json",
                    "optional": True,
                }
            )
    elif kind == "fission":
        outputs = result.get("outputs")
        if not isinstance(outputs, list) or not outputs:
            raise ValueError("裂变成片清单为空。")
        for position, output in enumerate(outputs, 1):
            if not isinstance(output, dict):
                raise ValueError("裂变成片清单无效。")
            try:
                index = int(output.get("index") or position)
            except (TypeError, ValueError) as exc:
                raise ValueError("裂变成片序号无效。") from exc
            expected_name = f"V17裂变成片_第{index:02d}条.mp4"
            raw_name = str(output.get("name") or expected_name)
            if index not in range(1, 6) or raw_name != expected_name:
                raise ValueError("裂变成片清单无效。")
            specs.append(
                {
                    "role": "video",
                    "index": index,
                    "root": FISSION_OUTPUT_ROOT,
                    "internal_name": expected_name,
                    "delivery_name": delivery_video_name(
                        task_name, run_id, index=index
                    ),
                    "mimetype": "video/mp4",
                }
            )
        if include_reports:
            specs.append(
                {
                    "role": "report",
                    "root": FISSION_OUTPUT_ROOT,
                    "internal_name": "裂变相似度报告.json",
                    "delivery_name": delivery_report_name(
                        task_name, run_id, fission=True
                    ),
                    "mimetype": "application/json",
                    "optional": True,
                }
            )
    else:
        raise ValueError("任务没有可交付成片。")
    return run_id, config, result, specs


def queue_delivery_artifacts(item, include_reports=True, internal_names=None):
    """Resolve each task artifact from managed storage or a verified export."""
    run_id, config, result, specs = _queue_delivery_specs(
        item, include_reports=include_reports
    )
    if internal_names is not None:
        selected_names = {
            str(name)
            for name in internal_names
            if isinstance(name, str) and Path(name).name == name
        }
        specs = [spec for spec in specs if spec["internal_name"] in selected_names]
    internal_artifacts = {}
    missing_specs = []
    for spec in specs:
        internal_path = Path(spec["root"]) / run_id / spec["internal_name"]
        resolved = _safe_internal_task_artifact(
            internal_path,
            spec["root"],
            run_id,
        )
        if resolved is None:
            missing_specs.append(spec)
        else:
            internal_artifacts[spec["internal_name"]] = resolved
    required_export_names = {
        name
        for spec in missing_specs
        for name in (spec["internal_name"], spec["delivery_name"])
    }
    exported = (
        _validated_published_auto_save_files(
            run_id,
            config,
            result,
            required_names=required_export_names,
            verify_hash=False,
        )
        if required_export_names
        else {}
    )
    artifacts = []
    for spec in specs:
        resolved = internal_artifacts.get(spec["internal_name"])
        source = "internal"
        if resolved is None:
            resolved = exported.get(spec["delivery_name"]) or exported.get(
                spec["internal_name"]
            )
            source = "auto_save"
        if resolved is None:
            if spec.get("optional"):
                continue
            raise FileNotFoundError(spec["internal_name"])
        artifact = dict(spec)
        artifact.update({"path": Path(resolved), "source": source})
        artifacts.append(artifact)
    return artifacts


def queue_delivery_artifact(item, role, index=None):
    """Resolve one requested artifact without hashing its unrequested siblings."""
    _run_id, _config, _result, specs = _queue_delivery_specs(
        item,
        include_reports=True,
    )
    target = next(
        spec
        for spec in specs
        if spec.get("role") == role
        and (index is None or int(spec.get("index") or 0) == int(index))
    )
    artifacts = queue_delivery_artifacts(
        item,
        include_reports=True,
        internal_names={target["internal_name"]},
    )
    return next(
        artifact
        for artifact in artifacts
        if artifact["internal_name"] == target["internal_name"]
    )


def release_internal_delivery_copies(item):
    """Release C-drive copies only after every primary file is export-verified."""
    run_id, config, result, specs = _queue_delivery_specs(item, include_reports=True)
    if config.get("delivery_policy") != DELIVERY_POLICY_DIRECT_FILES_V3:
        return 0
    exported = _validated_published_auto_save_files(run_id, config, result)
    required_specs = [spec for spec in specs if not spec.get("optional")]
    if not required_specs or any(
        spec["delivery_name"] not in exported
        and spec["internal_name"] not in exported
        for spec in required_specs
    ):
        return 0

    released = 0
    roots = set()
    # Keep the same lock order as retention GC.  Holding the task gate while
    # the internal copies are examined closes the route-lookup/send_file gap:
    # an already-started browser download wins, while a later one can resolve
    # the verified export after this short cleanup finishes.
    with output_download_active_lock:
        if int(output_download_active_tasks.get(run_id, 0)) > 0:
            return 0
        with storage_cleanup_lock:
            # Validate and remove a legacy ZIP while its sibling primaries still
            # exist; after the MP4s move out, the byte-for-byte proof is no longer
            # available locally.
            legacy_zip = (
                FISSION_OUTPUT_ROOT
                / run_id
                / "V17页面裂变成片_同时间轴相似度40以下.zip"
            )
            if safe_redundant_fission_zip(legacy_zip):
                try:
                    released += legacy_zip.stat().st_size
                    legacy_zip.unlink()
                except OSError:
                    pass
            for spec in specs:
                if (
                    spec["delivery_name"] not in exported
                    and spec["internal_name"] not in exported
                ):
                    # Never remove an optional report (or any future artifact)
                    # unless that exact file is part of the SQLite-anchored,
                    # SHA-256-verified export.
                    continue
                root = Path(spec["root"])
                roots.add(root)
                internal = _safe_internal_task_artifact(
                    root / run_id / spec["internal_name"], root, run_id
                )
                if internal is None:
                    continue
                try:
                    released += internal.stat().st_size
                    internal.unlink()
                except OSError:
                    pass
            for root in roots:
                run_dir = root / run_id
                try:
                    run_dir.rmdir()
                except OSError:
                    pass
    storage_scan_cache["checked_monotonic"] = 0.0
    return released


def _has_internal_delivery_copy(item):
    """Cheaply skip already-settled rows before hashing their saved exports."""
    try:
        run_id, _config, _result, specs = _queue_delivery_specs(
            item,
            include_reports=True,
        )
    except (OSError, TypeError, ValueError):
        return False
    return any(
        _safe_internal_task_artifact(
            Path(spec["root"]) / run_id / spec["internal_name"],
            spec["root"],
            run_id,
        )
        is not None
        for spec in specs
    )


def _saved_auto_save_records(
    store,
    task_id=None,
    *,
    owner_user_id=None,
    tenant_id=None,
):
    """Read completed direct saves inside an optional authenticated scope."""
    owner_user_id, tenant_id = _normalized_cleanup_scope(
        owner_user_id,
        tenant_id,
    )
    if task_id is not None:
        if owner_user_id is not None:
            getter = getattr(store, "get_owned", None)
            if getter is None:
                return []
            item = getter(
                owner_user_id,
                str(task_id),
                include_config=True,
                tenant_id=tenant_id,
            )
            candidates = [item] if isinstance(item, dict) else []
        else:
            # Trusted legacy maintenance deliberately retains unscoped lookup
            # semantics, including existing NULL-owner rows.
            getter = getattr(store, "get_internal", None) or getattr(
                store,
                "get",
                None,
            )
            if getter is None:
                return []
            item = getter(str(task_id), include_config=True)
            candidates = [item] if isinstance(item, dict) else []
    else:
        database_path = Path(getattr(store, "database_path", ""))
        if not database_path.is_file():
            return []
        query = (
            "SELECT task_id, status, title, config_json, result_json "
            "FROM task_queue"
        )
        parameters = []
        if owner_user_id is not None:
            query += " WHERE owner_user_id=?"
            parameters.append(owner_user_id)
            if tenant_id is not None:
                query += " AND tenant_id=?"
                parameters.append(tenant_id)
        query += " ORDER BY sequence ASC"
        with sqlite3.connect(str(database_path), timeout=5.0) as connection:
            connection.row_factory = sqlite3.Row
            connection.execute("PRAGMA busy_timeout=5000")
            rows = connection.execute(query, tuple(parameters)).fetchall()
        candidates = []
        for row in rows:
            try:
                config = json.loads(str(row["config_json"] or "{}"))
                result = json.loads(str(row["result_json"] or "{}"))
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if not isinstance(config, dict) or not isinstance(result, dict):
                continue
            candidates.append(
                {
                    "task_id": str(row["task_id"]),
                    "status": str(row["status"]),
                    "title": str(row["title"] or ""),
                    "config": config,
                    "result": result,
                }
            )

    saved = []
    for item in candidates:
        config = item.get("config") if isinstance(item, dict) else None
        result = item.get("result") if isinstance(item, dict) else None
        auto_save = result.get("auto_save") if isinstance(result, dict) else None
        if (
            isinstance(config, dict)
            and config.get("delivery_policy") == DELIVERY_POLICY_DIRECT_FILES_V3
            and isinstance(auto_save, dict)
            and auto_save.get("status") == "saved"
            and _has_internal_delivery_copy(item)
        ):
            saved.append(item)
    return saved


def best_effort_release_saved_internal_outputs(
    store,
    task_id=None,
    run_id=None,
    *,
    owner_user_id=None,
    tenant_id=None,
):
    """Idempotently release only externally hash-verified duplicate outputs."""
    released = 0
    examined = 0
    failures = 0
    try:
        records = _saved_auto_save_records(
            store,
            task_id=task_id,
            owner_user_id=owner_user_id,
            tenant_id=tenant_id,
        )
    except (OSError, sqlite3.Error, TypeError, ValueError):
        records = []
        failures += 1
    for item in records:
        examined += 1
        try:
            released += int(release_internal_delivery_copies(item) or 0)
        except (OSError, TypeError, ValueError):
            # A missing, changed, or unverifiable external copy must leave the
            # internal primary untouched.  A later maintenance pass may retry.
            failures += 1
    if run_id and released:
        append_log(
            "-> 已逐文件校验外部保存副本并释放应用内重复成片 "
            f"{format_gib(released)}；外部副本异常时不会删除内部成片。",
            run_id,
        )
    return {
        "released_bytes": released,
        "examined_count": examined,
        "failure_count": failures,
    }


_bundle_cache_thread_locks_guard = threading.RLock()
_bundle_cache_thread_locks = {}
_bundle_cache_active_guard = threading.RLock()
_bundle_cache_active_paths = {}


def _validated_bundle_cache_root(create=True, export_root=None):
    root = TENANT_EXPORT_ROOT if export_root is None else export_root
    if TENANT_BACKEND_MODE:
        import storage_roots
        root = storage_roots.validate_tenant_output_root(
            root, TENANT_USER_ID, require_exists=not create, **_storage_root_options())
        if create:
            root = _ensure_tenant_export_root(root)
    else:
        root = Path(root).resolve(strict=not create)
        if create:
            root = _ensure_plain_directory_tree(root, "整包缓存根目录")
    cache = root / BUNDLE_DOWNLOAD_CACHE_DIR_NAME
    if create:
        cache = _ensure_plain_directory_tree(cache, "整包缓存目录")
    elif not cache.is_dir():
        raise OSError("整包缓存目录不存在")
    if (_path_is_reparse_point(cache) or cache.resolve(strict=True).parent != root
            or cache.name != BUNDLE_DOWNLOAD_CACHE_DIR_NAME):
        raise OSError("整包缓存目录越界")
    return cache.resolve(strict=True)


def _bundle_member_identity(path):
    metadata = path.stat()
    return {
        "path": os.path.normcase(str(path)),
        "size": int(metadata.st_size),
        "mtime_ns": int(metadata.st_mtime_ns),
        "ctime_ns": int(metadata.st_ctime_ns),
        "device": int(getattr(metadata, "st_dev", 0) or 0),
        "inode": int(getattr(metadata, "st_ino", 0) or 0),
    }


def _normalized_bundle_members(artifacts):
    normalized = []
    names = set()
    for artifact in artifacts:
        path = Path(artifact.get("path")) if isinstance(artifact, dict) else None
        name = artifact.get("delivery_name") if isinstance(artifact, dict) else None
        if (
            path is None
            or not isinstance(name, str)
            or PurePosixPath(name).name != name
            or "\\" in name
            or "/" in name
            or "\x00" in name
            or sanitize_windows_task_folder_name(name, maximum_units=180) != name
            or name in names
            or path.is_symlink()
        ):
            raise ValueError("批量下载文件清单无效。")
        resolved = path.resolve(strict=True)
        if resolved.is_symlink() or not resolved.is_file():
            raise ValueError("批量下载文件清单无效。")
        identity = _bundle_member_identity(resolved)
        if identity["size"] <= 0:
            raise ValueError("批量下载文件清单无效。")
        names.add(name)
        normalized.append((resolved, name, identity))
    if not normalized:
        raise ValueError("没有可下载的成片。")
    return normalized


def _bundle_cache_key(cache_scope, normalized):
    scope = str(cache_scope or "").strip()
    # 100 validated task IDs need 3305 characters ("batch:" + comma list).
    # Keep the bound, but do not reject valid batches starting at task 31.
    if not scope or len(scope) > 4096:
        raise ValueError("整包下载任务标识无效。")
    payload = {
        "version": 1,
        "tenant_user_id": TENANT_USER_ID,
        "scope": scope,
        "members": [
            {"name": name, **identity}
            for _path, name, identity in normalized
        ],
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _bundle_cache_thread_lock(lock_path):
    key = os.path.normcase(str(lock_path))
    with _bundle_cache_thread_locks_guard:
        lock = _bundle_cache_thread_locks.get(key)
        if lock is None:
            lock = threading.Lock()
            _bundle_cache_thread_locks[key] = lock
        return lock


def _open_bundle_cache_file_lock(lock_path, *, blocking=True):
    descriptor = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        if os.fstat(descriptor).st_size < 1:
            os.write(descriptor, b"\0")
            os.fsync(descriptor)
        os.lseek(descriptor, 0, os.SEEK_SET)
        if _fcntl is not None:
            flags = _fcntl.LOCK_EX | (0 if blocking else _fcntl.LOCK_NB)
            _fcntl.flock(descriptor, flags)
            return descriptor
        if _msvcrt is not None:
            mode = _msvcrt.LK_NBLCK
            deadline = time.monotonic() + (
                BUNDLE_DOWNLOAD_CACHE_LOCK_WAIT_SECONDS if blocking else 0.0
            )
            while True:
                try:
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    _msvcrt.locking(descriptor, mode, 1)
                    return descriptor
                except OSError:
                    if not blocking or time.monotonic() >= deadline:
                        raise
                    time.sleep(0.1)
        raise OSError("当前系统不支持整包缓存文件锁。")
    except BaseException:
        os.close(descriptor)
        raise


def _close_bundle_cache_file_lock(descriptor):
    try:
        os.lseek(descriptor, 0, os.SEEK_SET)
        if _fcntl is not None:
            _fcntl.flock(descriptor, _fcntl.LOCK_UN)
        elif _msvcrt is not None:
            _msvcrt.locking(descriptor, _msvcrt.LK_UNLCK, 1)
    finally:
        os.close(descriptor)


def _mark_bundle_cache_active(path):
    key = os.path.normcase(str(path))
    with _bundle_cache_active_guard:
        _bundle_cache_active_paths[key] = int(
            _bundle_cache_active_paths.get(key, 0)
        ) + 1


def _release_bundle_cache_active(path):
    key = os.path.normcase(str(path))
    with _bundle_cache_active_guard:
        remaining = int(_bundle_cache_active_paths.get(key, 0)) - 1
        if remaining > 0:
            _bundle_cache_active_paths[key] = remaining
        else:
            _bundle_cache_active_paths.pop(key, None)


def _bundle_cache_path_is_active(path):
    key = os.path.normcase(str(path))
    with _bundle_cache_active_guard:
        return int(_bundle_cache_active_paths.get(key, 0)) > 0


def _cached_bundle_is_valid(path, normalized):
    try:
        if path.is_symlink() or not path.is_file() or path.stat().st_size <= 0:
            return False
        expected = {name: identity["size"] for _source, name, identity in normalized}
        with zipfile.ZipFile(path) as archive:
            members = archive.infolist()
            return bool(
                len(members) == len(expected)
                and {item.filename for item in members} == set(expected)
                and all(
                    not item.is_dir()
                    and not item.flag_bits & 0x1
                    and PurePosixPath(item.filename).name == item.filename
                    and int(item.file_size) == int(expected[item.filename])
                    for item in members
                )
            )
    except (OSError, ValueError, KeyError, zipfile.BadZipFile):
        return False


def _build_cached_bundle_zip(normalized, partial_path, final_path):
    required_bytes = sum(identity["size"] for _path, _name, identity in normalized)
    ensure_additional_disk_space(
        partial_path.parent,
        required_bytes + 16 * MIB_BYTES,
        "整包下载缓存",
    )
    # Never overwrite an unfinished package from an earlier attempt.
    if os.path.lexists(partial_path):
        partial_path = partial_path.with_name(
            partial_path.stem + "." + uuid.uuid4().hex + ".partial"
        )
    try:
        with zipfile.ZipFile(
            partial_path,
            mode="x",
            compression=zipfile.ZIP_STORED,
            allowZip64=True,
        ) as archive:
            for source, name, identity in normalized:
                if _bundle_member_identity(source) != identity:
                    raise OSError("整包源文件在缓存生成前发生变化。")
                archive.write(source, arcname=name)
                if _bundle_member_identity(source) != identity:
                    raise OSError("整包源文件在缓存生成期间发生变化。")
        with partial_path.open("r+b") as completed:
            os.fsync(completed.fileno())
        if not _cached_bundle_is_valid(partial_path, normalized):
            raise OSError("整包缓存完整性检查失败。")
        os.replace(partial_path, final_path)
    except BaseException:
        # Operator policy: preserve unfinished packaging for later inspection.
        raise


def prepare_bundle_download_cache(artifacts, cache_scope):
    """Atomically prepare one resumable ZIP in this tenant's export folder."""
    normalized = _normalized_bundle_members(artifacts)
    cache_root = _validated_bundle_cache_root(create=True, export_root=(
        _select_new_export_root() if TENANT_BACKEND_MODE else None))
    cache_key = _bundle_cache_key(cache_scope, normalized)
    final_path = cache_root / f"bundle-{cache_key}.zip"
    partial_path = cache_root / f"bundle-{cache_key}.partial"
    lock_path = cache_root / f"bundle-{cache_key}.lock"
    thread_lock = _bundle_cache_thread_lock(lock_path)
    with thread_lock:
        descriptor = _open_bundle_cache_file_lock(lock_path, blocking=True)
        _mark_bundle_cache_active(final_path)
        _mark_bundle_cache_active(partial_path)
        try:
            if not _cached_bundle_is_valid(final_path, normalized):
                final_path.unlink(missing_ok=True)
                _build_cached_bundle_zip(normalized, partial_path, final_path)
            if not _cached_bundle_is_valid(final_path, normalized):
                raise OSError("整包下载缓存不可用。")
            return final_path
        finally:
            _release_bundle_cache_active(partial_path)
            _release_bundle_cache_active(final_path)
            _close_bundle_cache_file_lock(descriptor)


def _cleanup_one_bundle_download_cache(now=None, export_root=None):
    """Collect expired owned ZIPs; download EOF never shortens 48h retention."""
    try:
        cache_root = _validated_bundle_cache_root(create=False, export_root=export_root)
    except OSError:
        return {"released_bytes": 0, "removed_count": 0}
    if not cache_root.is_dir() or cache_root.is_symlink():
        return {"released_bytes": 0, "removed_count": 0}
    released = 0
    removed = 0
    for candidate in cache_root.iterdir():
        if (
            candidate.is_symlink()
            or not re.fullmatch(r"bundle-[0-9a-f]{64}\.zip", candidate.name)
            or _bundle_cache_path_is_active(candidate)
        ):
            continue
        try:
            metadata = candidate.stat()
            if not bundle_ready_for_cleanup(candidate, TENANT_USER_ID, now=now):
                continue
            lock_path = candidate.with_suffix(".lock")
            descriptor = _open_bundle_cache_file_lock(lock_path, blocking=False)
        except OSError:
            continue
        try:
            if _bundle_cache_path_is_active(candidate):
                continue
            current = candidate.stat()
            if not bundle_ready_for_cleanup(candidate, TENANT_USER_ID, now=now):
                continue
            candidate.unlink()
            candidate.with_suffix(".json").unlink(missing_ok=True)
            released += int(current.st_size)
            removed += 1
        except OSError:
            pass
        finally:
            _close_bundle_cache_file_lock(descriptor)
    return {"released_bytes": released, "removed_count": removed}


def cleanup_bundle_download_cache(now=None):
    totals = {"released_bytes": 0, "removed_count": 0}
    roots = _allowed_tenant_export_roots(existing_only=True) if TENANT_BACKEND_MODE else (None,)
    for root in roots:
        try:
            result = _cleanup_one_bundle_download_cache(now=now, export_root=root)
            for key in totals:
                totals[key] += int(result.get(key) or 0)
        except (OSError, RuntimeError, ValueError):
            continue
    return totals


def _delete_completed_bundle_cache(cache_path):
    """Delete exactly one fully delivered inactive ZIP, never a broad path."""

    try:
        cache_root = _validated_bundle_cache_root(
            create=False, export_root=Path(cache_path).parent.parent).resolve()
        candidate = Path(cache_path)
        if candidate.is_symlink():
            return False
        candidate = candidate.resolve(strict=True)
        if (
            candidate.parent != cache_root
            or not re.fullmatch(r"bundle-[0-9a-f]{64}\.zip", candidate.name)
            or _bundle_cache_path_is_active(candidate)
        ):
            return False
        descriptor = _open_bundle_cache_file_lock(
            candidate.with_suffix(".lock"),
            blocking=False,
        )
    except (OSError, RuntimeError):
        return False
    try:
        if _bundle_cache_path_is_active(candidate) or not bundle_ready_for_cleanup(candidate, TENANT_USER_ID):
            return False
        candidate.unlink()
        candidate.with_suffix(".json").unlink(missing_ok=True)
        return True
    except OSError:
        return False
    finally:
        _close_bundle_cache_file_lock(descriptor)


def _validated_delivery_lease_root(create=True):
    """Return the tenant-local task lease directory without following links."""
    root = _ensure_tenant_export_root()
    lease_root = root / BUNDLE_DELIVERY_LEASE_DIR_NAME
    if lease_root.is_symlink():
        raise OSError("成片下载租约目录不能使用链接或重解析目录。")
    if create:
        lease_root.mkdir(parents=False, exist_ok=True)
    resolved = lease_root.resolve(strict=create)
    if resolved.parent != root or resolved.name != BUNDLE_DELIVERY_LEASE_DIR_NAME:
        raise OSError("成片下载租约目录越界。")
    if create:
        metadata = os.lstat(resolved)
        attributes = int(getattr(metadata, "st_file_attributes", 0))
        if resolved.is_symlink() or attributes & 0x400 or not resolved.is_dir():
            raise OSError("成片下载租约目录不安全。")
    return resolved


def _delivery_task_lease_path(task_id, *, create_root=True):
    task_id = str(task_id or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", task_id):
        raise ValueError("成片下载租约任务编号无效。")
    root = _validated_delivery_lease_root(create=create_root)
    path = root / f"{task_id}.lock"
    if path.parent != root or path.name != f"{task_id}.lock":
        raise OSError("成片下载租约路径越界。")
    return path


def _open_delivery_task_lease(task_id, *, blocking=False):
    """Create/open and lock one exact task lease using the shared protocol."""
    path = _delivery_task_lease_path(task_id, create_root=True)
    try:
        descriptor = _open_bundle_cache_file_lock(path, blocking=blocking)
    except OSError as exc:
        if not blocking and (
            exc.errno in {errno.EACCES, errno.EAGAIN}
            or getattr(exc, "winerror", None) in {33, 36}
        ):
            return None
        raise
    if descriptor is None:
        return None
    try:
        metadata = os.lstat(path)
        attributes = int(getattr(metadata, "st_file_attributes", 0))
        resolved = path.resolve(strict=True)
        if (
            path.is_symlink()
            or attributes & 0x400
            or not path.is_file()
            or resolved.parent != path.parent
            or resolved.name != path.name
            or int(metadata.st_size) < 1
        ):
            raise OSError("成片下载租约文件不安全。")
    except BaseException:
        _close_bundle_cache_file_lock(descriptor)
        raise
    return descriptor


def _ensure_delivery_task_lease_file(task_id):
    """Best-effort pre-create a succeeded task's stable cross-process lease."""
    try:
        descriptor = _open_delivery_task_lease(task_id, blocking=False)
    except (OSError, RuntimeError, TypeError, ValueError):
        return False
    if descriptor is None:
        # A busy lock proves the exact ordinary lock file already exists.
        return True
    _close_bundle_cache_file_lock(descriptor)
    return True


def _output_download_path_key(path):
    candidate = Path(path)
    try:
        normalized = candidate.resolve(strict=False)
    except OSError:
        normalized = candidate.absolute()
    return os.path.normcase(str(normalized))


def _mark_output_download_paths(paths):
    keys = tuple(dict.fromkeys(_output_download_path_key(path) for path in paths))
    with output_download_active_lock:
        for key in keys:
            output_download_active_paths[key] = int(
                output_download_active_paths.get(key, 0)
            ) + 1
    return keys


def _release_output_download_paths(keys):
    with output_download_active_lock:
        for key in keys:
            remaining = int(output_download_active_paths.get(key, 0)) - 1
            if remaining > 0:
                output_download_active_paths[key] = remaining
            else:
                output_download_active_paths.pop(key, None)


def _output_download_path_is_active(path):
    key = _output_download_path_key(path)
    with output_download_active_lock:
        return int(output_download_active_paths.get(key, 0)) > 0


def _mark_output_download_tasks(task_ids):
    keys = tuple(
        dict.fromkeys(
            str(task_id).strip().lower()
            for task_id in task_ids
            if re.fullmatch(r"[0-9a-f]{32}", str(task_id).strip().lower())
        )
    )
    acquired = []
    with output_download_active_lock:
        try:
            for key in keys:
                current = int(output_download_active_tasks.get(key, 0))
                if current <= 0:
                    descriptor = _open_delivery_task_lease(key, blocking=False)
                    if descriptor is None:
                        raise OSError("成片正在执行清理，请稍后重试下载。")
                    output_download_task_lease_descriptors[key] = descriptor
                output_download_active_tasks[key] = current + 1
                acquired.append(key)
        except BaseException:
            for key in reversed(acquired):
                remaining = int(output_download_active_tasks.get(key, 0)) - 1
                if remaining > 0:
                    output_download_active_tasks[key] = remaining
                    continue
                output_download_active_tasks.pop(key, None)
                descriptor = output_download_task_lease_descriptors.pop(key, None)
                if descriptor is not None:
                    _close_bundle_cache_file_lock(descriptor)
            raise
    return keys


def _release_output_download_tasks(keys):
    with output_download_active_lock:
        for key in keys:
            remaining = int(output_download_active_tasks.get(key, 0)) - 1
            if remaining > 0:
                output_download_active_tasks[key] = remaining
            else:
                output_download_active_tasks.pop(key, None)
                descriptor = output_download_task_lease_descriptors.pop(key, None)
                if descriptor is not None:
                    _close_bundle_cache_file_lock(descriptor)


def _guard_output_download_response(task_ids, response_factory):
    """Protect task outputs before resolving paths and until response close.

    The normal file senders also protect their exact paths.  This earlier,
    task-level guard closes the small gap where retention GC could otherwise
    move an expired task folder after route lookup began but before ``send_file``
    registered the path as active.
    """
    active_task_keys = _mark_output_download_tasks(task_ids)
    released = [False]

    def release_guard():
        if released[0]:
            return
        released[0] = True
        _release_output_download_tasks(active_task_keys)
        store = get_task_queue_store(create=False)
        if store is not None:
            schedule_bounded_retention_maintenance(store)

    try:
        response = response_factory()
    except BaseException:
        release_guard()
        raise
    response.call_on_close(release_guard)
    # send_file passthrough otherwise bypasses Response.close under real WSGI.
    # This still streams; it only ensures ClosingIterator releases the leases.
    response.direct_passthrough = False
    return response


def _release_client_save_guard(guard):
    _release_output_download_tasks(guard)
    store = get_task_queue_store(create=False)
    if store is not None:
        schedule_bounded_retention_maintenance(store)


client_save_sessions = ClientSaveSessions(
    _mark_output_download_tasks, _release_client_save_guard,
)


def _record_completed_download_receipts(receipts):
    """Best-effort durable receipt; a database outage never breaks a download."""
    store = get_task_queue_store(create=False)
    recorder = getattr(store, "record_completed_download", None) if store else None
    if recorder is None:
        return False
    completed_at = time.strftime("%Y-%m-%d %H:%M:%S")
    scope = _current_cleanup_scope_kwargs()
    recorded = False
    for task_id, artifact_keys in receipts:
        normalized_keys = list(
            dict.fromkeys(
                str(key)
                for key in artifact_keys
                if isinstance(key, str) and Path(key).name == key
            )
        )
        if not normalized_keys:
            continue
        try:
            recorded = bool(
                recorder(
                    str(task_id),
                    normalized_keys,
                    completed_at=completed_at,
                    **scope,
                )
            ) or recorded
        except (OSError, sqlite3.Error, TypeError, ValueError):
            continue
    if recorded:
        # Natural EOF records a complete server-side transfer, not proof of
        # a physical disk save. HEAD, partial Range and aborted streams never
        # create receipts. Normal cleanup also waits for all task files.
        schedule_bounded_retention_maintenance(store)
    return recorded


class _CompletedDownloadIterable:
    """Call a receipt hook only after an exact, natural EOF was iterated."""

    def __init__(self, iterable, expected_bytes, on_complete):
        self._iterable = iterable
        self._expected_bytes = int(expected_bytes)
        self._on_complete = on_complete
        self._sent_bytes = 0
        self._completed = False

    def __iter__(self):
        try:
            for chunk in self._iterable:
                self._sent_bytes += len(chunk)
                yield chunk
        except BaseException:
            raise
        else:
            if (
                not self._completed
                and self._expected_bytes > 0
                and self._sent_bytes == self._expected_bytes
            ):
                self._completed = True
                try:
                    self._on_complete()
                except Exception:
                    pass

    def close(self):
        closer = getattr(self._iterable, "close", None)
        if closer is not None:
            closer()


def _track_complete_get_response(
    response,
    expected_bytes,
    receipts,
    *,
    on_complete=None,
):
    """HEAD, Range/206 and interrupted responses deliberately create no receipt."""
    # Required even for HEAD/Range/abort: WSGI iterable.close must run callbacks.
    response.direct_passthrough = False
    if (
        request.method != "GET"
        or int(response.status_code) != 200
        or bool(request.headers.get("Range"))
        or int(expected_bytes or 0) <= 0
        or (not receipts and on_complete is None)
    ):
        return response

    def record_complete():
        try:
            if receipts:
                _record_completed_download_receipts(receipts)
        finally:
            if on_complete is not None:
                on_complete()

    response.response = _CompletedDownloadIterable(
        response.response,
        int(expected_bytes),
        record_complete,
    )
    return response


def _send_tracked_artifact(artifact, task_id, *, record_completion=True):
    path = Path(artifact["path"])
    role = str(artifact.get("role") or "").strip().lower()
    suffix = path.suffix.lower()
    mimetype = str(artifact.get("mimetype") or "").strip()
    if not mimetype:
        if role == "report" or suffix == ".json":
            mimetype = "application/json"
        elif suffix == ".zip":
            mimetype = "application/zip"
        elif suffix == ".mp4":
            mimetype = "video/mp4"
        elif suffix == ".txt":
            mimetype = "text/plain; charset=utf-8"
        else:
            mimetype = "application/octet-stream"
    delivery_name = str(artifact.get("delivery_name") or path.name)
    artifact_key = str(artifact.get("internal_name") or "").strip()
    completion_receipts = []
    if (
        record_completion
        and role != "report"
        and suffix == ".mp4"
        and artifact_key
        and Path(artifact_key).name == artifact_key
    ):
        completion_receipts = [(str(task_id), [artifact_key])]
    active_keys = _mark_output_download_paths((path,))
    active_task_keys = _mark_output_download_tasks((task_id,))
    try:
        expected_bytes = int(path.stat().st_size)
        response = send_file(
            path,
            as_attachment=True,
            download_name=delivery_name,
            mimetype=mimetype,
            conditional=True,
            etag=True,
            max_age=0,
        )
    except BaseException:
        _release_output_download_paths(active_keys)
        _release_output_download_tasks(active_task_keys)
        raise
    response.headers["Cache-Control"] = "no-store"
    response.headers.setdefault("Accept-Ranges", "bytes")
    response.headers["X-Content-Type-Options"] = "nosniff"
    released = [False]

    def release_active_download():
        if released[0]:
            return
        released[0] = True
        _release_output_download_paths(active_keys)
        _release_output_download_tasks(active_task_keys)
        store = get_task_queue_store(create=False)
        if store is not None:
            # The exact-EOF receipt is written while this response still owns
            # the active-download guard.  Queue another bounded pass after the
            # guard is released so immediate retention cannot lose that wakeup.
            schedule_bounded_retention_maintenance(store)

    response.call_on_close(release_active_download)
    return _track_complete_get_response(
        response,
        expected_bytes,
        completion_receipts,
    )


def _persist_bundle_ownership(cache_path, receipts, *, completed=False):
    """Best effort sidecar for the existing daily worker and retry collector."""
    if not receipts:
        return
    descriptor = None
    try:
        deadlines = []
        store = get_task_queue_store(create=False)
        for task_id, _keys in receipts:
            item = _public_queue_get(store, task_id) if store is not None else None
            finished = _task_asset_finished_epoch(item.get("finished_at")) if isinstance(item, dict) else None
            if finished is None or str(item.get("status") or "") not in {"succeeded", "failed", "timed_out", "interrupted", "review_required"}:
                deadlines = []
                break
            deadlines.append(finished + OUTPUT_COMPLETED_RETENTION_SECONDS)
        descriptor = _open_bundle_cache_file_lock(
            Path(cache_path).with_suffix(".lock"), blocking=False,
        )
        write_bundle_receipt(
            cache_path, TENANT_USER_ID,
            [task_id for task_id, _keys in receipts], completed=completed,
            retain_until_epoch=max(deadlines) if deadlines else None,
        )
    except (OSError, ValueError, TypeError, AttributeError, sqlite3.Error):
        # Metadata failure must not break transfer or permit unsafe deletion.
        pass
    finally:
        if descriptor is not None:
            _close_bundle_cache_file_lock(descriptor)


def cached_zip_response(
    artifacts,
    download_name,
    cache_scope,
    completion_receipts=None,
    *,
    record_completion=True,
    on_transfer_complete=None,
):
    """Serve a D-drive cached ZIP with length, Range and browser resume support."""
    completion_receipts = list(completion_receipts or [])
    active_task_keys = _mark_output_download_tasks(
        task_id for task_id, _artifact_keys in completion_receipts
    )
    cleanup_bundle_download_cache()
    source_active_keys = _mark_output_download_paths(
        artifact["path"] for artifact in artifacts
    )
    try:
        cache_path = prepare_bundle_download_cache(artifacts, cache_scope)
    except BaseException:
        _release_output_download_tasks(active_task_keys)
        raise
    finally:
        _release_output_download_paths(source_active_keys)
    safe_name = sanitize_windows_task_folder_name(
        str(download_name or "快手成片.zip"), maximum_units=150
    )
    if not safe_name.lower().endswith(".zip"):
        safe_name += ".zip"
    _mark_bundle_cache_active(cache_path)
    try:
        _persist_bundle_ownership(cache_path, completion_receipts)
        expected_bytes = int(cache_path.stat().st_size)
        response = send_file(
            cache_path,
            as_attachment=True,
            download_name=safe_name,
            mimetype="application/zip",
            conditional=True,
            etag=True,
            max_age=0,
        )
    except BaseException:
        _release_bundle_cache_active(cache_path)
        _release_output_download_tasks(active_task_keys)
        raise
    response.headers["Cache-Control"] = "no-store"
    response.headers.setdefault("Accept-Ranges", "bytes")
    response.headers["X-Content-Type-Options"] = "nosniff"
    released = [False]
    response._client_save_cache_path = cache_path

    def mark_complete():
        if record_completion:
            _persist_bundle_ownership(cache_path, completion_receipts, completed=True)
        if on_transfer_complete is not None:
            on_transfer_complete(cache_path)

    def release_active_download():
        if released[0]:
            return
        released[0] = True
        _release_bundle_cache_active(cache_path)
        _release_output_download_tasks(active_task_keys)
        # Any reader may be last: a prior completed reader's durable receipt
        # survives concurrent readers, aborts and a later backend restart.
        _delete_completed_bundle_cache(cache_path)
        store = get_task_queue_store(create=False)
        if store is not None:
            # Exact EOF runs before response close.  Re-run after both the ZIP
            # and task guards are gone so zero-retention output cleanup can win.
            schedule_bounded_retention_maintenance(store)

    response.call_on_close(release_active_download)
    return _track_complete_get_response(
        response,
        expected_bytes,
        completion_receipts if record_completion else [],
        on_complete=mark_complete,
    )


def _output_retention_deadline(item):
    from delivery_handoff_guard import cleanup_allowed
    if not cleanup_allowed(item):
        return None
    """Return a conservative deadline, or None when metadata is incomplete."""
    if not isinstance(item, dict):
        return None
    if str(item.get("output_retention_state") or "") == "expired":
        return None
    try:
        _run_id, _config, _result, specs = _queue_delivery_specs(
            item,
            include_reports=False,
        )
    except (TypeError, ValueError):
        return None
    required_keys = [
        spec["internal_name"] for spec in specs if spec.get("role") == "video"
    ]
    if not required_keys:
        return None
    # Queue submission time and server-side transfer receipts must not start
    # or shorten the user's two-day retrieval window.
    if str(item.get("status") or "") not in {"succeeded", "failed", "timed_out", "interrupted", "review_required"}:
        return None
    finished_epoch = _task_asset_finished_epoch(item.get("finished_at"))
    return None if finished_epoch is None else finished_epoch + OUTPUT_COMPLETED_RETENTION_SECONDS


def _managed_output_destination(item):
    """Resolve only the exact current tenant/task folder; never a broad path."""
    if not TENANT_BACKEND_MODE or not TENANT_USER_ID or not isinstance(item, dict):
        raise ValueError("当前实例没有可自动回收的租户成片目录。")
    run_id = str(item.get("task_id") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", run_id):
        raise ValueError("任务编号无效。")
    config = item.get("config") if isinstance(item.get("config"), dict) else {}
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    metadata = result.get("auto_save") if isinstance(result, dict) else None
    if (
        config.get("delivery_policy") != DELIVERY_POLICY_DIRECT_FILES_V3
        or int(config.get("auto_save_folder_scheme") or 0) < 3
        or not isinstance(metadata, dict)
        or metadata.get("status") != "saved"
    ):
        raise ValueError("任务不是当前受控的独立文件交付。")
    root = validate_auto_save_directory(config.get("auto_save_directory"), verify_write=False)
    configured_root = Path(
        os.path.abspath(str(config.get("auto_save_directory") or ""))
    )
    if configured_root != Path(os.path.abspath(str(root))):
        raise ValueError("任务成片目录不属于当前租户。")
    expected_name = task_auto_save_folder_name(config.get("task_name"), run_id)
    if metadata.get("folder_name") != expected_name:
        raise ValueError("任务成片文件夹与数据库记录不一致。")
    destination = root / expected_name
    if destination.parent != root or destination.name != expected_name:
        raise ValueError("任务成片文件夹越界。")
    return run_id, root, destination, config, result


def _strict_managed_output_set(item):
    run_id, root, destination, config, result = _managed_output_destination(item)
    if (
        _path_is_reparse_point(destination)
        or destination.resolve(strict=True).parent != root
        or not destination.is_dir()
    ):
        raise ValueError("任务成片文件夹不可验证。")
    # Publishing already SHA-256-anchored every byte in the durable manifest.
    # Retention cleanup revalidates that signed manifest, the exact tenant/task
    # directory, complete name set, file identity/size and all reparse guards.
    # Do not reread several GiB here: that would compete with active renderers
    # and recreate the former multi-user download stall immediately before an
    # already-authorized, atomic tombstone move.
    verified = _validated_published_auto_save_files(
        run_id,
        config,
        result,
        verify_hash=False,
    )
    _spec_run_id, _spec_config, _spec_result, specs = _queue_delivery_specs(
        item,
        include_reports=False,
    )
    required_specs = [spec for spec in specs if spec.get("role") == "video"]
    if not required_specs or any(
        spec["delivery_name"] not in verified
        and spec["internal_name"] not in verified
        for spec in required_specs
    ):
        raise ValueError("必需成片未通过完整性校验。")
    paths = tuple(dict.fromkeys(Path(path) for path in verified.values()))
    if not paths or any(path.parent != destination for path in paths):
        raise ValueError("任务成片清单越界。")
    return run_id, root, destination, paths


def _output_gc_root(root):
    root = Path(root).resolve(strict=True)
    gc_root = _ensure_plain_directory_tree(root / ".v17_output_gc", "成片回收目录")
    if gc_root.parent != root or gc_root.name != ".v17_output_gc":
        raise RuntimeError("成片回收目录越界。")
    return gc_root


def _recover_one_storage_root(store, records, export_root, max_candidates=1):
    """Finish only DB-expired tombstones; otherwise restore the exact folder."""
    if not TENANT_BACKEND_MODE:
        return 0
    try:
        root = _ensure_tenant_export_root(export_root)
        gc_root = _output_gc_root(root)
    except (OSError, RuntimeError, ValueError):
        return 0
    by_task_id = {
        str(item.get("task_id") or ""): item
        for item in records
        if isinstance(item, dict)
    }
    handled = 0
    for tombstone in sorted(gc_root.iterdir(), key=lambda path: path.name):
        match = re.fullmatch(
            r"([0-9a-f]{32})\.([0-9a-f]{32})\.deleting",
            tombstone.name,
        )
        if (
            not match
            or tombstone.is_symlink()
            or not tombstone.is_dir()
            or tombstone.resolve(strict=True).parent != gc_root
        ):
            continue
        item = by_task_id.get(match.group(1))
        if not isinstance(item, dict):
            getter = getattr(store, "get_owned", None)
            if getter is not None:
                try:
                    item = getter(
                        TENANT_USER_ID,
                        match.group(1),
                        include_config=True,
                        tenant_id=TENANT_ID,
                    )
                except (OSError, sqlite3.Error, TypeError, ValueError):
                    item = None
        if not isinstance(item, dict):
            continue
        try:
            _run_id, _root, destination, _config, _result = (
                _managed_output_destination(item)
            )
            if _root != root:
                continue
            if str(item.get("output_retention_state") or "") == "expired":
                from delivery_handoff_guard import cleanup_allowed
                if not cleanup_allowed(item):
                    continue
                shutil.rmtree(tombstone)
            elif not os.path.lexists(destination):
                os.replace(tombstone, destination)
            else:
                continue
            handled += 1
        except (OSError, RuntimeError, TypeError, ValueError):
            continue
        if handled >= max(0, int(max_candidates)):
            break
    return handled


def _recover_output_gc_tombstones(store, records, max_candidates=1):
    if not TENANT_BACKEND_MODE:
        return 0
    remaining = max(0, int(max_candidates))
    handled = 0
    for root in _allowed_tenant_export_roots(existing_only=True):
        if remaining <= 0:
            break
        count = _recover_one_storage_root(store, records, root, max_candidates=remaining)
        remaining -= count
        handled += count
    return handled


def _expire_managed_output_record(
    store,
    item,
    now_epoch,
    *,
    marker_method="mark_output_expired",
    reason="output_retention_expired",
    finished_cutoff_at=None,
):
    deadline = _output_retention_deadline(item)
    if deadline is None or float(now_epoch) < deadline:
        return False
    run_id, root, destination, paths = _strict_managed_output_set(item)
    marker = getattr(store, str(marker_method), None)
    if marker is None:
        return False
    gc_root = _output_gc_root(root)
    tombstone = gc_root / f"{run_id}.{uuid.uuid4().hex}.deleting"
    if tombstone.resolve(strict=False).parent != gc_root:
        return False
    moved = False
    lease_descriptor = None
    try:
        with output_download_active_lock:
            if int(output_download_active_tasks.get(run_id, 0)) > 0 or any(
                int(
                    output_download_active_paths.get(
                        _output_download_path_key(path), 0
                    )
                )
                > 0
                for path in paths
            ):
                return False
            lease_descriptor = _open_delivery_task_lease(
                run_id,
                blocking=False,
            )
            if lease_descriptor is None:
                return False
            # Keep both the process-local guard and the cross-process lease
            # through the atomic move.  No new response can resolve this task
            # between the last activity check and its tombstone transition.
            with storage_cleanup_lock:
                os.replace(destination, tombstone)
                moved = True
        scope = _current_cleanup_scope_kwargs()
        if finished_cutoff_at is not None:
            scope["finished_cutoff_at"] = str(finished_cutoff_at)
        try:
            marked = bool(
                marker(
                    run_id,
                    expired_at=time.strftime(
                        "%Y-%m-%d %H:%M:%S",
                        time.localtime(float(now_epoch)),
                    ),
                    reason=str(reason),
                    **scope,
                )
            )
        except (OSError, sqlite3.Error, TypeError, ValueError):
            marked = False
        if not marked:
            if moved:
                try:
                    with storage_cleanup_lock:
                        if tombstone.is_dir() and not os.path.lexists(destination):
                            os.replace(tombstone, destination)
                except OSError:
                    pass
            return False
        try:
            shutil.rmtree(tombstone)
        except FileNotFoundError:
            pass
        except OSError:
            # DB state is already expired.  A later bounded pass may finish
            # this exact task-id tombstone without touching any other folder.
            pass
        storage_scan_cache["checked_monotonic"] = 0.0
        return True
    finally:
        if lease_descriptor is not None:
            _close_bundle_cache_file_lock(lease_descriptor)


def best_effort_expire_task_outputs(store, *, max_deletions=1, now=None):
    """Bounded, tenant-scoped final-output retention collector (fail closed)."""
    lister = getattr(store, "list_output_retention_candidates", None)
    marker = getattr(store, "mark_output_expired", None)
    if lister is None or marker is None or not TENANT_BACKEND_MODE:
        return {"expired_count": 0, "examined_count": 0, "failure_count": 0}
    scope = _current_cleanup_scope_kwargs()
    try:
        records = lister(limit=OUTPUT_RETENTION_SCAN_LIMIT, **scope)
    except (OSError, sqlite3.Error, TypeError, ValueError):
        return {"expired_count": 0, "examined_count": 0, "failure_count": 1}
    if not isinstance(records, list):
        return {"expired_count": 0, "examined_count": 0, "failure_count": 1}
    _recover_output_gc_tombstones(
        store,
        records,
        max_candidates=max_deletions,
    )
    try:
        now_epoch = float(time.time() if now is None else now)
        delete_limit = max(0, int(max_deletions))
    except (TypeError, ValueError, OverflowError):
        return {"expired_count": 0, "examined_count": 0, "failure_count": 1}
    expired = 0
    examined = 0
    failures = 0
    for item in records:
        if expired >= delete_limit:
            break
        if not isinstance(item, dict):
            continue
        deadline = _output_retention_deadline(item)
        if deadline is None or now_epoch < deadline:
            continue
        examined += 1
        try:
            if _expire_managed_output_record(store, item, now_epoch):
                expired += 1
        except (OSError, RuntimeError, TypeError, ValueError):
            failures += 1
    return {
        "expired_count": expired,
        "examined_count": examined,
        "failure_count": failures,
    }


def best_effort_force_expire_succeeded_outputs(
    store,
    *,
    max_deletions=DAILY_COMPLETED_OUTPUT_CLEANUP_DELETE_LIMIT,
    now=None,
    finished_cutoff_at=None,
):
    """Delete only exact ``succeeded`` outputs during the daily big sweep.

    This is deliberately stricter than the ordinary terminal-retention path.
    Failed, timed-out, interrupted, skipped, canceled and review-required rows
    may still carry retry/settlement evidence, so they are never eligible.
    Waiting/running/finalizing rows (including a paused running task) are not
    returned by the store's terminal query and are also rejected by the final
    atomic database marker.
    """
    lister = getattr(
        store,
        "list_daily_succeeded_output_cleanup_candidates",
        None,
    )
    marker = getattr(store, "force_mark_output_expired", None)
    if lister is None or marker is None or not TENANT_BACKEND_MODE:
        return {
            "expired_count": 0,
            "candidate_count": 0,
            "examined_count": 0,
            "blocked_count": 0,
            "failure_count": 0,
        }
    try:
        records = lister(
            limit=OUTPUT_RETENTION_SCAN_LIMIT,
            finished_cutoff_at=finished_cutoff_at,
            **_current_cleanup_scope_kwargs(),
        )
        now_epoch = float(time.time() if now is None else now)
        delete_limit = max(0, int(max_deletions))
    except (OSError, sqlite3.Error, TypeError, ValueError, OverflowError):
        return {
            "expired_count": 0,
            "candidate_count": 0,
            "examined_count": 0,
            "blocked_count": 0,
            "failure_count": 1,
        }
    if not isinstance(records, list):
        return {
            "expired_count": 0,
            "candidate_count": 0,
            "examined_count": 0,
            "blocked_count": 0,
            "failure_count": 1,
        }
    _recover_output_gc_tombstones(
        store,
        records,
        max_candidates=max(1, delete_limit),
    )
    candidates = [
        item
        for item in records
        if isinstance(item, dict)
        and str(item.get("status") or "") == "succeeded"
        and str(item.get("output_retention_state") or "") != "expired"
        and _output_retention_deadline(item) is not None
        and _output_retention_deadline(item) <= now_epoch
    ]
    expired = 0
    examined = 0
    blocked = 0
    failures = 0
    for item in candidates:
        if expired >= delete_limit:
            break
        examined += 1
        try:
            if _expire_managed_output_record(
                store,
                item,
                now_epoch,
                marker_method="force_mark_output_expired",
                reason="daily_1800_succeeded_output_cleanup",
                finished_cutoff_at=finished_cutoff_at,
            ):
                expired += 1
            else:
                # An active browser download deliberately keeps its exact task
                # and path guard.  Leave it in place and retry the due sweep.
                blocked += 1
        except (OSError, RuntimeError, TypeError, ValueError):
            failures += 1
    return {
        "expired_count": expired,
        "candidate_count": len(candidates),
        "examined_count": examined,
        "blocked_count": blocked,
        "failure_count": failures,
    }


def _next_daily_completed_cleanup_text(now_epoch, *, force_next_day=False):
    """Return the next local-wall-clock 18:00, DST/restart safe."""
    local_now = datetime.fromtimestamp(float(now_epoch))
    target_date = local_now.date()
    if force_next_day or local_now.time() >= datetime_time(
        DAILY_COMPLETED_OUTPUT_CLEANUP_LOCAL_HOUR,
        0,
        0,
    ):
        target_date += timedelta(days=1)
    target = datetime.combine(
        target_date,
        datetime_time(DAILY_COMPLETED_OUTPUT_CLEANUP_LOCAL_HOUR, 0, 0),
    )
    return target.strftime("%Y-%m-%d %H:%M:%S")


def run_daily_completed_output_cleanup_if_due(store, *, now=None):
    """Drain one durable local-18:00 cycle without deleting queue records."""
    state_reader = getattr(store, "daily_completed_output_cleanup_state", None)
    state_writer = getattr(
        store,
        "complete_daily_completed_output_cleanup",
        None,
    )
    if state_reader is None or state_writer is None or not TENANT_BACKEND_MODE:
        return {"due": False, "completed": False, "failure_count": 0}
    try:
        now_epoch = float(time.time() if now is None else now)
        now_text = time.strftime(
            "%Y-%m-%d %H:%M:%S",
            time.localtime(now_epoch),
        )
        initial_due_at = DAILY_COMPLETED_OUTPUT_CLEANUP_FIRST_DUE_AT
    except (TypeError, ValueError, OverflowError):
        return {"due": False, "completed": False, "failure_count": 1}
    if not daily_completed_output_cleanup_lock.acquire(blocking=False):
        return {
            "due": True,
            "completed": False,
            "busy": True,
            "failure_count": 0,
        }
    total_expired = 0
    try:
        try:
            state = state_reader(
                now=now_text,
                initial_due_at=initial_due_at,
            )
        except (OSError, sqlite3.Error, RuntimeError, TypeError, ValueError):
            return {"due": False, "completed": False, "failure_count": 1}
        if not isinstance(state, dict) or not state.get("due"):
            return {
                "due": False,
                "completed": False,
                "next_due_at": state.get("next_due_at")
                if isinstance(state, dict)
                else None,
                "failure_count": 0,
            }
        cycle_cutoff_at = str(state.get("next_due_at") or "").strip()
        if not cycle_cutoff_at:
            return {"due": True, "completed": False, "failure_count": 1}

        def complete_cycle(**details):
            try:
                completed_state = state_writer(
                    completed_at=now_text,
                    next_due_at=_next_daily_completed_cleanup_text(now_epoch),
                )
            except (
                OSError,
                sqlite3.Error,
                RuntimeError,
                TypeError,
                ValueError,
            ):
                return {
                    "due": True,
                    "completed": False,
                    "expired_count": total_expired,
                    "failure_count": 1,
                }
            return {
                "due": True,
                "completed": True,
                "expired_count": total_expired,
                "next_due_at": completed_state.get("next_due_at"),
                "failure_count": int(details.pop("failure_count", 0) or 0),
                **details,
            }
        while not task_queue_shutdown_event.is_set():
            result = best_effort_force_expire_succeeded_outputs(
                store,
                max_deletions=DAILY_COMPLETED_OUTPUT_CLEANUP_DELETE_LIMIT,
                now=now_epoch,
                finished_cutoff_at=cycle_cutoff_at,
            )
            total_expired += int(result.get("expired_count", 0) or 0)
            if int(result.get("failure_count", 0) or 0) > 0:
                return complete_cycle(
                    deferred_to_next_cycle=True,
                    failure_count=int(result["failure_count"]),
                )
            candidate_count = int(result.get("candidate_count", 0) or 0)
            expired_count = int(result.get("expired_count", 0) or 0)
            if candidate_count <= 0:
                return complete_cycle()
            if expired_count <= 0:
                # Busy downloads and fail-closed validation remain intact and
                # are reconsidered only at the next day's 18:00 cycle.
                return complete_cycle(
                    deferred_to_next_cycle=True,
                    blocked_count=int(result.get("blocked_count", 0) or 0),
                )
            if task_queue_shutdown_event.wait(timeout=0.05):
                break
        return {
            "due": True,
            "completed": False,
            "expired_count": total_expired,
            "failure_count": 0,
        }
    finally:
        daily_completed_output_cleanup_lock.release()


def schedule_bounded_retention_maintenance(store):
    """Coalesce bounded sweeps without losing an EOF or close wakeup.

    A download receipt is recorded before the response-close callbacks release
    the task/path guards.  Multiple downloads can also reach EOF while an older
    sweep is still running.  The pending counter makes both cases durable at
    process scope: the single worker keeps taking bounded passes until every
    wakeup observed while it was busy has received a later pass.
    """
    global bounded_retention_maintenance_pending
    global bounded_retention_maintenance_running
    if store is None:
        return False
    with bounded_retention_maintenance_lock:
        bounded_retention_maintenance_pending += 1
        if bounded_retention_maintenance_running:
            return True
        bounded_retention_maintenance_running = True

    def run_maintenance():
        global bounded_retention_maintenance_pending
        global bounded_retention_maintenance_running
        try:
            while True:
                with bounded_retention_maintenance_lock:
                    # Coalesce everything already pending into this pass.  Any
                    # EOF/close arriving afterwards increments it again and is
                    # therefore guaranteed another pass.
                    bounded_retention_maintenance_pending = 0
                best_effort_reclaim_task_asset_sets(
                    store,
                    max_candidates=1,
                    **_current_cleanup_scope_kwargs(),
                )
                output_result = best_effort_expire_task_outputs(
                    store,
                    max_deletions=OUTPUT_RETENTION_TERMINAL_DELETE_LIMIT,
                )
                cleanup_bundle_download_cache()
                with bounded_retention_maintenance_lock:
                    # Hitting the deletion bound means another due output may
                    # remain even without a second receipt racing this pass.
                    if int(output_result.get("expired_count", 0) or 0) >= int(
                        OUTPUT_RETENTION_TERMINAL_DELETE_LIMIT
                    ):
                        bounded_retention_maintenance_pending += 1
                    if bounded_retention_maintenance_pending <= 0:
                        bounded_retention_maintenance_running = False
                        return
        finally:
            restart = False
            with bounded_retention_maintenance_lock:
                if bounded_retention_maintenance_running:
                    bounded_retention_maintenance_running = False
                    restart = bounded_retention_maintenance_pending > 0
            if restart:
                schedule_bounded_retention_maintenance(store)

    try:
        thread = threading.Thread(
            target=run_maintenance,
            name="v17-bounded-retention-maintenance",
            daemon=True,
        )
        thread.start()
    except BaseException:
        with bounded_retention_maintenance_lock:
            bounded_retention_maintenance_running = False
        return False
    return True


def streaming_zip_response(artifacts, download_name, cache_scope="legacy"):
    """Compatibility name retained for callers; responses are now file-backed."""
    return cached_zip_response(artifacts, download_name, cache_scope)


def _tree_size_bytes(root):
    root = Path(root)
    if root.is_symlink() or not root.exists():
        return 0
    total = 0
    stack = [root]
    while stack:
        current = stack.pop()
        try:
            with os.scandir(current) as entries:
                for entry in entries:
                    try:
                        if entry.is_symlink():
                            continue
                        if entry.is_dir(follow_symlinks=False):
                            stack.append(Path(entry.path))
                        elif entry.is_file(follow_symlinks=False):
                            total += int(entry.stat(follow_symlinks=False).st_size)
                    except OSError:
                        continue
        except (NotADirectoryError, OSError):
            try:
                if current.is_file() and not current.is_symlink():
                    total += current.stat().st_size
            except OSError:
                pass
    return total


def _quick_redundant_zip_candidate(path):
    """Cheap estimate for the UI; destructive cleanup performs CRC validation."""
    zip_path = Path(path)
    try:
        if zip_path.is_symlink() or not zip_path.is_file():
            return False
        report_path = zip_path.parent / "裂变相似度报告.json"
        report = json.loads(report_path.read_text(encoding="utf-8"))
        outputs = report.get("outputs") if isinstance(report, dict) else None
        if not isinstance(outputs, list) or not outputs:
            return False
        expected = {report_path.name: report_path.stat().st_size}
        for name in outputs:
            if not isinstance(name, str) or Path(name).name != name:
                return False
            candidate = zip_path.parent / name
            if candidate.is_symlink() or not candidate.is_file():
                return False
            expected[name] = candidate.stat().st_size
        with zipfile.ZipFile(zip_path) as archive:
            members = archive.infolist()
            return (
                len(members) == len(expected)
                and {item.filename for item in members} == set(expected)
                and all(
                    not item.is_dir()
                    and not item.flag_bits & 0x1
                    and PurePosixPath(item.filename).name == item.filename
                    and item.file_size == expected[item.filename]
                    for item in members
                )
            )
    except (OSError, UnicodeError, ValueError, TypeError, zipfile.BadZipFile):
        return False


def _managed_partial_candidates(now=None):
    cutoff = float(now if now is not None else time.time()) - STORAGE_STALE_SECONDS
    candidates = []

    def is_owned_temporary(relative_path, root):
        parts = relative_path.parts
        name = parts[-1]
        if root == Path(TASK_ASSET_ROOT):
            if (
                len(parts) == 3
                and parts[0] in {"drafts", "sets"}
                and re.fullmatch(r"[0-9a-f]{32}", parts[1])
            ):
                return name == ".manifest.partial"
            return bool(
                len(parts) == 4
                and parts[0] == "drafts"
                and re.fullmatch(r"[0-9a-f]{32}", parts[1])
                and parts[2] == ".dynamic_previews"
                and re.fullmatch(r"\.[0-9a-f]{32}\.partial\.mp4", name)
            )
        if len(parts) < 2 or not re.fullmatch(r"[0-9a-f]{32}", parts[0]):
            return False
        if root == Path(QUEUE_OUTPUT_ROOT):
            return len(parts) == 2 and (
                name
                in {
                    "V17排队成片.mp4.partial.mp4",
                    "V17排队成片_合规报告.json.partial",
                }
                or bool(re.fullmatch(r"\.v16-contract-[A-Za-z0-9_-]+\.mp4", name))
            )
        if root != Path(FISSION_OUTPUT_ROOT):
            return False
        if len(parts) == 2:
            return (
                name
                in {
                    "裂变相似度报告.partial.json",
                }
                or bool(
                    re.fullmatch(
                        r"\.裂变候选_[0-9]{2}_尝试_[0-9]{2}\.mp4\.partial\.mp4",
                        name,
                    )
                )
                or bool(
                    re.fullmatch(
                        r"\.去重指纹_[0-9]{2}_尝试_[0-9]{2}\.json"
                        r"(?:\.visual)?\.partial",
                        name,
                    )
                )
                or bool(re.fullmatch(r"\.v16-contract-[A-Za-z0-9_-]+\.mp4", name))
            )
        fixed_cache_path = parts[1] == ".fixed-stage-cache" and len(parts) in {3, 4}
        if not fixed_cache_path:
            return False
        if len(parts) == 4 and not re.fullmatch(r"[0-9a-f]{16}", parts[2]):
            return False
        return bool(
            re.fullmatch(r"(?:core|quality)_[0-9]{3}\.mp4\.partial", name)
            or name == "manifest.json.partial"
        )

    # Task assets use an exact internal-path whitelist only.  User uploads
    # retain their original filenames, so a perfectly valid source such as
    # “商品.partial.原片.mp4” must never be mistaken for an interrupted file.
    for root in (QUEUE_OUTPUT_ROOT, FISSION_OUTPUT_ROOT, TASK_ASSET_ROOT):
        root = Path(root)
        if root.is_symlink() or not root.is_dir():
            continue
        try:
            resolved_root = root.resolve(strict=True)
        except OSError:
            continue
        for candidate in root.rglob("*"):
            try:
                relative = candidate.relative_to(root)
                if (
                    candidate.is_symlink()
                    or not candidate.is_file()
                    or not is_owned_temporary(relative, root)
                    or candidate.stat().st_mtime >= cutoff
                    or not _path_is_within(candidate.resolve(strict=True), resolved_root)
                ):
                    continue
                candidates.append(candidate)
            except OSError:
                continue
    return candidates


def storage_usage_snapshot(force=False):
    now = time.monotonic()
    cached = storage_scan_cache.get("snapshot")
    if (
        not force
        and isinstance(cached, dict)
        and now - float(storage_scan_cache.get("checked_monotonic") or 0.0)
        < STORAGE_SCAN_TTL_SECONDS
    ):
        return dict(cached)
    with storage_scan_lock:
        cached = storage_scan_cache.get("snapshot")
        if (
            not force
            and isinstance(cached, dict)
            and now - float(storage_scan_cache.get("checked_monotonic") or 0.0)
            < STORAGE_SCAN_TTL_SECONDS
        ):
            return dict(cached)
        redundant_zips = []
        if FISSION_OUTPUT_ROOT.is_dir() and not FISSION_OUTPUT_ROOT.is_symlink():
            for run_dir in FISSION_OUTPUT_ROOT.iterdir():
                if not run_dir.is_dir() or run_dir.is_symlink():
                    continue
                candidate = run_dir / "V17页面裂变成片_同时间轴相似度40以下.zip"
                if _quick_redundant_zip_candidate(candidate):
                    redundant_zips.append(candidate)
        partials = _managed_partial_candidates()
        output_bytes = _tree_size_bytes(QUEUE_OUTPUT_ROOT) + _tree_size_bytes(
            FISSION_OUTPUT_ROOT
        )
        asset_bytes = _tree_size_bytes(TASK_ASSET_ROOT)
        cache_bytes = sum(
            _tree_size_bytes(BASE_DIR / name)
            for name in (".v16_cache", ".upload_tmp", "tmp_process_v16_enhanced")
        )
        redundant_zip_bytes = sum(
            path.stat().st_size for path in redundant_zips if path.is_file()
        )
        stale_partial_bytes = sum(
            path.stat().st_size for path in partials if path.is_file()
        )
        try:
            free_bytes = int(shutil.disk_usage(BASE_DIR).free)
        except OSError:
            free_bytes = 0
        snapshot = {
            "data_bytes": _tree_size_bytes(BASE_DIR),
            "output_bytes": output_bytes,
            "asset_bytes": asset_bytes,
            "cache_bytes": cache_bytes,
            "safe_cleanup_candidate_bytes": redundant_zip_bytes
            + stale_partial_bytes,
            "redundant_zip_bytes": redundant_zip_bytes,
            "redundant_zip_count": len(redundant_zips),
            "stale_partial_bytes": stale_partial_bytes,
            "stale_partial_count": len(partials),
            "free_bytes": free_bytes,
            "future_zip_policy": "stream-only",
        }
        storage_scan_cache.update(
            {"checked_monotonic": time.monotonic(), "snapshot": snapshot}
        )
        return dict(snapshot)


def cleanup_safe_managed_storage():
    """Remove only CRC-verified redundant ZIPs and stale partial files."""
    released = 0
    removed_zips = 0
    removed_partials = 0
    with storage_cleanup_lock:
        if FISSION_OUTPUT_ROOT.is_dir() and not FISSION_OUTPUT_ROOT.is_symlink():
            for run_dir in FISSION_OUTPUT_ROOT.iterdir():
                if not run_dir.is_dir() or run_dir.is_symlink():
                    continue
                candidate = run_dir / "V17页面裂变成片_同时间轴相似度40以下.zip"
                if not safe_redundant_fission_zip(candidate):
                    continue
                try:
                    released += candidate.stat().st_size
                    candidate.unlink()
                    removed_zips += 1
                except OSError:
                    continue
        for candidate in _managed_partial_candidates():
            try:
                released += candidate.stat().st_size
                candidate.unlink()
                removed_partials += 1
            except OSError:
                continue
    storage_scan_cache["checked_monotonic"] = 0.0
    return {
        "released_bytes": released,
        "removed_zip_count": removed_zips,
        "removed_partial_count": removed_partials,
    }


def resume_pending_auto_saves(store):
    try:
        items = store.pending_auto_save_tasks()
    except (OSError, sqlite3.Error):
        return False
    all_settled = True
    for item in items:
        run_id = str(item.get("task_id") or "")
        config = item.get("config")
        result = dict(item.get("result") or {})
        result["auto_save"] = best_effort_auto_save_task(run_id, config, result)
        try:
            updated = retry_queue_store_operation(
                lambda: store.update_preserved_result(run_id, result),
                run_id,
                "恢复自动保存状态",
            )
        except Exception:
            updated = False
        all_settled = bool(updated) and all_settled
    return all_settled


def attach_optional_opening(
    run_id, body_path, names, index, material_root, *, mute_opening=False
):
    name = choose_opening(names, index)
    if name is None:
        return None
    root = Path(material_root or BASE_DIR).resolve(strict=True)
    opening_path = _task_asset_file_path(root, "开头视频", name)
    if opening_path.resolve(strict=True).parent != (root / "开头视频").resolve(strict=True):
        raise ValueError("开头素材越界")
    append_log(f"-> 原片已验收；正在前置开头“{name}”，原核心倍率和原片不变。", run_id)
    def owned_run(command, output):
        wait_at_queue_pause_checkpoint(run_id)
        if queue_skip_requested(run_id):
            raise QueueTaskSkipped("用户已跳过本条任务")
        with task_queue_control_lock:
            if task_queue_shutdown_event.is_set():
                raise QueueControlError("服务正在关闭，不启动开头拼接")
            proc = _start_queue_renderer_process(run_id, command, cwd=str(root),
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                encoding="utf-8", errors="replace", bufsize=1)
        diagnostics = {}
        code = stream_renderer_output(proc, run_id, activity_paths=(output,), diagnostics=diagnostics)
        if code:
            phase = "开头转码" if output.name.startswith("prefix_") else "开头与原片合并"
            reason = opening_failure_hint(diagnostics.get("output_tail", []))
            raise RuntimeError(f"{phase}失败（退出码 {code}）：{reason}；原成片保留")
    result = prepend_opening_video(body_path, opening_path,
        ffmpeg=os.environ.get("V16_FFMPEG_EXE") or shutil.which("ffmpeg") or "ffmpeg",
        ffprobe=os.environ.get("V16_FFPROBE_EXE") or shutil.which("ffprobe") or "ffprobe",
        run=owned_run,
        mute_opening=bool(mute_opening))
    append_log(f"-> 开头原片已原画原声接到最前面；最终 {result['final_duration_seconds']:.2f} 秒（含开头 {result['opening_duration_seconds']:.2f} 秒）。", run_id)
    return result


def attach_untouched_core_videos(run_id, body_path, core_names, material_root):
    names = [str(n) for n in (core_names or []) if n]
    if not names:
        return None
    root = Path(material_root or BASE_DIR).resolve(strict=True)
    core_dir_resolved = (root / "核心素材").resolve(strict=True)
    core_paths = []
    for name in names:
        cp = _task_asset_file_path(root, "核心素材", name)
        if cp.resolve(strict=True).parent != core_dir_resolved:
            raise ValueError("核心素材越界")
        core_paths.append(cp)
    joined_names = "、".join(f"“{n}”" for n in names[:3]) + (f"等{len(names)}条" if len(names) > 3 else "")
    append_log(f"-> 打乱混剪段已就绪；正在将核心素材 {joined_names} 100% 原画原声前置拼接...", run_id)

    def owned_run(command, output):
        wait_at_queue_pause_checkpoint(run_id)
        if queue_skip_requested(run_id):
            raise QueueTaskSkipped("用户已跳过本条任务")
        with task_queue_control_lock:
            if task_queue_shutdown_event.is_set():
                raise QueueControlError("服务正在关闭，不启动核心前置拼接")
            proc = _start_queue_renderer_process(
                run_id,
                command,
                cwd=str(root),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="replace",
                bufsize=1,
            )
        diagnostics = {}
        code = stream_renderer_output(
            proc, run_id, activity_paths=(output,), diagnostics=diagnostics
        )
        if code:
            phase = "核心原片轨道对齐" if output.name.startswith("prefix_") else "核心原片与打乱段合并"
            reason = opening_failure_hint(diagnostics.get("output_tail", []))
            raise RuntimeError(f"{phase}失败（退出码 {code}）：{reason}；原打乱段保留")

    result = prepend_untouched_clips(
        body_path,
        core_paths,
        ffmpeg=os.environ.get("V16_FFMPEG_EXE") or shutil.which("ffmpeg") or "ffmpeg",
        ffprobe=os.environ.get("V16_FFPROBE_EXE") or shutil.which("ffprobe") or "ffprobe",
        run=owned_run,
        mute_clips=False,
        phase_label="核心素材",
    )
    append_log(
        f"-> 核心素材已 100% 原时长原声前置完成（核心 {result['added_duration_seconds']:.2f} 秒 + 打乱段 {result['original_duration_seconds']:.2f} 秒 = {result['final_duration_seconds']:.2f} 秒）。",
        run_id,
    )
    return result


def run_job(
    run_id,
    customer_id,
    customer_name,
    face_effects,
    sticker_settings,
    price_filter,
    target_duration,
    timeline_budgets,
    fission_count,
    sync_mode,
    full_spec_mode,
    selected_materials,
    vision_provider,
    dedup_style_plan=DEFAULT_DEDUP_STYLE_PLAN,
    dedup_style_source="local-fallback",
    timepin_zoom=None,
    corner_mask_reveal=None,
    single_output_path=None,
    single_compliance_path=None,
    stall_timeout_seconds=DEFAULT_QUEUE_STALL_MINUTES * 60,
    auto_save_directory="",
    material_base_dir=None,
    slice_seconds=hardcut_audio.DEFAULT_SLICE_SECONDS,
    audio_dub_settings=None,
    edition_mode=None,
    subtitle_masks=None,
):
    job_started_monotonic = time.monotonic()
    slice_seconds = hardcut_audio.parse_slice_seconds(slice_seconds)
    audio_dub = hardcut_audio.normalize_audio_dub_settings(audio_dub_settings)
    subtitle_masks = clone_subtitle_masks(subtitle_masks)
    norm_edition_mode = hardcut_audio.normalize_edition_mode(
        edition_mode,
        default="v2" if HARDCUT_DUB_MODE else "original",
    )
    is_v2_edition = norm_edition_mode == "v2"
    if not is_v2_edition:
        subtitle_masks = clone_subtitle_masks(None)
    use_hardcut = bool(is_v2_edition and audio_dub.get("hardcut_enabled", True))
    preserve_raw_core = bool(is_v2_edition and not full_spec_mode)
    keep_orig_audio = bool(
        (not is_v2_edition) or audio_dub.get("keep_original_audio", False)
    )
    mute_orig_audio = not keep_orig_audio
    opening_names = list(selected_materials.get("开头视频", []))
    voice_audio_names = list(selected_materials.get("配音音频", []))
    ref_voice_names = list(selected_materials.get("参考音色", []))
    bgm_audio_names = list(selected_materials.get("背景音乐", []))
    choose_opening(opening_names, 1)
    # Opening and audio-only pools are excluded from video track rendering inputs.
    excluded_video_pools = {"开头视频", *AUDIO_POOLS}
    selected_materials = {
        pool: names
        for pool, names in selected_materials.items()
        if pool not in excluded_video_pools
    }
    timepin_zoom = clone_timepin_zoom_settings(timepin_zoom)
    corner_mask_reveal = clone_corner_mask_reveal_settings(corner_mask_reveal)
    single_output_path = Path(single_output_path or OUT_FILE)
    single_compliance_path = Path(
        single_compliance_path or COMPLIANCE_REPORT_FILE
    )
    # Historical queue rows may contain an older provider name.  Production
    # execution is Qwen-only regardless of that persisted display preference.
    vision_provider = "qwen"
    vision_config = VISION_PROVIDERS[vision_provider]
    multi_output = int(fission_count) > 1
    if not multi_output:
        single_output_path.parent.mkdir(parents=True, exist_ok=True)
        single_compliance_path.parent.mkdir(parents=True, exist_ok=True)
    timeline_budgets = dict(timeline_budgets)
    core_budget = max(
        0.0,
        float(
            timeline_budgets.get(
                "core_budget", timeline_budgets.get("core", 0.0)
            )
            or 0.0
        ),
    )
    core_effective = max(
        core_budget,
        float(timeline_budgets.get("core_effective", core_budget) or 0.0),
    )
    core_source = max(
        core_effective,
        float(timeline_budgets.get("core_source", core_effective) or 0.0),
    )
    timeline_budgets.setdefault("core", core_budget)
    timeline_budgets.setdefault("core_budget", core_budget)
    timeline_budgets.setdefault("core_effective", core_effective)
    timeline_budgets.setdefault("core_source", core_source)
    timeline_budgets.setdefault(
        "multiplier",
        round(float(target_duration) / core_effective, 1)
        if core_effective > 0.0
        else DEFAULT_DURATION_MULTIPLIER,
    )
    timeline_budgets.setdefault(
        "shuffle", float(timeline_budgets.get("dedup", 0.0) or 0.0)
    )
    timeline_budgets.setdefault(
        "shuffle_source", float(timeline_budgets.get("shuffle", 0.0) or 0.0)
    )
    timeline_budgets.setdefault(
        "minimum_shuffle",
        min(float(timeline_budgets.get("shuffle_source", 0.0) or 0.0), slice_seconds)
        if (use_hardcut or preserve_raw_core)
        else core_effective * SHUFFLE_TO_CORE_MIN_RATIO,
    )
    timeline_budgets["slice_seconds"] = slice_seconds
    natural_tail_limit = 0.0 if full_spec_mode else natural_tail_allowance(target_duration)
    base_env = os.environ.copy()
    base_env.pop("V16_QWEN_API_KEY", None)
    base_env.pop("V16_KIMI_API_KEY", None)
    base_env.pop("V16_VOICE_API_KEY", None)
    base_env.pop("OPENAI_API_KEY", None)
    base_env.pop("CODEX_API_KEY", None)
    base_env.pop("CODEX_ACCESS_TOKEN", None)
    base_env.update(
        {
            "BASE_DIR": str(BASE_DIR),
            "V16_MATERIAL_BASE_DIR": str(
                Path(material_base_dir or BASE_DIR).resolve()
            ),
            "V17_EDITION_MODE": norm_edition_mode,
            "V17_PRESERVE_RAW_CORE": "1" if preserve_raw_core else "0",
            "V17_HARDCUT_DUB_MODE": "1" if use_hardcut else "0",
            "V16_HARDCUT_MODE": "1" if use_hardcut else "0",
            "V16_MUTE_ORIGINAL_AUDIO": "1" if mute_orig_audio else "0",
            "V16_FIXED_SLICE_SECONDS": str(slice_seconds),
            "ENABLE_PRICE_FILTER": "1" if price_filter else "0",
            "MAX_TOTAL_DURATION": str(target_duration),
            "V16_TARGET_SECONDS": str(target_duration),
            "V16_HARD_DURATION": "1" if full_spec_mode else "0",
            "V16_QUALITY_BUDGET_SECONDS": str(timeline_budgets["quality"]),
            "V16_DEDUP_BUDGET_SECONDS": str(timeline_budgets["dedup"]),
            "V16_SHUFFLE_BUDGET_SECONDS": str(timeline_budgets["shuffle"]),
            "V16_CORE_EFFECTIVE_SECONDS": str(core_effective),
            "V16_CORE_BUDGET_SECONDS": str(core_budget),
            "V16_DURATION_MULTIPLIER": str(timeline_budgets["multiplier"]),
            "V16_THREE_POOL_MODE": "1",
            "V16_AUTO_MASK_FROM_SHUFFLE": "1",
            "V16_FULL_SPEC_MODE": "1" if full_spec_mode else "0",
            "V16_STRICT_MATERIAL_COUNTS": "1" if full_spec_mode else "0",
            "V16_AUTO_PERSON_EFFECTS": "1" if full_spec_mode else "0",
            "V16_FULL_COMPLIANCE_SCAN": "1" if full_spec_mode else "0",
            "V16_OUTPUT_FPS": "auto",
            "V16_AUTO_FPS_60_THRESHOLD": "0.70",
            "V16_FINISH_LAST_CLIP": "0" if (full_spec_mode or use_hardcut) else "1",
            "V16_MAX_NATURAL_TAIL_SECONDS": str(natural_tail_limit),
            "V16_AUTO_MICRO_MOTION": "0",
            "V16_MICRO_MOTION_WINDOW_SECONDS": "1.0",
            "V16_MICRO_MOTION_MAX_FRAME_DELTA": "4.0",
            "V16_MICRO_MOTION_ZOOM": "0.12",
            "V16_TIMEPIN_ZOOM_ENABLED": "1"
            if timepin_zoom["enabled"]
            else "0",
            "V16_TIMEPIN_ZOOM_KEYFRAMES_JSON": json.dumps(
                timepin_zoom["keyframes"],
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            "V16_CORNER_MASK_REVEAL_MODE": corner_mask_reveal["mode"],
            "V16_CORNER_MASK_REVEAL_RADIUS_PX": str(
                corner_mask_reveal["radius_px"]
            ),
            "V17_SUBTITLE_MASKS_JSON": json.dumps(
                subtitle_masks,
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            "V16_SHORT_EFFECT_WINDOW_SECONDS": "1.0",
            "V16_EARLY_EFFECT_SECONDS": "30",
            "V16_EARLY_EFFECT_OPACITY": "0.30",
            "V16_FACE_DETECT_INTERVAL": "3",
            "V16_FACE_IDLE_DETECT_INTERVAL": "6",
            "V16_SUBTITLE_TIMEOUT": "120",
            "V16_EXTERNAL_API_KEYS_REQUIRED": "1",
            "V16_VISION_PROVIDER": vision_provider,
            "V16_VISION_MODEL": vision_config["model"],
            "V16_VISION_USE_CODEX": "0",
            "V16_VISION_USE_OPENAI": "0",
            "V16_VISION_USE_OPENCLAW": "0",
            "V16_VISION_USE_GEMINI": "0",
            "V16_TTS_ENABLED": "0",
            "V16_DEDUP2_ENABLED": "0",
            "V16_SYNC_MODE": sync_mode,
            "V16_UPLOAD_ORDER_FILE": str(UPLOAD_ORDER_FILE),
            "PYTHONUNBUFFERED": "1",
            "PYTHONUTF8": "1",
            "PYTHONIOENCODING": "utf-8",
        }
    )
    if WINDOWS_CPU_STABILITY_PROFILE:
        # Force the single-path/native-auto contract even when the target PC
        # has stale V16 thread-limit variables in its global environment.
        base_env.update(windows_stability_environment())
    python = os.environ.get("V16_PYTHON_EXE", "").strip()
    if not python:
        python = str(PY312) if PY312.exists() else sys.executable
    if not python:
        python = "python3"

    fission_plan_key = ""
    if multi_output:
        fission_plan_key = build_fission_plan_key(
            selected_materials,
            {
                "target_duration": round(float(target_duration), 3),
                "timeline_budgets": timeline_budgets,
                "fission_count": int(fission_count),
                "sync_mode": str(sync_mode),
                "full_spec_mode": bool(full_spec_mode),
                "price_filter": bool(price_filter),
                "face_effects": list(face_effects),
                "sticker_settings": dict(sticker_settings),
                "dedup_style_plan": list(dedup_style_plan),
                "timepin_zoom": timepin_zoom,
                "corner_mask_reveal": corner_mask_reveal,
                "subtitle_masks": subtitle_masks,
            },
            material_root=material_base_dir,
        )
    run_dir = FISSION_OUTPUT_ROOT / run_id if multi_output else None
    accepted_paths = []
    accepted_durations = []
    accepted_hashes = []
    pair_results = []
    variant_plans = []
    last_returncode = -1
    queue_finalizing = False
    material_capacity = fission_material_capacity(selected_materials)
    material_plan_cursor = 0
    used_material_plans = set()
    disk_reservation_acquired = False
    batch_base_candidate_budget = fission_batch_candidate_budget(fission_count)
    batch_candidate_budget = fission_candidate_limit(
        fission_count,
        fission_count,
    )
    batch_candidate_attempts_used = 0
    fill_session = None
    fill_enabled = False

    def fill_snapshot():
        return dict(accepted_paths=accepted_paths, accepted_durations=accepted_durations,
                    accepted_hashes=accepted_hashes, pair_results=pair_results,
                    variant_plans=variant_plans, material_plan_cursor=material_plan_cursor)

    synthesized_voice_temps: list[Path] = []
    try:
        fill_store = get_task_queue_store(create=False)
        fill_enabled = bool(multi_output and fill_store is not None and fill_store.get(run_id))
        if fill_enabled:
            signature = hashlib.sha256(fill_canonical(dict(
                customer_id=customer_id, customer_name=customer_name,
                face_effects=face_effects, sticker_settings=sticker_settings,
                price_filter=price_filter, target_duration=target_duration,
                timeline_budgets=timeline_budgets, fission_count=fission_count,
                sync_mode=sync_mode, full_spec_mode=full_spec_mode,
                selected_materials=selected_materials, opening_names=opening_names,
                edition_mode=norm_edition_mode, slice_seconds=slice_seconds,
                audio_dub=audio_dub, voice_audio_names=voice_audio_names,
                ref_voice_names=ref_voice_names, bgm_audio_names=bgm_audio_names,
                material_base_dir=material_signature_identity(material_base_dir),
                dedup_style_plan=dedup_style_plan, timepin_zoom=timepin_zoom,
                corner_mask_reveal=corner_mask_reveal,
                subtitle_masks=subtitle_masks,
            )).encode('utf-8')).hexdigest()

            def fill_notify(metadata):
                metadata = dict(metadata)
                metadata['failure_reason'] = redact_local_paths(metadata.get('failure_reason') or '')
                metadata['message'] = redact_local_paths(metadata.get('message') or '')
                if not fill_store.update_auto_fill(run_id, metadata):
                    raise FillCheckpointError('自动补做状态无法持久化，停止以免重复制作')
                with state_lock:
                    if state['run_id'] == run_id:
                        state['auto_fill'] = metadata
                        if metadata['retry_round']:
                            state['stage'] = metadata['message']

            fill_session = RenderCheckpoint(
                QUEUE_OUTPUT_ROOT / run_id / '.auto-fill.json', run_id,
                TENANT_USER_ID or INSTANCE_ID, fission_count, signature, run_dir, fill_notify)
            restored = fill_session.restore()
            if restored:
                accepted_paths = restored['accepted_paths']
                accepted_durations = restored['accepted_durations']
                accepted_hashes = restored['accepted_hashes']
                pair_results = restored['pair_results']
                variant_plans = restored['variant_plans']
                material_plan_cursor = restored['material_plan_cursor']
            if fill_session.data['state'] == 'fill_failed':
                raise FillCheckpointError(fill_session.data['error'])
        acquire_renderer_disk_reservation(run_id)
        disk_reservation_acquired = True
        append_log("V17 增强版开始运行...", run_id)
        working_space = ensure_candidate_working_space(
            target_duration,
            fission_count,
        )
        publish_renderer_disk_reservation(
            run_id,
            working_space["required_bytes"],
        )
        append_log(
            f"-> 稳定运行配置 {RUNTIME_STABILITY_PROFILE}："
            f"本批启动门槛 {format_gib(working_space['required_bytes'])}，"
            f"当前可用 {format_gib(working_space['free_bytes'])}；"
            f"Windows 使用两路镜头并行，CPU 编码回退每路限 {EFFECTIVE_FFMPEG_THREADS} 线程；合格的完整 H.264 素材优先走 GPU 0 的 "
            "NVDEC + CUDA 缩放裁剪 + NVENC 全显存通道；复杂软件滤镜继续由 CPU "
            "稳定执行，重复分段在收益足够时只规范化一次。CUDA 首个真实素材"
            "验收失败会自动回退原滤镜图并保留 NVENC；所有回退均写入日志。",
            run_id,
        )
        if multi_output:
            FISSION_OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
            run_dir.mkdir(parents=False, exist_ok=bool(fill_session))
            if use_hardcut:
                append_log(
                    f"-> 页面裂变模式：串行生成 {fission_count} 条；核心素材整段保留，"
                    f"打乱素材按 {slice_seconds:g} 秒一刀无视动作硬切，单条内 0 重复。",
                    run_id,
                )
                append_log(
                    "-> 去重策略：已取消 40% 相似度硬门槛拦截；跨条读取批次切片账本自动错位排片，"
                    "做到成片间相似度最低。",
                    run_id,
                )
            else:
                append_log(
                    f"-> 页面裂变模式：串行生成 {fission_count} 条；打乱素材按完整话术/动作"
                    "逐条独立重组，并按不同自然时间窗取材。核心超出预算时按自然边界截取。",
                    run_id,
                )
                append_log(
                    f"-> 本地门槛：比较完整打乱镜头轨道；任意两条画面哈希相似度"
                    f"在同一制作批次内不得超过 {FISSION_SIMILARITY_LIMIT:.0f}%。"
                    "自动补做另起新批次，不与前轮成片比较；核心素材不计入该指标。",
                    run_id,
                )
                append_log(
                    f"-> 稳定候选计划：同一批素材与参数固定使用计划 "
                    f"{fission_plan_key[:12]}；本批共享最多 "
                    f"{batch_base_candidate_budget} 套自然时间窗/换序方案；"
                    "单个候选不合格不会提前结束整批，也不会无界重渲染。",
                    run_id,
                )
        elif full_spec_mode:
            append_log(
                "-> 完整规范模式：固定 210 秒；0–60 秒核心、60–150 秒优质、"
                "150–210 秒去重；执行分层画面处理与全片合规扫描。",
                run_id,
            )
        append_log(
            f"-> 时长公式: 原始核心 C_raw={core_source:.1f} 秒，有效基准 "
            f"C={core_effective:.1f} 秒，核心纳入预算 {core_budget:.1f} 秒，"
            f"K={timeline_budgets['multiplier']:.1f}，T=C×K={target_duration:.1f} 秒；"
            f"S={timeline_budgets['shuffle_source']:.1f} 秒。"
            + (
                f"打乱轨按 {slice_seconds:g} 秒一刀硬切拼接（单条内 0 重复）。"
                if use_hardcut
                else f"打乱段在完整话术/动作结束处自然收尾，最多顺延 {natural_tail_limit:.1f} 秒。"
            ),
            run_id,
        )
        append_log(
            "-> 智能加速: 只预处理本条所需的打乱素材窗口；人脸隔帧检测并连续跟踪；"
            "不降帧、不降分辨率、不在参考点硬砍尾段。",
            run_id,
        )
        if timepin_zoom["enabled"]:
            keyframe_summary = " → ".join(
                f"{item['position_percent']:.0f}%:"
                f"{item['scale_percent']:.0f}%/"
                f"上下{item['vertical_percent']:+.0f}%"
                for item in timepin_zoom["keyframes"]
            )
            append_log(
                f"-> 时间针推拉已开启：只放大无黑边模式 {keyframe_summary}；"
                "缩放与上下位置在针间平滑插值，不跳帧、不改变时长。",
                run_id,
            )
        if corner_mask_reveal["enabled"]:
            append_log(
                f"-> 四角露底蒙版已开启：{corner_mask_reveal['mode']} 档，"
                f"四角圆角半径 {corner_mask_reveal['radius_px']}px；"
                "全片持续、只露四角，蒙版音频不进入成片。",
                run_id,
            )
        if multi_output:
            credential_note = (
                "不导出 Codex 登录凭证，也不传入剪辑或媒体子进程。"
                if vision_provider == "codex"
                else "Key 不传入剪辑或媒体子进程。"
            )
            append_log(
                "-> 画质保护：所有候选全部保持自然彩色画面；不再启用剪影、"
                f"墨线或海报化滤镜。重试只更换自然时间窗与编排。{credential_note}",
                run_id,
            )
        else:
            if vision_provider == "codex":
                append_log(
                    "-> Codex 本机 ChatGPT 登录状态已确认；单条模式不调用模型，"
                    "不导出任何登录凭证。",
                    run_id,
                )
            else:
                append_log(
                    f"-> {vision_config['label']} Key 已完成官方校验；单条模式不调用模型，"
                    "Key 不传入剪辑或媒体子进程。",
                    run_id,
                )
        append_log(
            "-> 自动帧率: 真实高帧率素材时长占比达到 70% 输出恒定 60fps，"
            "否则输出恒定 30fps；90/120fps 不直接作为成片帧率。",
            run_id,
        )
        material_root_resolved = Path(material_base_dir or BASE_DIR).resolve()
        tmp_runtime_root = BASE_DIR / ".v17_batch_ledgers"
        tmp_runtime_root.mkdir(parents=True, exist_ok=True)
        batch_used_slices_path = tmp_runtime_root / f".batch_slices_{run_id}.json"
        if not accepted_paths:
            batch_used_slices_path.unlink(missing_ok=True)
        total_variants = max(1, int(fission_count or 1))
        variant_voice_paths: list[Path | None] = [None] * total_variants
        variant_voice_labels: list[str] = [""] * total_variants
        variant_bgm_paths: list[Path | None] = [None] * total_variants
        variant_bgm_names: list[str] = [""] * total_variants

        def _safe_audio_pool_file(pool_name: str, file_name: str) -> Path:
            pool_dir = (material_root_resolved / pool_name).resolve()
            candidate = (pool_dir / Path(str(file_name)).name).resolve()
            if candidate.parent != pool_dir or not candidate.is_file():
                raise RuntimeError(f"{pool_name}文件不存在或路径无效：{file_name}")
            return candidate

        if subtitle_masks.get("enabled") and subtitle_masks.get("boxes"):
            _sm_style_map = {
                "blur": f"高斯模糊（强度 {subtitle_masks['strength']}）",
                "delogo": "智能融合去字（delogo）",
                "dark": f"深色柔化条（强度 {subtitle_masks['strength']}）",
            }
            _sm_desc = _sm_style_map.get(subtitle_masks.get("style", "blur"), "高斯模糊")
            append_log(
                f"-> 手动选框挡字：已启用 {len(subtitle_masks['boxes'])} 个挡字框（效果：{_sm_desc} · 仅遮挡打乱素材，开头与核心原片保留不动）。",
                run_id,
            )

        if is_v2_edition:
            append_log(
                f"-> 第二版本（可选模式）：原片声音={'保留原片原声' if keep_orig_audio else '已取消原片原声'}；"
                + (
                    f"切分方式=固定 {slice_seconds:g} 秒一刀硬切（核心整段保留、单条内 0 重复、取消 40% 门槛自动最低相似度）。"
                    if use_hardcut
                    else "切分方式=原版智能自然切分。"
                ),
                run_id,
            )
            if audio_dub["voice_mode"] == "upload":
                if not voice_audio_names:
                    raise RuntimeError("当前选择了“使用已上传配音音频”，但任务中尚未上传配音音频文件。")
                voice_path_map = {
                    name: _safe_audio_pool_file("配音音频", name)
                    for name in dict.fromkeys(voice_audio_names)
                }
                voice_schedule = hardcut_audio.build_shuffled_audio_schedule(
                    list(voice_path_map.keys()),
                    total_variants,
                    seed_key=f"{run_id}:voice_upload",
                )
                max_v_dur = 0.0
                for idx_slot, chosen_v_name in enumerate(voice_schedule):
                    if chosen_v_name and chosen_v_name in voice_path_map:
                        v_p = voice_path_map[chosen_v_name]
                        variant_voice_paths[idx_slot] = v_p
                        variant_voice_labels[idx_slot] = chosen_v_name
                        max_v_dur = max(max_v_dur, hardcut_audio.probe_audio_duration(v_p))
                if total_variants > 1 and len(voice_path_map) > 1:
                    preview_pairs = "、".join(
                        f"第{i + 1}条→“{n}”" for i, n in enumerate(variant_voice_labels) if n
                    )
                    append_log(
                        f"-> 已加载 {len(voice_path_map)} 条配音音频，已按每条视频随机不重复分配：{preview_pairs}（音量 {audio_dub['voice_volume']}%）。",
                        run_id,
                    )
                elif variant_voice_paths[0] is not None:
                    v_dur = hardcut_audio.probe_audio_duration(variant_voice_paths[0])
                    append_log(
                        f"-> 已加载上传的配音音频“{variant_voice_labels[0]}”（{v_dur:.2f} 秒，音量 {audio_dub['voice_volume']}%）。",
                        run_id,
                    )
                voice_target_dur = (
                    float(timeline_budgets["shuffle"])
                    if preserve_raw_core
                    else float(target_duration)
                )
                if max_v_dur > voice_target_dur + 0.6:
                    append_log(
                        "-> 提示：部分配音时长略长于当前打乱混剪段时长，超出部分将随结尾平滑淡出；如需完整播完配音可调高时长倍率。",
                        run_id,
                    )
            elif audio_dub["voice_mode"] == "tts":
                voice_target_dur = (
                    float(timeline_budgets["shuffle"])
                    if preserve_raw_core
                    else float(target_duration)
                )
                if not audio_dub["voice_text"]:
                    raise RuntimeError("当前选择了“文案生成/克隆音色配音”，但配音文案为空。")
                with state_lock:
                    if state["run_id"] == run_id:
                        state["stage"] = "正在合成配音音色"
                if audio_dub["voice_preset"] == "custom_clone":
                    if not ref_voice_names:
                        raise RuntimeError("当前选择了“导入参考音色克隆”，但未上传参考音色音频。")
                    ref_path_map = {
                        name: _safe_audio_pool_file("参考音色", name)
                        for name in dict.fromkeys(ref_voice_names)
                    }
                    ref_schedule = hardcut_audio.build_shuffled_audio_schedule(
                        list(ref_path_map.keys()),
                        total_variants,
                        seed_key=f"{run_id}:voice_ref",
                    )
                    tts_cache_by_ref: dict[str, tuple[Path, float, str]] = {}
                    for ref_idx, ref_name in enumerate(dict.fromkeys(n for n in ref_schedule if n)):
                        out_wav = tmp_runtime_root / f".tts_voice_{run_id}_{ref_idx}.wav"
                        synthesized_voice_temps.append(out_wav)
                        tts_info = hardcut_audio.synthesize_voiceover(
                            audio_dub["voice_text"],
                            audio_dub["voice_preset"],
                            out_wav,
                            speed=audio_dub["voice_speed"],
                            ref_audio_path=ref_path_map[ref_name],
                        )
                        tts_cache_by_ref[ref_name] = (
                            Path(tts_info["path"]),
                            float(tts_info["duration_seconds"]),
                            str(tts_info["engine_used"]),
                        )
                    max_tts_dur = 0.0
                    for idx_slot, chosen_ref in enumerate(ref_schedule):
                        if chosen_ref and chosen_ref in tts_cache_by_ref:
                            wav_p, t_dur, _eng = tts_cache_by_ref[chosen_ref]
                            variant_voice_paths[idx_slot] = wav_p
                            variant_voice_labels[idx_slot] = f"克隆:{chosen_ref}"
                            max_tts_dur = max(max_tts_dur, t_dur)
                    if total_variants > 1 and len(tts_cache_by_ref) > 1:
                        preview_refs = "、".join(
                            f"第{i + 1}条→“{n}”" for i, n in enumerate(ref_schedule) if n
                        )
                        append_log(
                            f"-> 已用 {len(tts_cache_by_ref)} 条参考音色完成克隆配音合成，随机不重复分配：{preview_refs}（音量 {audio_dub['voice_volume']}%）。",
                            run_id,
                        )
                    elif tts_cache_by_ref:
                        first_ref, (_wp, t_dur, eng_used) = next(iter(tts_cache_by_ref.items()))
                        append_log(
                            f"-> 配音已合成：{eng_used}（样本“{first_ref}”），时长 {t_dur:.2f} 秒（音量 {audio_dub['voice_volume']}%）。",
                            run_id,
                        )
                    if max_tts_dur > voice_target_dur + 0.6:
                        append_log(
                            "-> 提示：配音时长略长于当前打乱混剪段时长，超出部分将随结尾平滑淡出；如需完整播完配音可调高时长倍率。",
                            run_id,
                        )
                else:
                    single_tts_wav = tmp_runtime_root / f".tts_voice_{run_id}.wav"
                    synthesized_voice_temps.append(single_tts_wav)
                    tts_info = hardcut_audio.synthesize_voiceover(
                        audio_dub["voice_text"],
                        audio_dub["voice_preset"],
                        single_tts_wav,
                        speed=audio_dub["voice_speed"],
                        ref_audio_path=None,
                    )
                    synth_path = Path(tts_info["path"])
                    tts_dur = float(tts_info["duration_seconds"])
                    for idx_slot in range(total_variants):
                        variant_voice_paths[idx_slot] = synth_path
                        variant_voice_labels[idx_slot] = str(tts_info["engine_used"])
                    append_log(
                        f"-> 配音已合成：{tts_info['engine_used']}，时长 {tts_dur:.2f} 秒（音量 {audio_dub['voice_volume']}%）。",
                        run_id,
                    )
                    if tts_dur > voice_target_dur + 0.6:
                        append_log(
                            "-> 提示：配音时长略长于当前打乱混剪段时长，超出部分将随结尾平滑淡出；如需完整播完配音可调高时长倍率。",
                            run_id,
                        )
            else:
                append_log(
                    "-> 人声配音：未启用（可选，不加配音直接出片）。",
                    run_id,
                )
            if audio_dub.get("bgm_enabled", True) and bgm_audio_names:
                bgm_path_map: dict[str, Path] = {}
                for b_name in dict.fromkeys(bgm_audio_names):
                    try:
                        bgm_path_map[b_name] = _safe_audio_pool_file("背景音乐", b_name)
                    except RuntimeError:
                        continue
                if bgm_path_map:
                    bgm_schedule = hardcut_audio.build_shuffled_audio_schedule(
                        list(bgm_path_map.keys()),
                        total_variants,
                        seed_key=f"{run_id}:bgm",
                    )
                    for idx_slot, chosen_bgm in enumerate(bgm_schedule):
                        if chosen_bgm and chosen_bgm in bgm_path_map:
                            variant_bgm_paths[idx_slot] = bgm_path_map[chosen_bgm]
                            variant_bgm_names[idx_slot] = chosen_bgm
                    if total_variants > 1 and len(bgm_path_map) > 1:
                        preview_bgms = "、".join(
                            f"第{i + 1}条→“{n}”" for i, n in enumerate(variant_bgm_names) if n
                        )
                        append_log(
                            f"-> 已加载 {len(bgm_path_map)} 首背景音乐，已按每条视频随机不重复分配：{preview_bgms}（循环铺底＋结尾淡出，音量 {audio_dub['bgm_volume']}%）。",
                            run_id,
                        )
                    elif variant_bgm_paths[0] is not None:
                        b_dur = hardcut_audio.probe_audio_duration(variant_bgm_paths[0])
                        append_log(
                            f"-> 已加载背景音乐“{variant_bgm_names[0]}”（{b_dur:.2f} 秒，循环铺底＋结尾淡出，音量 {audio_dub['bgm_volume']}%）。",
                            run_id,
                        )
        else:
            append_log(
                "-> 第一版（原版模式）：完整保留原视频原声，按原版智能自然窗口切分与 40% 去重门槛执行。",
                run_id,
            )

        def _variant_audio_choice(v_idx: int) -> tuple[Path | None, str, Path | None, str]:
            slot = max(0, min(total_variants - 1, int(v_idx or 1) - 1))
            return (
                variant_voice_paths[slot],
                variant_voice_labels[slot],
                variant_bgm_paths[slot],
                variant_bgm_names[slot],
            )

        variant_index = len(accepted_paths) + 1
        while variant_index <= int(fission_count):
            try:
                with state_lock:
                    if state["run_id"] == run_id:
                        state["current_variant"] = variant_index
                        state["stage"] = (
                            f"正在生成裂变 {variant_index}/{fission_count}"
                            if multi_output
                            else "正在制作成片"
                        )

                comparison_start = fill_session.similarity_start if fill_session else 0
                comparison_hashes = accepted_hashes[comparison_start:]
                accepted = False
                render_failure_count = 0
                slot_attempt = (fill_session.round * 1000 if fill_session else 0)
                variant_candidate_limit = fission_candidate_limit(
                    fission_count,
                    variant_index,
                )
                while True:
                    if batch_candidate_attempts_used >= variant_candidate_limit:
                        break
                    attempt = slot_attempt
                    slot_attempt += 1
                    batch_candidate_attempts_used += 1
                    more_candidates_available = (
                        batch_candidate_attempts_used < variant_candidate_limit
                    )
                    if attempt > 0 or accepted_paths:
                        remaining_outputs = max(
                            1,
                            int(fission_count) - len(accepted_paths),
                        )
                        remaining_space = ensure_candidate_working_space(
                            target_duration,
                            remaining_outputs,
                        )
                        publish_renderer_disk_reservation(
                            run_id,
                            remaining_space["required_bytes"],
                        )
                    material_plan_index = None
                    shuffle_window_index = 0
                    if multi_output:
                        while True:
                            material_plan_index = material_plan_cursor
                            material_plan_cursor += 1
                            # Every candidate advances the source-window cycle.
                            # The runner applies a stable basename-rank offset, so
                            # each individual 6–8 minute source moves to its next
                            # non-zero slot instead of only changing file order.
                            shuffle_window_index = material_plan_index + 1
                            variant_materials = build_fission_materials(
                                selected_materials,
                                fission_plan_key,
                                variant_index,
                                attempt,
                                plan_index=material_plan_index,
                            )
                            material_signature = tuple(
                                tuple(variant_materials.get(pool, []))
                                for pool in ("核心素材", "打乱素材池")
                            ) + (shuffle_window_index,)
                            if (
                                material_signature not in used_material_plans
                                or len(used_material_plans) >= material_capacity
                            ):
                                used_material_plans.add(material_signature)
                                break
                    else:
                        variant_materials = {
                            pool: list(names) for pool, names in selected_materials.items()
                        }
                    core_window_index = (
                        variant_index
                        if multi_output and core_source > core_budget + 0.05
                        else 0
                    )
                    variant_effects = (
                        build_fission_effects(face_effects, variant_index, attempt)
                        if multi_output
                        else list(face_effects)
                    )
                    variant_style = (
                        build_fission_dedup_style(
                            dedup_style_plan, variant_index, attempt
                        )
                        if multi_output
                        else "clean"
                    )
                    variant_stickers = (
                        build_fission_stickers(sticker_settings, variant_index, attempt)
                        if multi_output
                        else dict(sticker_settings)
                    )
                    variant_seed = (
                        f"{fission_plan_key}:{variant_index}:{attempt}"
                        if multi_output
                        else ""
                    )
                    core_order = list(variant_materials.get("核心素材", []))
                    core_cache_identity = hashlib.sha256(
                        json.dumps(
                            {
                                "policy": CORE_WINDOW_POLICY,
                                "order": core_order,
                                "budget": round(core_budget, 3),
                                "window_index": core_window_index,
                                "hardcut_mode": bool(use_hardcut),
                                "mute_original_audio": bool(mute_orig_audio),
                            },
                            ensure_ascii=False,
                            sort_keys=True,
                            separators=(",", ":"),
                        ).encode("utf-8")
                    ).hexdigest()[:16]
                    rotate_core_openers = bool(
                        multi_output
                        and len(selected_materials.get("核心素材", [])) > 1
                    )
                    fixed_cache_dir = None
                    fixed_cache_key = ""
                    if multi_output:
                        fixed_cache_dir = run_dir / ".fixed-stage-cache" / core_cache_identity
                        fixed_cache_key = f"{run_id}:{core_cache_identity}"
                    effect_chain = ",".join(variant_effects) if variant_effects else "none"
                    sticker_corners = dict(variant_stickers.get("corners", {}))
                    sticker_size_percent = int(variant_stickers.get("size_percent", 100))
                    fullscreen_sticker = dict(
                        variant_stickers.get("fullscreen", {})
                    )
                    mask_source_name = choose_shuffle_mask_name(
                        variant_materials.get("打乱素材池", []),
                        fission_plan_key,
                        variant_index,
                        attempt,
                    )

                    if multi_output:
                        candidate_path = run_dir / (
                            f".裂变候选_{variant_index:02d}_尝试_{attempt + 1:02d}.mp4"
                        )
                        compliance_path = run_dir / (
                            f".合规候选_{variant_index:02d}_尝试_{attempt + 1:02d}.json"
                        )
                        dedup_hash_path = run_dir / (
                            f".去重指纹_{variant_index:02d}_尝试_{attempt + 1:02d}.json"
                        )
                    else:
                        candidate_path = single_output_path
                        compliance_path = single_compliance_path
                        dedup_hash_path = None

                    # Every proposal first uses the strict natural-boundary plan.
                    # When that plan has no usable complete ending, the runner may
                    # use its bounded natural-ending fallback.  Keeping this on for
                    # every proposal prevents 43-only attempts from wasting most of
                    # the shared batch budget; it never permits a hard frame cut.
                    natural_boundary_fallback_attempt = True
                    natural_boundary_fallback_extra = min(
                        natural_tail_limit,
                        18.0,
                    )
                    job_tmp_name = (
                        f"{run_id}-{variant_index:02d}-{attempt + 1:02d}-"
                        f"{uuid.uuid4().hex[:12]}"
                    )
                    job_tmp_path = BASE_DIR / "tmp_process_v16_enhanced" / job_tmp_name
                    variant_env = base_env.copy()
                    variant_env.update(
                        {
                            "KUAISHOU_TASK_ID": run_id,
                            # The runner atomically creates this direct child.  Do
                            # not pre-create it here; duplicate ownership must fail.
                            "KUAISHOU_JOB_TMP": str(job_tmp_path),
                            "OUT_FILE": str(candidate_path),
                            "V16_BATCH_USED_SLICES_FILE": str(batch_used_slices_path),
                            "FACE_EFFECTS": effect_chain,
                            "FACE_EFFECT": variant_effects[0] if variant_effects else "none",
                            "V16_SELECTED_MATERIALS_JSON": json.dumps(
                                variant_materials,
                                ensure_ascii=False,
                                separators=(",", ":"),
                            ),
                            "V16_STICKER_CORNER_CONFIG": json.dumps(
                                sticker_corners, ensure_ascii=False
                            ),
                            "V16_STICKER_SIZE_PERCENT": str(sticker_size_percent),
                            "V16_FULLSCREEN_STICKER_CONFIG": json.dumps(
                                fullscreen_sticker,
                                ensure_ascii=False,
                                separators=(",", ":"),
                            ),
                            "V16_FISSION_VARIANT_SEED": variant_seed,
                            "V16_FISSION_MATERIAL_PLAN_INDEX": str(
                                material_plan_index or 0
                            ),
                            "V16_SHUFFLE_WINDOW_INDEX": str(shuffle_window_index),
                            "V16_CORE_WINDOW_INDEX": str(core_window_index),
                            "V16_FISSION_SHUFFLE_ALL": "1" if multi_output else "0",
                            "V16_FISSION_CORE_OPENER": (
                                "1" if rotate_core_openers else "0"
                            ),
                            "V16_FAST_DEDUP_STYLE": variant_style,
                            "V16_DEDUP_HASH_FILE": str(dedup_hash_path) if dedup_hash_path else "",
                            "V16_FIXED_STAGE_CACHE_DIR": (
                                str(fixed_cache_dir) if fixed_cache_dir else ""
                            ),
                            "V16_FIXED_STAGE_CACHE_KEY": (
                                fixed_cache_key if multi_output else ""
                            ),
                            "V16_PRIOR_DEDUP_HASHES_JSON": json.dumps(
                                comparison_hashes, separators=(",", ":")
                            ) if multi_output else "",
                            "V16_FISSION_SIMILARITY_LIMIT": str(FISSION_SIMILARITY_LIMIT),
                            "V16_COMPLIANCE_REPORT_FILE": str(compliance_path),
                            "V16_MASK_SOURCE_NAME": mask_source_name,
                            "V16_ALLOW_NATURAL_BOUNDARY_FALLBACK": (
                                "1" if natural_boundary_fallback_attempt else "0"
                            ),
                            "V16_NATURAL_BOUNDARY_FALLBACK_EXTRA_SECONDS": str(
                                natural_boundary_fallback_extra
                            ),
                        }
                    )
                    if dedup_hash_path:
                        dedup_hash_path.unlink(missing_ok=True)
                    output_before = output_file_signature(candidate_path)
                    if multi_output:
                        if attempt == 0:
                            retry_label = "首次方案"
                        elif attempt == 1:
                            retry_label = "第 2 次自然时间窗/换序方案"
                        else:
                            retry_label = f"第 {attempt + 1} 次自然时间窗/换序方案"
                        if natural_boundary_fallback_attempt:
                            retry_label += "（安全自然边界容错已开启）"
                        append_log(
                            f"-> 裂变 {variant_index}/{fission_count}：{retry_label}；"
                            f"打乱轨风格 {variant_style}，自动蒙版 {mask_source_name}，"
                            f"用户效果链 {effect_chain}。",
                            run_id,
                        )
                    else:
                        append_log(f"-> 人脸特效叠加链: {effect_chain}", run_id)
                    if fullscreen_sticker.get("name"):
                        append_log(
                            f"-> 动态全屏贴纸：{fullscreen_sticker['name']}；"
                            "透明/绿幕自动处理，全片循环，贴纸声音不进入成片。",
                            run_id,
                        )

                    # A pause may be requested while this variant is being
                    # prepared.  Do not launch another renderer until the same
                    # queue task is explicitly resumed.
                    wait_at_queue_pause_checkpoint(run_id)
                    # Close the shutdown race: the signal handler sets the flag
                    # under this same lock, so a renderer is either not launched
                    # at all or is registered before shutdown snapshots the list.
                    with task_queue_control_lock:
                        if task_queue_shutdown_event.is_set():
                            raise QueueControlError("服务正在关闭，本条未启动新的制作进程")
                        proc = _start_queue_renderer_process(
                            run_id,
                            [python, str(RUNNER)],
                            cwd=str(BASE_DIR),
                            env=variant_env,
                            stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT,
                            text=True,
                            encoding="utf-8",
                            errors="ignore",
                            bufsize=1,
                        )
                    renderer_diagnostics = {}
                    try:
                        if vision_config["key_env"]:
                            variant_env.pop(vision_config["key_env"], None)
                        last_returncode = stream_renderer_output(
                            proc,
                            run_id,
                            stall_timeout_seconds=stall_timeout_seconds,
                            activity_paths=(
                                candidate_path,
                                compliance_path,
                                job_tmp_path,
                            ),
                            diagnostics=renderer_diagnostics,
                        )
                    except BaseException:
                        with task_queue_control_lock:
                            still_owned = task_queue_renderer_processes.get(str(run_id)) is proc
                        if still_owned:
                            terminate_queue_renderer(proc, run_id)
                            unregister_queue_renderer(run_id, proc)
                        raise
                    finally:
                        cleanup_safe = renderer_working_directory_cleanup_safe(
                            run_id,
                            proc,
                        )
                        if cleanup_safe and not cleanup_renderer_job_tmp_path(
                            job_tmp_path,
                            run_id,
                        ):
                            append_log(
                                "-> 本次制作临时目录暂被 Windows 占用；不会影响"
                                "已验收成片或其他并发任务，冷启动空闲清理时会再处理。",
                                run_id,
                            )
                        elif not cleanup_safe:
                            append_log(
                                "-> 制作进程树仍由安全控制器接管，暂不清理临时目录；"
                                "确认进程退出后再清理，避免活进程写入被删除路径。",
                                run_id,
                            )
                    if multi_output and last_returncode == 42:
                        candidate_hashes = load_dedup_hash_file(
                            dedup_hash_path, variant_style
                        )
                        dedup_hash_path.unlink(missing_ok=True)
                        early_results = []
                        for prior_index, prior_hashes in enumerate(comparison_hashes, comparison_start + 1):
                            similarity = frame_hash_similarity_percent(
                                candidate_hashes, prior_hashes
                            )
                            early_results.append(
                                {
                                    "first": prior_index,
                                    "second": variant_index,
                                    "similarity_percent": similarity,
                                }
                            )
                        early_worst = max(
                            (item["similarity_percent"] for item in early_results),
                            default=0.0,
                        )
                        if early_worst <= FISSION_SIMILARITY_LIMIT:
                            raise RuntimeError("剪辑程序错误地提前停止了合格的打乱轨候选。")
                        append_log(
                            f"-> 裂变 {variant_index}/{fission_count} 打乱轨道相似度 "
                            f"{early_worst:.2f}% > {FISSION_SIMILARITY_LIMIT:.0f}%，"
                            "已在穿插、全片特效和最终压制前止损，立即换下一方案。",
                            run_id,
                        )
                        candidate_path.unlink(missing_ok=True)
                        compliance_path.unlink(missing_ok=True)
                        if more_candidates_available:
                            continue
                        raise RuntimeError(
                            f"本条可用候选预算 {variant_candidate_limit} 套已经用尽；"
                            f"裂变第 {variant_index} 条仍高于 "
                            f"{FISSION_SIMILARITY_LIMIT:.0f}%"
                        )
                    if multi_output and last_returncode == 43:
                        candidate_path.unlink(missing_ok=True)
                        compliance_path.unlink(missing_ok=True)
                        if dedup_hash_path:
                            dedup_hash_path.unlink(missing_ok=True)
                        append_log(
                            f"-> 裂变 {variant_index}/{fission_count} 本方案在参考点附近"
                            "没有可用的完整话术/动作结束点，未硬切，立即换下一方案。",
                            run_id,
                        )
                        if more_candidates_available:
                            continue
                        raise RuntimeError(
                            f"本条可用候选预算 {variant_candidate_limit} 套已经用尽；"
                            f"裂变第 {variant_index} 条仍找不到"
                            "参考时长附近的完整结束点；请调整倍率或更换打乱素材"
                        )
                    if last_returncode == 44:
                        # The runner performs this gate before atomically
                        # publishing its candidate.  Never delete the previous
                        # good single-output file; multi-output candidate paths
                        # are attempt-specific and safe to clean here.
                        if multi_output:
                            candidate_path.unlink(missing_ok=True)
                            compliance_path.unlink(missing_ok=True)
                            if dedup_hash_path:
                                dedup_hash_path.unlink(missing_ok=True)
                        append_log(
                            f"-> {'裂变 ' + str(variant_index) + '/' + str(fission_count) + ' ' if multi_output else ''}"
                            "成片画质门禁未通过：候选未替换正式成片，"
                            "原素材未改动，也尚未进入扣费。",
                            run_id,
                        )
                        visual_quality_reason = renderer_diagnostics.get(
                            "visual_quality_blocked"
                        ) or "检测到相对原素材新增的白底线稿或近黑白连续画面"
                        if multi_output and more_candidates_available:
                            append_log(
                                f"-> 精确原因：{visual_quality_reason} 已换用下一套"
                                "自然时间窗和编排重新生成。",
                                run_id,
                            )
                            continue
                        raise RuntimeError(
                            f"成片画质验收未通过：{visual_quality_reason}"
                        )
                    if last_returncode == 45:
                        if multi_output:
                            candidate_path.unlink(missing_ok=True)
                            compliance_path.unlink(missing_ok=True)
                            if dedup_hash_path:
                                dedup_hash_path.unlink(missing_ok=True)
                        evidence_reason = renderer_diagnostics.get(
                            "visual_quality_evidence"
                        ) or "画质审计证据未能完整生成"
                        append_log(
                            "-> 成片画质审计链路未完成；这是审计证据错误，不会误报成"
                            f"黑白坏片，也不会浪费其余候选重渲染。精确原因：{evidence_reason}",
                            run_id,
                        )
                        raise RuntimeError(
                            f"成片画质审计未完成：{evidence_reason}"
                        )
                    output_after = output_file_signature(candidate_path)
                    output_is_fresh = output_after is not None and output_after != output_before
                    output_is_valid = output_is_fresh and output_after[1] > 0
                    if last_returncode != 0:
                        render_failure_count += 1
                        if multi_output:
                            candidate_path.unlink(missing_ok=True)
                            compliance_path.unlink(missing_ok=True)
                            if dedup_hash_path:
                                dedup_hash_path.unlink(missing_ok=True)
                        if (
                            multi_output
                            and render_failure_count <= FISSION_RENDER_FAILURE_RETRIES
                            and more_candidates_available
                        ):
                            append_log(
                                f"-> 裂变 {variant_index}/{fission_count} 本候选渲染退出码 "
                                f"{last_returncode}；已安全丢弃，自动换下一套方案重试 "
                                f"({render_failure_count}/{FISSION_RENDER_FAILURE_RETRIES})。",
                                run_id,
                            )
                            continue
                        raise RuntimeError(
                            f"裂变第 {variant_index} 条渲染失败（退出码 {last_returncode}）："
                            + (renderer_diagnostics.get("render_process_error")
                               or "子进程未返回具体原因，请保留本次制作日志")
                        )
                    if not output_is_valid:
                        render_failure_count += 1
                        if multi_output:
                            candidate_path.unlink(missing_ok=True)
                            compliance_path.unlink(missing_ok=True)
                            if dedup_hash_path:
                                dedup_hash_path.unlink(missing_ok=True)
                        if (
                            multi_output
                            and render_failure_count <= FISSION_RENDER_FAILURE_RETRIES
                            and more_candidates_available
                        ):
                            append_log(
                                f"-> 裂变 {variant_index}/{fission_count} 本候选没有生成"
                                "新的有效文件；已换下一套方案自动重试 "
                                f"({render_failure_count}/{FISSION_RENDER_FAILURE_RETRIES})。",
                                run_id,
                            )
                            continue
                        raise RuntimeError(
                            f"裂变第 {variant_index} 条未生成本次有效成品文件"
                        )
                    candidate_duration = _media_duration(candidate_path)
                    expected_reference = 210.0 if full_spec_mode else float(target_duration)
                    if preserve_raw_core:
                        shuffle_ref = max(
                            0.3, float(timeline_budgets.get("shuffle", 0.0) or 0.0)
                        )
                        shuffle_src = max(
                            0.3,
                            float(
                                timeline_budgets.get("shuffle_source", shuffle_ref)
                                or shuffle_ref
                            ),
                        )
                        expected_body_reference = min(shuffle_ref, shuffle_src)
                    else:
                        expected_body_reference = expected_reference
                    accepted_tail_limit = natural_tail_limit + (
                        natural_boundary_fallback_extra
                        if natural_boundary_fallback_attempt
                        else 0.0
                    )
                    if preserve_raw_core:
                        shuffle_upper_ref = max(
                            expected_body_reference,
                            float(
                                timeline_budgets.get("shuffle", expected_body_reference)
                                or expected_body_reference
                            ),
                        )
                        if use_hardcut:
                            tail_drop_allowance = 0.5 * max(
                                1, len(variant_materials.get("打乱素材池", []))
                            )
                            minimum_duration = max(
                                0.25,
                                expected_body_reference
                                - max(0.5, slice_seconds + 0.5 + tail_drop_allowance),
                            )
                            maximum_duration = (
                                shuffle_upper_ref
                                + max(accepted_tail_limit, slice_seconds * 2.0 + 3.0)
                                + 0.5
                            )
                        else:
                            natural_shortfall_allowance = max(
                                4.0, expected_body_reference * 0.25
                            )
                            minimum_duration = max(
                                0.25,
                                expected_body_reference - natural_shortfall_allowance,
                            )
                            maximum_duration = (
                                shuffle_upper_ref + accepted_tail_limit + 0.35
                            )
                    elif use_hardcut:
                        minimum_duration = max(0.5, min(expected_reference, core_budget) - 0.35)
                        maximum_duration = expected_reference + max(accepted_tail_limit, slice_seconds * 2.0 + 3.0) + 0.5
                    else:
                        minimum_duration = expected_reference - 0.15
                        maximum_duration = expected_reference + accepted_tail_limit + 0.15
                    if not (
                        math.isfinite(candidate_duration)
                        and minimum_duration <= candidate_duration <= maximum_duration
                    ):
                        raise RuntimeError(
                            f"裂变第 {variant_index} 条成片时长异常：参考 "
                            f"{expected_body_reference:.1f} 秒，实际 {candidate_duration:.3f} 秒"
                        )

                    current_pair_results = []
                    candidate_hashes = None
                    candidate_source_windows = []
                    candidate_visual_quality_gate = None
                    worst_similarity = 0.0
                    if multi_output:
                        candidate_hashes = load_dedup_hash_file(
                            dedup_hash_path, variant_style
                        )
                        candidate_source_windows = load_source_window_audit(
                            dedup_hash_path,
                            allowed_sources=[
                                *variant_materials.get("核心素材", []),
                                *variant_materials.get("打乱素材池", []),
                            ],
                        )
                        candidate_visual_quality_gate = load_visual_quality_gate(
                            dedup_hash_path
                        )
                        dedup_hash_path.unlink(missing_ok=True)
                        for prior_index, prior_hashes in enumerate(comparison_hashes, comparison_start + 1):
                            similarity = frame_hash_similarity_percent(
                                candidate_hashes, prior_hashes
                            )
                            current_pair_results.append(
                                {
                                    "first": prior_index,
                                    "second": variant_index,
                                    "similarity_percent": similarity,
                                }
                            )
                        worst_similarity = max(
                            (item["similarity_percent"] for item in current_pair_results),
                            default=0.0,
                        )
                        if (not use_hardcut) and worst_similarity > FISSION_SIMILARITY_LIMIT:
                            append_log(
                                f"-> 裂变 {variant_index}/{fission_count} 本次最高打乱轨道等比例位置相似度 "
                                f"{worst_similarity:.2f}% > {FISSION_SIMILARITY_LIMIT:.0f}%，"
                                "自动更换下一套自然时间窗和打乱编排。",
                                run_id,
                            )
                            candidate_path.unlink(missing_ok=True)
                            compliance_path.unlink(missing_ok=True)
                            if more_candidates_available:
                                continue
                            raise RuntimeError(
                                f"本条可用候选预算 {variant_candidate_limit} 套已经用尽；"
                                f"裂变第 {variant_index} 条仍高于 "
                                f"{FISSION_SIMILARITY_LIMIT:.0f}%"
                            )

                        v_voice_path, v_voice_label, v_bgm_path, v_bgm_name = _variant_audio_choice(
                            variant_index
                        )
                        final_out_duration = candidate_duration
                        if is_v2_edition:
                            mix_info = hardcut_audio.apply_final_audio_mix(
                                candidate_path,
                                keep_original_audio=keep_orig_audio,
                                original_volume_percent=audio_dub["original_volume"],
                                voice_path=v_voice_path,
                                bgm_path=v_bgm_path,
                                voice_volume_percent=audio_dub["voice_volume"],
                                bgm_volume_percent=audio_dub["bgm_volume"],
                                voice_delay_seconds=0.0,
                            )
                            final_out_duration = mix_info["video_duration_seconds"]
                            picked_tags = []
                            if v_voice_label:
                                picked_tags.append(f"配音:“{v_voice_label}”")
                            if v_bgm_name:
                                picked_tags.append(f"BGM:“{v_bgm_name}”")
                            picked_note = f"（{'，'.join(picked_tags)}）" if picked_tags else ""
                            append_log(
                                f"-> 裂变 {variant_index}/{fission_count} 打乱段音轨处理完成：{mix_info['summary']}{picked_note}（打乱段 {final_out_duration:.2f} 秒）。",
                                run_id,
                            )
                        core_prepend_info = (
                            attach_untouched_core_videos(
                                run_id,
                                candidate_path,
                                core_order,
                                material_base_dir,
                            )
                            if preserve_raw_core
                            else None
                        )
                        if core_prepend_info:
                            final_out_duration = core_prepend_info["final_duration_seconds"]
                        opening_info = attach_optional_opening(
                            run_id,
                            candidate_path,
                            opening_names,
                            variant_index,
                            material_base_dir,
                            mute_opening=False,
                        )
                        if opening_info:
                            final_out_duration = opening_info["final_duration_seconds"]
                        final_path = run_dir / f"V17裂变成片_第{variant_index:02d}条.mp4"
                        final_compliance_path = final_path.with_suffix(".json")
                        final_compliance_path = run_dir / (
                            f"V17合规报告_第{variant_index:02d}条.json"
                        )
                        if not fill_session:
                            os.replace(candidate_path, final_path)
                            if compliance_path.exists():
                                os.replace(compliance_path, final_compliance_path)
                        accepted_paths.append(final_path)
                        accepted_durations.append(final_out_duration)
                        accepted_hashes.append(candidate_hashes)
                        pair_results.extend(current_pair_results)
                        source_window_durations = summarize_source_window_durations(
                            candidate_source_windows
                        )
                        variant_plans.append(
                            {
                                "index": variant_index,
                                "opening_video": opening_info,
                                "untouched_core": core_prepend_info,
                                "assigned_voice": v_voice_label,
                                "assigned_bgm": v_bgm_name,
                                "attempt": attempt + 1,
                                "material_plan_index": material_plan_index,
                                "shuffle_window_index": shuffle_window_index,
                                "core_window_index": core_window_index,
                                "source_windows": candidate_source_windows,
                                "visual_quality_gate": candidate_visual_quality_gate,
                                **source_window_durations,
                                "seed": variant_seed,
                                "materials": {
                                    pool: list(variant_materials.get(pool, []))
                                    for pool in POOLS
                                },
                                "core_opener": (
                                    variant_materials.get("核心素材", [""])[0]
                                    if variant_materials.get("核心素材")
                                    else ""
                                ),
                                "core_opener_policy": (
                                    "untouched-raw-core-prefix-v2"
                                    if preserve_raw_core
                                    else (
                                        "unique-first-balanced-cycle"
                                        if len(selected_materials.get("核心素材", [])) > 1
                                        else "single-core-legacy"
                                    )
                                ),
                                "effects": list(variant_effects),
                                "dedup_style": variant_style,
                                "shuffle_scope": (
                                    "shuffle-only-after-untouched-core"
                                    if preserve_raw_core
                                    else "shuffle-track-with-complete-core-interleave"
                                ),
                                "mask_source": mask_source_name,
                                "stickers": variant_stickers,
                                "timepin_zoom": clone_timepin_zoom_settings(timepin_zoom),
                                "corner_mask_reveal": clone_corner_mask_reveal_settings(
                                    corner_mask_reveal
                                ),
                                "max_similarity_percent": worst_similarity,
                                "similarity_scope": "within_retry_batch",
                                "similarity_batch_start": comparison_start,
                                "retry_round": fill_session.round if fill_session else 0,
                                "reference_duration_seconds": round(expected_reference, 3),
                                "actual_duration_seconds": round(final_out_duration, 3),
                                "duration_delta_seconds": round(
                                    final_out_duration - expected_reference, 3
                                ),
                                "natural_boundary_fallback_attempt": (
                                    natural_boundary_fallback_attempt
                                ),
                                "natural_boundary_fallback_extended": (
                                    final_out_duration
                                    > expected_reference + natural_tail_limit + 0.15
                                ),
                            }
                        )
                        if fill_session:
                            try:
                                fill_session.publish(candidate_path, final_path, compliance_path,
                                                     final_compliance_path, fill_snapshot())
                            except Exception as publish_error:
                                raise FillCheckpointError('成片发布检查点失败：' + str(publish_error)) from publish_error
                        append_log(
                            f"-> 裂变 {variant_index}/{fission_count} 已验收；"
                            f"实际 {final_out_duration:.2f} 秒；与本批次既有成片最高打乱轨道"
                            f"等比例位置相似度 {worst_similarity:.2f}%"
                            + (
                                "（无40%门槛拦截，已自动最低相似度排片）。"
                                if use_hardcut
                                else "。"
                            )
                            + (
                                f"开头/核心原片已100%原样保留（核心首段“{variant_materials['核心素材'][0]}”）。"
                                if preserve_raw_core and variant_materials.get("核心素材")
                                else (
                                    f"本条从核心“{variant_materials['核心素材'][0]}”开场，"
                                    "其余已选核心仍完整保留。"
                                    if len(selected_materials.get("核心素材", [])) > 1
                                    else ""
                                )
                            ),
                            run_id,
                        )
                        with state_lock:
                            if state["run_id"] == run_id:
                                state["fission_completed"] = variant_index
                        if variant_index < int(fission_count):
                            try:
                                checkpoint_report = build_partial_fission_report(
                                    run_id,
                                    fission_count,
                                    accepted_paths,
                                    accepted_durations,
                                    pair_results,
                                    variant_plans,
                                    (
                                        f"已验收前 {variant_index} 条；"
                                        f"第 {variant_index + 1} 条仍在制作。"
                                    ),
                                    target_duration,
                                    timeline_budgets,
                                    natural_tail_limit,
                                    dedup_style_plan,
                                    dedup_style_source,
                                    timepin_zoom,
                                    corner_mask_reveal,
                                    FISSION_PLAN_POLICY,
                                    fission_plan_key,
                                    batch_candidate_budget,
                                    batch_candidate_attempts_used,
                                )
                                publish_fission_report(run_dir, checkpoint_report)
                                checkpoint_running_fission_result(
                                    run_id,
                                    fission_count,
                                    accepted_paths,
                                    accepted_durations,
                                )
                            except Exception as checkpoint_exc:
                                # Checkpointing improves crash recovery, but an
                                # unavailable disk/database must not invalidate an
                                # already accepted video or stop later variants.
                                append_log(
                                    "-> 已验收成片的中途检查点暂未完整发布；"
                                    "不影响继续制作："
                                    f"{redact_local_paths(checkpoint_exc)}",
                                    run_id,
                                )
                    else:
                        single_final_duration = candidate_duration
                        if is_v2_edition:
                            s_voice_path, s_voice_label, s_bgm_path, s_bgm_name = _variant_audio_choice(1)
                            mix_info = hardcut_audio.apply_final_audio_mix(
                                single_output_path,
                                keep_original_audio=keep_orig_audio,
                                original_volume_percent=audio_dub["original_volume"],
                                voice_path=s_voice_path,
                                bgm_path=s_bgm_path,
                                voice_volume_percent=audio_dub["voice_volume"],
                                bgm_volume_percent=audio_dub["bgm_volume"],
                                voice_delay_seconds=0.0,
                            )
                            single_final_duration = mix_info["video_duration_seconds"]
                            picked_tags = []
                            if s_voice_label:
                                picked_tags.append(f"配音:“{s_voice_label}”")
                            if s_bgm_name:
                                picked_tags.append(f"BGM:“{s_bgm_name}”")
                            picked_note = f"（{'，'.join(picked_tags)}）" if picked_tags else ""
                            append_log(
                                f"-> 打乱段音轨处理完成：{mix_info['summary']}{picked_note}（打乱段 {single_final_duration:.2f} 秒）。",
                                run_id,
                            )
                        if preserve_raw_core:
                            core_prepend_info = attach_untouched_core_videos(
                                run_id,
                                single_output_path,
                                core_order,
                                material_base_dir,
                            )
                            if core_prepend_info:
                                single_final_duration = core_prepend_info["final_duration_seconds"]
                        opening_info = attach_optional_opening(
                            run_id,
                            single_output_path,
                            opening_names,
                            1,
                            material_base_dir,
                            mute_opening=False,
                        )
                        if opening_info:
                            single_final_duration = opening_info["final_duration_seconds"]
                        accepted_paths = [single_output_path]
                        accepted_durations = [single_final_duration]
                    accepted = True
                    break

                if not accepted:
                    raise RuntimeError(
                        f"本条可用候选预算 {variant_candidate_limit} 套已经用尽；"
                        f"裂变第 {variant_index} 条仍未通过验收"
                    )
            except (RuntimeError, OSError, ValueError) as render_error:
                if fill_session and isinstance(render_error, FillCheckpointError):
                    committed = fill_session.verified_snapshot()
                    accepted_paths = committed.get('accepted_paths', [])
                    accepted_durations = committed.get('accepted_durations', [])
                    accepted_hashes = committed.get('accepted_hashes', [])
                    pair_results = committed.get('pair_results', [])
                    variant_plans = committed.get('variant_plans', [])
                if (not fill_session or isinstance(render_error, (QueueTaskSkipped, FillCheckpointError))
                        or queue_skip_requested(run_id) or task_queue_shutdown_event.is_set()):
                    raise
                if not fill_session.retry(
                    render_error, fill_snapshot(),
                    lambda: validate_queued_materials(
                        dict(
                            selected_materials,
                            **{
                                '开头视频': opening_names,
                                '配音音频': voice_audio_names,
                                '参考音色': ref_voice_names,
                                '背景音乐': bgm_audio_names,
                            },
                        ),
                        material_base_dir,
                    )):
                    raise RuntimeError(fill_session.data['error']) from render_error
                batch_candidate_attempts_used = 0
                append_log(fill_session.public()['message'], run_id)
                variant_index = len(accepted_paths) + 1
                continue
            variant_index += 1

        batch_used_slices_path.unlink(missing_ok=True)
        for _tmp_wav in synthesized_voice_temps:
            _tmp_wav.unlink(missing_ok=True)

        if fill_session:
            fill_session.rendered()

        fission_zip_path = None
        max_similarity = None
        if multi_output:
            fixed_cache_dir = run_dir / ".fixed-stage-cache"
            try:
                if (
                    fixed_cache_dir.name == ".fixed-stage-cache"
                    and fixed_cache_dir.parent == run_dir
                    and fixed_cache_dir.is_dir()
                ):
                    shutil.rmtree(fixed_cache_dir)
            except OSError as cleanup_exc:
                append_log(
                    "-> 固定段临时缓存暂时被系统占用，稍后可自动清理；"
                    f"不影响已验收成片：{redact_local_paths(cleanup_exc)}",
                    run_id,
                )
            max_similarity = max(
                (item["similarity_percent"] for item in pair_results), default=0.0
            )
            report = {
                "metric_version": FISSION_METRIC_VERSION,
                "runtime_stability": runtime_stability_metadata(),
                "plan_policy": FISSION_PLAN_POLICY,
                "plan_key": fission_plan_key,
                "candidate_budget": batch_candidate_budget,
                "candidate_attempts_used": batch_candidate_attempts_used,
                "passed": True,
                "threshold_percent": FISSION_SIMILARITY_LIMIT,
                "similarity_scope": "within_retry_batch",
                "definition": (
                    "直接对穿插核心前的完整打乱镜头轨道按等比例时间位置抽帧计算画面哈希相似度；"
                    "自动补做按新批次，仅比较同轮补做内的成片，不保证跨轮相似度；"
                    "核心素材按自然窗口穿插，但不进入该指标；"
                    "不是平台官方查重分数，也不是素材内容集合重合率。"
                ),
                "run_id": run_id,
                "video_count": int(fission_count),
                "duration_policy": NATURAL_TAIL_POLICY,
                "reference_duration_seconds": round(float(target_duration), 3),
                "duration_multiplier": round(float(timeline_budgets["multiplier"]), 1),
                "core_duration_seconds": round(float(timeline_budgets["core"]), 3),
                "core_source_duration_seconds": round(
                    float(timeline_budgets["core_source"]), 3
                ),
                "core_effective_duration_seconds": round(
                    float(timeline_budgets["core_effective"]), 3
                ),
                "core_inclusion_budget_seconds": round(
                    float(timeline_budgets["core_budget"]), 3
                ),
                "shuffle_source_duration_seconds": round(
                    float(timeline_budgets["shuffle_source"]), 3
                ),
                "minimum_shuffle_duration_seconds": round(
                    float(timeline_budgets["minimum_shuffle"]), 3
                ),
                "duration_rules": list(DURATION_RULES),
                "core_window_policy": CORE_WINDOW_POLICY,
                "shuffle_window_policy": SHUFFLE_WINDOW_POLICY,
                "visual_quality_policy": VISUAL_QUALITY_POLICY,
                "visual_quality_gate": {
                    "version": VISUAL_QUALITY_GATE_VERSION,
                    "gate_kind": "clean-style-invariant",
                    "status": "passed",
                    "validated_variants": [
                        int(plan["index"])
                        for plan in variant_plans
                        if isinstance(plan.get("visual_quality_gate"), dict)
                        and plan["visual_quality_gate"].get("passed") is True
                    ],
                },
                "reference_is_hard_cap": False,
                "natural_tail_limit_seconds": round(natural_tail_limit, 3),
                "natural_boundary_fallback_extra_seconds": round(
                    min(natural_tail_limit, 18.0),
                    3,
                ),
                "natural_boundary_fallback_extended_variants": [
                    int(plan["index"])
                    for plan in variant_plans
                    if plan.get("natural_boundary_fallback_extended")
                ],
                "output_durations_seconds": [
                    round(float(value), 3) for value in accepted_durations
                ],
                "actual_duration_min_seconds": round(min(accepted_durations), 3),
                "actual_duration_max_seconds": round(max(accepted_durations), 3),
                "protected_materials_excluded": ["核心素材"],
                "shuffle_scope": [
                    "每个打乱源按有界自然时间窗取材并连贯重组",
                    "长核心按预算和自然边界取窗，裂变错开窗口",
                    "所有候选均通过 clean-only 渲染配置约束",
                    "蒙版从打乱素材中自动选择且不移除主轨素材",
                ],
                "core_opener_policy": (
                    variant_plans[0].get(
                        "core_opener_policy",
                        "single-core-legacy",
                    )
                    if variant_plans
                    else "single-core-legacy"
                ),
                "core_openers": [
                    str(plan.get("core_opener") or "")
                    for plan in variant_plans
                ],
                "shuffle_reference_seconds": round(float(timeline_budgets["shuffle"]), 3),
                "model_style_plan": ["clean", "clean", "clean"],
                "model_style_source": VISUAL_QUALITY_POLICY,
                "timepin_zoom": clone_timepin_zoom_settings(timepin_zoom),
                "corner_mask_reveal": clone_corner_mask_reveal_settings(
                    corner_mask_reveal
                ),
                "max_similarity_percent": max_similarity,
                "pairs": pair_results,
                "outputs": [path.name for path in accepted_paths],
                "variants": variant_plans,
            }
            try:
                fission_zip_path = build_fission_bundle(
                    run_dir,
                    accepted_paths,
                    report,
                )
            except Exception as bundle_exc:
                # All videos are already accepted.  A convenience ZIP failure
                # must degrade to individual downloads, never fail the batch.
                publish_fission_report(run_dir, report)
                append_log(
                    "-> 全部成片均已完成，但整包生成失败；"
                    "已保留逐条下载入口："
                    f"{redact_local_paths(bundle_exc)}",
                    run_id,
                )

        # Keep a finished renderer's result in the current task until the user
        # resumes; after this checkpoint the durable finalizing boundary wins
        # and pause is intentionally no longer offered.
        wait_at_queue_pause_checkpoint(run_id)
        if queue_skip_requested(run_id):
            raise QueueTaskSkipped("用户已跳过本条任务，队列将继续下一条")
        queue_store = get_task_queue_store(create=False)
        queue_record = (
            retry_queue_store_operation(
                lambda: queue_store.get(run_id),
                run_id,
                "读取队列状态",
            )
            if queue_store is not None
            else None
        )
        queue_result = queue_result_for_outputs(
            run_id,
            fission_count,
            single_output_path,
            accepted_paths,
            accepted_durations,
            bundle_exists=bool(fission_zip_path) if multi_output else True,
        )
        queue_result["auto_save"] = pending_auto_save_metadata(
            auto_save_directory
        )
        billing_state = "not_started" if CUSTOMER_BILLING_REQUIRED else "not_required"
        if CUSTOMER_BILLING_REQUIRED and queue_record is None:
            raise RuntimeError(
                "计费任务缺少持久化队列记录，已停止扣费和成品交付"
            )
        if queue_record is not None and not mark_queue_task_finalizing(
            run_id,
            queue_result,
            billing_state,
        ):
            if queue_skip_requested(run_id) or queue_record.get("status") == "skip_requested":
                raise QueueTaskSkipped("用户已跳过本条任务，队列将继续下一条")
            raise RuntimeError("无法锁定队列任务的成品保存阶段，已停止后续扣费")
        queue_finalizing = queue_record is not None
        with state_lock:
            if state["run_id"] == run_id:
                state["returncode"] = 0
                state["status"] = "finalizing"
                state["progress"] = 99
                state["output_ready"] = not multi_output
                state["output_path"] = str(single_output_path)
                state["compliance_path"] = str(single_compliance_path)
                state["fission_ready"] = multi_output
                state["fission_output_paths"] = [str(path) for path in accepted_paths] if multi_output else []
                state["fission_output_durations"] = list(accepted_durations) if multi_output else []
                state["fission_zip_path"] = str(fission_zip_path) if fission_zip_path else ""
                state["fission_max_similarity"] = max_similarity
                state["output_duration_seconds"] = (
                    accepted_durations[0] if not multi_output and accepted_durations else None
                )
                if multi_output:
                    duration_summary = "/".join(
                        f"{value:.1f}s" for value in accepted_durations
                    )
                    state["stage"] = (
                        f"裂变完成：{fission_count} 条，实际 {duration_summary}，"
                        f"最高打乱轨道等比例位置相似度 {max_similarity:.2f}%"
                    )
                else:
                    state["stage"] = "制作完成"

        if not CUSTOMER_BILLING_REQUIRED:
            append_log(
                "-> ERP 直传模式：按当前扫码用户逐条上报使用记录；"
                "授权过期时保留待补传记录，重新扫码后补传。",
                run_id,
            )
            try:
                erp_relay_summary = report_accepted_output_successes(
                    customer_id, customer_name, run_id, accepted_paths
                )
                queue_result["erp_relay"] = {
                    "state": erp_delivery_summary_state(erp_relay_summary),
                    "contract": "status-ok",
                    "confirmed_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "total": int(erp_relay_summary.get("total") or 0),
                    "relay_ok_count": int(
                        erp_relay_summary.get("relay_ok_count") or 0
                    ),
                    "backup_pending_count": int(
                        erp_relay_summary.get("backup_pending_count") or 0
                    ),
                    "direct_ok_count": int(
                        erp_relay_summary.get("direct_ok_count") or 0
                    ),
                    "direct_pending_count": int(
                        erp_relay_summary.get("direct_pending_count") or 0
                    ),
                    "events": list(erp_relay_summary.get("events") or []),
                }
                if queue_store is not None:
                    retry_queue_store_operation(
                        lambda: queue_store.update_preserved_result(
                            run_id,
                            queue_result,
                        ),
                        run_id,
                        "保存 ERP 直传状态",
                    )
            except Exception as exc:
                if STRICT_ERP_RELAY:
                    raise
                record_hidden_erp_log(
                    run_id,
                    f"batch_report_failed owner_user_id={TENANT_USER_ID or '-'} error={exc}",
                )
                append_log(
                    f"-> 使用记录批量上报异常，已写入隐藏日志：{exc}",
                    run_id,
                )
        else:
            pipeline_contract = "local-videos-debit-usage-db-optional-direct-erp-v2"
            pipeline_sequence = [
                "local_videos/report",
                "customers/recharge:-1-per-video",
                "erp/page_req_log:database-only-status-ok",
                "erp-direct:per-user-token-when-enabled",
            ]
            queue_result["business_pipeline"] = {
                "state": "started",
                "contract": pipeline_contract,
                "sequence": pipeline_sequence,
                "started_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "last_stage": "not_started",
                "local_videos": {"state": "pending"},
                "recharge": {
                    "state": "pending",
                    "confirmed_count": 0,
                    "total": len(accepted_paths),
                },
                "erp_relay": {"state": "pending"},
            }

            def persist_business_stage(stage_name, details):
                pipeline = queue_result["business_pipeline"]
                now_text = time.strftime("%Y-%m-%d %H:%M:%S")
                pipeline["last_stage"] = stage_name
                pipeline["updated_at"] = now_text
                if stage_name == "local_videos_reported":
                    pipeline["local_videos"] = {
                        "state": "confirmed",
                        "confirmed_at": now_text,
                        **details,
                    }
                elif stage_name == "balance_debited":
                    pipeline["recharge"] = {
                        "state": (
                            "confirmed"
                            if int(details.get("confirmed_count") or 0)
                            == int(details.get("total") or 0)
                            else "in_progress"
                        ),
                        "updated_at": now_text,
                        **details,
                    }
                elif stage_name == "erp_reported":
                    pipeline["erp_relay"] = {
                        "state": "confirmed",
                        "confirmed_at": now_text,
                        **details,
                    }
                if queue_store is not None:
                    retry_queue_store_operation(
                        lambda: queue_store.update_preserved_result(
                            run_id,
                            queue_result,
                        ),
                        run_id,
                        f"保存三阶段业务进度 {stage_name}",
                    )

            try:
                # Serialize the complete remote business transaction locally.
                # Each confirmed remote write is durably checkpointed before
                # the next stage, so an ambiguous interruption is never retried
                # automatically and can be reconciled by local_task_id.
                with operation_lock:
                    if queue_store is not None:
                        billing_started = retry_queue_store_operation(
                            lambda: queue_store.mark_billing_started(run_id),
                            run_id,
                            "保存三阶段业务准备状态",
                        )
                        if not billing_started:
                            raise RuntimeError(
                                "三阶段业务准备状态无法确认，已停止远端写入并保留成品"
                            )
                        retry_queue_store_operation(
                            lambda: queue_store.update_preserved_result(
                                run_id,
                                queue_result,
                            ),
                            run_id,
                            "保存三阶段业务初始状态",
                        )
                    pipeline_result = complete_success_business_pipeline(
                        customer_id,
                        customer_name,
                        run_id,
                        accepted_paths,
                        stage_callback=persist_business_stage,
                    )
                    now_text = time.strftime("%Y-%m-%d %H:%M:%S")
                    queue_result["business_pipeline"].update(
                        {
                            "state": "confirmed",
                            "confirmed_at": now_text,
                            "last_stage": "erp_reported",
                            "video_count": int(
                                pipeline_result.get("video_count") or 0
                            ),
                            "debit_confirmed_count": int(
                                pipeline_result.get("debit_confirmed_count") or 0
                            ),
                        }
                    )
                    erp_relay_summary = dict(
                        pipeline_result.get("erp_relay") or {}
                    )
                    queue_result["erp_relay"] = {
                        "state": erp_delivery_summary_state(erp_relay_summary),
                        "contract": "status-ok",
                        "confirmed_at": now_text,
                        "total": int(erp_relay_summary.get("total") or 0),
                        "relay_ok_count": int(
                            erp_relay_summary.get("relay_ok_count") or 0
                        ),
                        "backup_pending_count": int(
                            erp_relay_summary.get("backup_pending_count") or 0
                        ),
                        "direct_ok_count": int(
                            erp_relay_summary.get("direct_ok_count") or 0
                        ),
                        "direct_pending_count": int(
                            erp_relay_summary.get("direct_pending_count") or 0
                        ),
                        "events": list(erp_relay_summary.get("events") or []),
                    }
                    if queue_store is not None:
                        retry_queue_store_operation(
                            lambda: queue_store.update_preserved_result(
                                run_id,
                                queue_result,
                            ),
                            run_id,
                            "保存三阶段业务完成回执",
                        )
                        billing_confirmed = retry_queue_store_operation(
                            lambda: queue_store.mark_billing_confirmed(run_id),
                            run_id,
                            "保存三阶段业务确认状态",
                        )
                        if not billing_confirmed:
                            raise RuntimeError(
                                "三个远端阶段均已返回成功，但本地确认状态无法保存"
                            )
                try:
                    append_log(
                        f"-> 三阶段业务完成：{len(accepted_paths)} 条成片已入库，"
                        f"逐条扣次 {len(accepted_paths)} 次，旧计费服务回执均返回 status=ok。",
                        run_id,
                    )
                except Exception:
                    # The durable queue state and all three remote receipts are
                    # already confirmed; a display-log failure must not turn a
                    # completed transaction into an ambiguous retry candidate.
                    pass
            except Exception as exc:
                pipeline = queue_result.get("business_pipeline") or {}
                pipeline.update(
                    {
                        "state": "review_required",
                        "failed_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                        "error": redact_local_paths(exc),
                    }
                )
                queue_result["business_pipeline"] = pipeline
                if queue_store is not None:
                    try:
                        retry_queue_store_operation(
                            lambda: queue_store.update_preserved_result(
                                run_id,
                                queue_result,
                            ),
                            run_id,
                            "保存三阶段业务待核对状态",
                        )
                    except Exception:
                        pass
                    try:
                        retry_queue_store_operation(
                            lambda: queue_store.mark_billing_uncertain(run_id),
                            run_id,
                            "保存待核对状态",
                        )
                    except Exception:
                        # State-transition validation errors are not transient
                        # SQLite failures.  The worker will still leave the
                        # finalizing task for manual review rather than retry it.
                        pass
                record_billing_warning(
                    run_id,
                    "成片已生成，但三阶段业务链路未全部确认："
                    f"{exc}。请按任务 ID 核对成片库、扣次和 ERP，勿自动重复写入",
                )
                raise
        with state_lock:
            if state["run_id"] == run_id:
                state["status"] = "succeeded"
                state["progress"] = 100
        append_log("运行完成。", run_id)
    except Exception as exc:
        if fill_session is not None and not queue_finalizing:
            committed = fill_session.verified_snapshot()
            accepted_paths = committed.get('accepted_paths', [])
            accepted_durations = committed.get('accepted_durations', [])
            accepted_hashes = committed.get('accepted_hashes', [])
            pair_results = committed.get('pair_results', [])
            variant_plans = committed.get('variant_plans', [])
        was_queue_skip = isinstance(exc, QueueTaskSkipped)
        public_error = redact_local_paths(exc)
        partial_delivery_ready = False
        if (
            multi_output
            and accepted_paths
            and not was_queue_skip
            and not queue_finalizing
        ):
            try:
                partial_report = build_partial_fission_report(
                    run_id,
                    fission_count,
                    accepted_paths,
                    accepted_durations,
                    pair_results,
                    variant_plans,
                    public_error,
                    target_duration,
                    timeline_budgets,
                    natural_tail_limit,
                    dedup_style_plan,
                    dedup_style_source,
                    timepin_zoom,
                    corner_mask_reveal,
                    FISSION_PLAN_POLICY,
                    fission_plan_key,
                    batch_candidate_budget,
                    batch_candidate_attempts_used,
                )
                partial_zip_path = None
                try:
                    partial_zip_path = build_fission_bundle(
                        run_dir,
                        accepted_paths,
                        partial_report,
                    )
                except Exception as bundle_exc:
                    # The validated MP4 files are the primary artifacts.  ZIP
                    # creation is a convenience and must never make them all
                    # unavailable again.
                    publish_fission_report(run_dir, partial_report)
                    append_log(
                        "-> 已完成成片均已保留，但压缩包生成失败；"
                        f"可逐条下载：{redact_local_paths(bundle_exc)}",
                        run_id,
                    )
                completed_count = len(accepted_paths)
                accepted_max_similarity = float(
                    partial_report.get("max_similarity_percent") or 0.0
                )
                partial_stage = (
                    f"部分完成：已保留 {completed_count}/{int(fission_count)} 条；"
                    f"第 {completed_count + 1} 条未通过验收：{public_error}"
                )
                with state_lock:
                    if state["run_id"] == run_id:
                        state["returncode"] = last_returncode if last_returncode else -2
                        state["status"] = "failed"
                        state["progress"] = max(
                            1,
                            min(
                                99,
                                round(completed_count * 100 / int(fission_count)),
                            ),
                        )
                        state["stage"] = partial_stage
                        state["output_ready"] = False
                        state["fission_ready"] = True
                        state["fission_completed"] = completed_count
                        state["fission_output_paths"] = [
                            str(path) for path in accepted_paths
                        ]
                        state["fission_output_durations"] = list(
                            accepted_durations
                        )
                        state["fission_zip_path"] = (
                            str(partial_zip_path) if partial_zip_path else ""
                        )
                        state["fission_max_similarity"] = accepted_max_similarity
                        state["output_duration_seconds"] = None
                try:
                    cleanup_incomplete_fission_artifacts(run_dir, run_id)
                except Exception as cleanup_exc:
                    # Keep this outer guard even though the helper is itself
                    # best-effort; a future cleanup regression must not revoke
                    # an already-published partial delivery.
                    append_log(
                        "-> 临时文件暂时无法清理；已完成成片和下载入口不受影响："
                        f"{redact_local_paths(cleanup_exc)}",
                        run_id,
                    )
                append_log(
                    f"-> 批次部分完成：前 {completed_count} 条已经逐条验收并安全保留；"
                    f"第 {completed_count + 1} 条失败只影响本条。"
                    + (
                        "可下载已完成成片整包。"
                        if partial_zip_path
                        else "可分别下载每条已完成成片。"
                    ),
                    run_id,
                )
                append_log(
                    "-> 本批未全部完成；自动补做已停止，保留已验收成片及具体失败原因。",
                    run_id,
                )
                partial_delivery_ready = True
            except Exception as preserve_exc:
                append_log(
                    "-> 部分成片发布清单未能完成，但已经验收的 MP4 不会删除："
                    f"{redact_local_paths(preserve_exc)}",
                    run_id,
                )
        if partial_delivery_ready:
            if CUSTOMER_BILLING_REQUIRED:
                append_log(
                    "-> 整批未完成：不向成片数据库写入伪失败记录，"
                    "也不执行扣次或 ERP 成功上报。",
                    run_id,
                )
            return
        if queue_finalizing and not was_queue_skip:
            # The renderer already produced and durably registered the output.
            # A later reporting/billing/bookkeeping error must never delete the
            # file or make the task automatically retryable.
            record_billing_warning(
                run_id,
                "成片已经保留，但收尾状态需要核对："
                f"{public_error}。系统不会自动重做本条",
            )
            with state_lock:
                if state["run_id"] == run_id:
                    state["returncode"] = 0
                    state["status"] = "review_required"
                    state["progress"] = 100
                    state["stage"] = "成片已保留，收尾状态待核对"
            return
        append_log(
            f"{'本条已停止' if was_queue_skip else '运行异常'}：{public_error}，未登记成功使用记录。",
            run_id,
        )
        with state_lock:
            if state["run_id"] == run_id:
                state["returncode"] = last_returncode if last_returncode else -2
                state["status"] = "skipped" if was_queue_skip else "failed"
                state["stage"] = (
                    "本条已停止，队列继续下一条"
                    if was_queue_skip
                    else f"制作失败：{public_error}"
                )
                state["output_ready"] = False
                state["fission_ready"] = False
                state["fission_output_paths"] = []
                state["fission_output_durations"] = []
                state["fission_zip_path"] = ""
                state["output_duration_seconds"] = None
        if multi_output and not fill_enabled and (not accepted_paths or was_queue_skip):
            try:
                if cleanup_failed_fission_run(run_dir, run_id):
                    append_log("-> 本次未通过的裂变候选和临时打包文件已清理。", run_id)
            except OSError as cleanup_exc:
                append_log(f"-> 裂变临时文件清理未完成：{cleanup_exc}", run_id)
        if CUSTOMER_BILLING_REQUIRED and not was_queue_skip:
            append_log(
                "-> 剪辑失败：不写入成片数据库，不扣次，也不发送 ERP 成功记录。",
                run_id,
            )
    finally:
        for _tmp_wav in synthesized_voice_temps:
            _tmp_wav.unlink(missing_ok=True)
        if fill_session is not None:
            fill_session.close()
        elapsed_seconds = max(0.0, time.monotonic() - job_started_monotonic)
        with state_lock:
            final_status = (
                str(state.get("status") or "unknown")
                if state.get("run_id") == run_id
                else "superseded"
            )
            encoder_status = dict(state.get("runtime_encoder") or {})
        benchmark_encoders = list(encoder_status.get("used_encoders") or [])
        benchmark_encoder = encoder_status.get("selected", "unknown")
        if encoder_status.get("fallback") and len(set(benchmark_encoders)) > 1:
            benchmark_encoder = "mixed"
        append_log(
            "V16_JOB_BENCHMARK "
            + json.dumps(
                {
                    "status": final_status,
                    "wall_seconds": round(elapsed_seconds, 3),
                    "accepted_outputs": len(accepted_paths),
                    "encoder": benchmark_encoder,
                    "fallback": bool(encoder_status.get("fallback")),
                    "fallback_events": int(
                        encoder_status.get("fallback_events") or 0
                    ),
                    "used_encoders": benchmark_encoders,
                    "paused_time_included": True,
                },
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            run_id,
        )
        for _temp_key in ("batch_used_slices_path", "synthesized_voice_temp"):
            _temp_path = locals().get(_temp_key)
            if isinstance(_temp_path, Path):
                try:
                    _temp_path.unlink(missing_ok=True)
                except OSError:
                    pass
        if disk_reservation_acquired:
            release_renderer_disk_reservation(run_id)
        if vision_config["key_env"]:
            base_env.pop(vision_config["key_env"], None)
        with state_lock:
            if state["run_id"] == run_id:
                state["running"] = False
                state["finished_at"] = time.strftime("%Y-%m-%d %H:%M:%S")


def queue_task_title(config):
    task_name = str(config.get("task_name") or "视频制作任务").strip()
    fission_count = int(config.get("fission_count") or 1)
    target_duration = float(config.get("target_duration") or 0.0)
    selected = config.get("selected_materials") or {}
    mode = f"裂变 {fission_count} 条" if fission_count > 1 else "单条视频"
    return (
        f"{task_name} · {mode} · 约 {target_duration:.1f} 秒 · "
        f"核心 {len(selected.get('核心素材', []))} / "
        f"打乱 {len(selected.get('打乱素材池', []))}"
    )


def validate_queued_materials(selected_materials, material_root=None):
    material_root = Path(material_root or BASE_DIR).resolve()
    for pool in POOLS:
        for name in selected_materials.get(pool, []):
            pool_dir = (material_root / pool).resolve()
            candidate = pool_dir / str(name)
            if (
                not isinstance(name, str)
                or Path(name).name != name
                or candidate.is_symlink()
                or candidate.resolve(strict=False).parent != pool_dir
                or not candidate.is_file()
            ):
                raise RuntimeError(f"排队时选择的素材已经不存在：{pool}/{name}")


def initialize_queue_run_state(run_id, config, output_path, compliance_path):
    run_id = str(run_id)
    with state_lock:
        run_state = _clone_task_state(_base_state)
        run_state.update(
            {
                "running": True,
                "status": "running",
                "run_id": run_id,
                "progress": 1,
                "stage": "队列已轮到本条，正在启动",
                "started_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "finished_at": None,
                "returncode": None,
                "output_ready": False,
                "output_path": str(output_path),
                "compliance_path": str(compliance_path),
                "fission_ready": False,
                "fission_count": int(config["fission_count"]),
                "fission_completed": 0,
                "fission_similarity_limit": FISSION_SIMILARITY_LIMIT,
                "fission_max_similarity": None,
                "fission_output_paths": [],
                "fission_output_durations": [],
                "fission_zip_path": "",
                "current_variant": 1,
                "effects": list(config["face_effects"]),
                "stickers": dict(config["sticker_settings"]),
                "timepin_zoom": clone_timepin_zoom_settings(
                    config["timepin_zoom"]
                ),
                "corner_mask_reveal": clone_corner_mask_reveal_settings(
                    config["corner_mask_reveal"]
                ),
                "target_duration": float(config["target_duration"]),
                "duration_multiplier": float(config["duration_multiplier"]),
                "duration_policy": NATURAL_TAIL_POLICY,
                "natural_tail_limit_seconds": natural_tail_allowance(
                    config["target_duration"]
                ),
                "output_duration_seconds": None,
                "sync_mode": str(config["sync_mode"]),
                "vision_provider": str(config["vision_provider"]),
                "dedup_style_plan": list(config["dedup_style_plan"]),
                "dedup_style_source": str(config["dedup_style_source"]),
                "full_spec_mode": bool(config["full_spec_mode"]),
                "billing_warning": "",
                "runtime_encoder": {},
                "log": [],
            }
        )
        task_run_states[run_id] = run_state
        task_run_states.move_to_end(run_id)
        _prune_task_run_states_locked()
    return run_state


def queue_result_for_run(run_id, config, job_state, output_path):
    if int(config["fission_count"]) > 1:
        requested_count = int(config["fission_count"])
        outputs = list(job_state.get("fission_outputs") or [])
        completed_count = len(outputs)
        partial = 0 < completed_count < requested_count
        result = {
            "kind": "fission",
            "delivery_state": "partial" if partial else "complete",
            "bundle_url": (
                f"/download-fission/{run_id}/bundle" if completed_count else ""
            ),
            "outputs": outputs,
            "count": requested_count,
            "requested_count": requested_count,
            "completed_count": completed_count,
            "auto_save": pending_auto_save_metadata(
                config.get("auto_save_directory")
            ),
        }
        if partial:
            result["failure"] = {
                "index": completed_count + 1,
                "summary": str(job_state.get("stage") or "后续成片未通过验收"),
            }
        return result
    return {
        "kind": "single",
        "download_url": f"/queue/download/{run_id}",
        "compliance_url": f"/queue/compliance/{run_id}",
        "name": output_path.name,
        "duration_seconds": job_state.get("output_duration_seconds"),
        "auto_save": pending_auto_save_metadata(
            config.get("auto_save_directory")
        ),
    }


def durable_queue_finish(store, run_id, status_name, stage, error="", result=None):
    finished = retry_queue_store_operation(
        lambda: store.finish(
            run_id,
            status_name,
            stage,
            error=error,
            result=result,
        ),
        run_id,
        "保存队列完成状态",
    )
    if finished is not None:
        if status_name == "succeeded":
            _ensure_delivery_task_lease_file(run_id)
        return finished
    current = retry_queue_store_operation(
        lambda: store.get(run_id),
        run_id,
        "核对队列完成状态",
    )
    if current and current.get("status") == status_name:
        if status_name == "succeeded":
            _ensure_delivery_task_lease_file(run_id)
        return current
    raise RuntimeError(
        f"队列任务无法从 {current.get('status') if current else 'missing'} "
        f"安全切换到 {status_name}"
    )


def cleanup_failed_queue_single(run_id):
    if not re.fullmatch(r"[0-9a-f]{32}", run_id or ""):
        return False
    root = QUEUE_OUTPUT_ROOT.resolve()
    task_dir = root / run_id
    if task_dir.is_symlink():
        return False
    resolved_dir = task_dir.resolve()
    if resolved_dir.parent != root or resolved_dir.name != run_id:
        return False
    removed = False
    for name in ("V17排队成片.mp4", "V17排队成片_合规报告.json"):
        path = resolved_dir / name
        if path.is_symlink():
            continue
        try:
            if path.is_file():
                path.unlink()
                removed = True
        except OSError:
            pass
    return removed


def _recover_queue_before_claiming(store):
    """Run startup recovery exactly once while every other worker waits.

    A second worker must never call ``recover_interrupted`` after the leader
    has begun claiming work: doing so would incorrectly mark the leader's live
    task as interrupted.  The condition also lets a waiter take over if the
    original leader exits unexpectedly before completing recovery.
    """
    global task_queue_recovered, task_queue_recovery_in_progress
    while True:
        with task_queue_recovery_condition:
            if task_queue_recovered:
                return True
            if task_queue_shutdown_event.is_set():
                return False
            if not task_queue_recovery_in_progress:
                task_queue_recovery_in_progress = True
                break
            task_queue_recovery_condition.wait(timeout=1.0)

    if not all(
        hasattr(store, method)
        for method in (
            "pending_auto_save_tasks",
            "recover_interrupted",
        )
    ):
        with task_queue_recovery_condition:
            task_queue_recovered = True
            task_queue_recovery_in_progress = False
            task_queue_recovery_condition.notify_all()
        return True
    try:
        while not task_queue_shutdown_event.is_set():
            settled = False
            try:
                auto_saves_settled = resume_pending_auto_saves(store)
                store.recover_interrupted()
                pending_auto_saves = bool(store.pending_auto_save_tasks())
                settled = bool(auto_saves_settled and not pending_auto_saves)
            except (OSError, sqlite3.Error):
                settled = False
            if settled:
                # Startup maintenance is idempotent.  External deliveries are
                # SHA-256 verified before duplicate internal outputs are released;
                # task assets remain until their three-hour terminal deadline.
                best_effort_release_saved_internal_outputs(
                    store,
                    **_current_cleanup_scope_kwargs(),
                )
                best_effort_reclaim_task_asset_sets(
                    store,
                    **_current_cleanup_scope_kwargs(),
                )
                best_effort_expire_task_outputs(
                    store,
                    max_deletions=8,
                )
                with task_queue_recovery_condition:
                    task_queue_recovered = True
                    task_queue_recovery_in_progress = False
                    task_queue_recovery_condition.notify_all()
                return True
            task_queue_wakeup.wait(timeout=5)
            task_queue_wakeup.clear()
        return False
    finally:
        with task_queue_recovery_condition:
            if not task_queue_recovered:
                task_queue_recovery_in_progress = False
            task_queue_recovery_condition.notify_all()


def _claim_next_queue_item(store):
    """Serialize claim against shutdown so no new task starts afterwards."""
    with task_queue_control_lock:
        if task_queue_shutdown_event.is_set():
            return None
        return store.claim_next()


def _tenant_waiting_head(store):
    """Return this tenant's oldest waiting identity without task payload data."""
    if not TENANT_BACKEND_MODE:
        return None
    return store.waiting_head_owned(
        TENANT_USER_ID,
        tenant_id=TENANT_ID,
    )


def _publish_current_global_fifo_head(store, head=None):
    """Synchronize one tenant-local queue head into the metadata-only broker."""
    if GLOBAL_FIFO_COORDINATOR is None:
        return head
    current = _tenant_waiting_head(store) if head is None else head
    if current is None:
        GLOBAL_FIFO_COORDINATOR.clear_head(
            TENANT_USER_ID,
            tenant_id=TENANT_ID,
        )
        return None
    GLOBAL_FIFO_COORDINATOR.publish_head(
        TENANT_USER_ID,
        TENANT_ID,
        current["task_id"],
        current["created_at"],
        local_sequence=current["sequence"],
        stable_key=current.get("fifo_stable_key"),
    )
    return current


def _claim_exact_tenant_queue_item(store, task_id):
    """Close shutdown races while claiming only the advertised tenant row."""
    with task_queue_control_lock:
        if task_queue_shutdown_event.is_set():
            return None
        return store.claim_waiting_exact_owned(
            TENANT_USER_ID,
            task_id,
            tenant_id=TENANT_ID,
        )


def _global_fifo_head_is_ours(head):
    return bool(
        isinstance(head, dict)
        and head.get("owner_user_id") == TENANT_USER_ID
        and head.get("tenant_id") == TENANT_ID
    )


def _run_persistent_task_queue_worker(worker_index=0):
    store = get_task_queue_store(create=True)
    if not _recover_queue_before_claiming(store):
        return
    next_idle_maintenance_monotonic = 0.0
    next_strict_preflight_monotonic = 0.0
    strict_preflight_failures = 0
    while not task_queue_shutdown_event.is_set():
        render_slot_lease = None
        fifo_head = None
        using_global_fifo = GLOBAL_FIFO_COORDINATOR is not None
        try:
            if using_global_fifo:
                fifo_head = _publish_current_global_fifo_head(store)
            elif GLOBAL_RENDER_SLOTS is not None:
                render_slot_lease = GLOBAL_RENDER_SLOTS.try_acquire(
                    TENANT_USER_ID or INSTANCE_ID
                )
        except (OSError, sqlite3.Error, RuntimeError, TypeError, ValueError):
            if render_slot_lease is not None:
                render_slot_lease.close()
                render_slot_lease = None
            task_queue_wakeup.wait(timeout=5.0)
            task_queue_wakeup.clear()
            continue
        if not using_global_fifo and GLOBAL_RENDER_SLOTS is not None:
            if render_slot_lease is None:
                task_queue_wakeup.wait(timeout=1.0)
                task_queue_wakeup.clear()
                continue
        # ERP authorization is intentionally not a render-admission gate.
        # When a tenant token expires, accepted usage events are persisted in
        # that tenant's outbox and delivered after the same owner scans again.
        # Until the claim/preflight phase completes, this loop still owns any
        # lease locally. Any unexpected BaseException must release it before
        # the worker exits; otherwise a render slot can remain unavailable for
        # the lifetime of this tenant backend.
        claim_phase_completed = False
        try:
            item = None
            has_waiting = fifo_head is not None
            if not using_global_fifo and STRICT_ERP_RELAY:
                # An empty local queue must never poll the remote readiness
                # endpoint.  A task arriving afterwards waits for the next loop.
                queue_snapshot = _public_queue_snapshot(
                    store,
                    history_limit=1,
                    waiting_limit=1,
                )
                has_waiting = int(queue_snapshot.get("waiting", 0) or 0) > 0
            elif not using_global_fifo:
                has_waiting = True

            if using_global_fifo and has_waiting:
                advertised = GLOBAL_FIFO_COORDINATOR.current_head()
                if (
                    not _global_fifo_head_is_ours(advertised)
                    or advertised.get("task_id") != fifo_head.get("task_id")
                ):
                    claim_phase_completed = True
                    task_queue_wakeup.wait(timeout=0.5)
                    task_queue_wakeup.clear()
                    continue

            if STRICT_ERP_RELAY and has_waiting:
                now_monotonic = time.monotonic()
                if now_monotonic < next_strict_preflight_monotonic:
                    if render_slot_lease is not None:
                        lease_to_close = render_slot_lease
                        render_slot_lease = None
                        lease_to_close.close()
                    task_queue_wakeup.wait(
                        timeout=min(
                            5.0,
                            max(
                                0.1,
                                next_strict_preflight_monotonic
                                - time.monotonic(),
                            ),
                        )
                    )
                    task_queue_wakeup.clear()
                    claim_phase_completed = True
                    continue
                readiness_error = strict_erp_readiness_error()
                if readiness_error:
                    strict_preflight_failures += 1
                    retry_delay = min(
                        60.0,
                        5.0 * (2 ** min(strict_preflight_failures - 1, 4)),
                    )
                    next_strict_preflight_monotonic = (
                        time.monotonic() + retry_delay
                    )
                    if render_slot_lease is not None:
                        lease_to_close = render_slot_lease
                        render_slot_lease = None
                        lease_to_close.close()
                    task_queue_wakeup.wait(timeout=min(5.0, retry_delay))
                    task_queue_wakeup.clear()
                    claim_phase_completed = True
                    continue
                strict_preflight_failures = 0
                next_strict_preflight_monotonic = 0.0
            elif STRICT_ERP_RELAY:
                strict_preflight_failures = 0
                next_strict_preflight_monotonic = 0.0

            if has_waiting:
                if using_global_fifo:
                    render_slot_lease, item = (
                        GLOBAL_FIFO_COORDINATOR.try_admit_and_claim(
                            TENANT_USER_ID,
                            TENANT_ID,
                            fifo_head["task_id"],
                            lambda task_id: _claim_exact_tenant_queue_item(
                                store, task_id
                            ),
                            next_head_callback=lambda: _tenant_waiting_head(store),
                            fairness_key=TENANT_USER_ID,
                        )
                    )
                else:
                    item = _claim_next_queue_item(store)
            claim_phase_completed = True
        except (OSError, sqlite3.Error, RuntimeError, TypeError, ValueError):
            if render_slot_lease is not None:
                lease_to_close = render_slot_lease
                render_slot_lease = None
                lease_to_close.close()
            task_queue_wakeup.wait(timeout=5)
            task_queue_wakeup.clear()
            continue
        finally:
            if not claim_phase_completed and render_slot_lease is not None:
                lease_to_close = render_slot_lease
                render_slot_lease = None
                lease_to_close.close()
        if task_queue_shutdown_event.is_set():
            # A claim that committed immediately before shutdown is left as a
            # durable interrupted row for cold-start recovery; never launch a
            # new renderer after shutdown admission has closed.
            if render_slot_lease is not None:
                lease_to_close = render_slot_lease
                render_slot_lease = None
                lease_to_close.close()
            break
        if item is None:
            if render_slot_lease is not None:
                lease_to_close = render_slot_lease
                render_slot_lease = None
                lease_to_close.close()
            if task_queue_shutdown_event.is_set():
                break
            now_monotonic = time.monotonic()
            if (
                worker_index == 0
                and now_monotonic >= next_idle_maintenance_monotonic
            ):
                best_effort_release_saved_internal_outputs(
                    store,
                    **_current_cleanup_scope_kwargs(),
                )
                best_effort_reclaim_task_asset_sets(
                    store,
                    **_current_cleanup_scope_kwargs(),
                )
                best_effort_expire_task_outputs(
                    store,
                    max_deletions=8,
                )
                cleanup_bundle_download_cache()
                next_idle_maintenance_monotonic = (
                    time.monotonic() + IDLE_MAINTENANCE_INTERVAL_SECONDS
                )
            idle_wait_timeout = 5.0
            if worker_index == 0:
                idle_wait_timeout = min(
                    5.0,
                    max(
                        0.1,
                        next_idle_maintenance_monotonic - time.monotonic(),
                    ),
                )
            task_queue_wakeup.wait(
                timeout=idle_wait_timeout
            )
            task_queue_wakeup.clear()
            continue

        run_id = item["task_id"]
        config = item.get("config")
        single_dir = QUEUE_OUTPUT_ROOT / run_id
        output_path = single_dir / "V17排队成片.mp4"
        compliance_path = single_dir / "V17排队成片_合规报告.json"
        try:
            if not isinstance(config, dict):
                raise RuntimeError("排队任务配置已损坏")
            if config.get("config_version") not in {1, 2}:
                raise RuntimeError("排队任务版本不兼容，请按原设置重新排队")
            material_base_dir = resolve_task_material_root(config, run_id)
            validate_queued_materials(
                config["selected_materials"], material_base_dir
            )
            config["timepin_zoom"] = normalize_timepin_zoom_settings(
                config.get("timepin_zoom")
            )
            config["corner_mask_reveal"] = normalize_corner_mask_reveal_settings(
                config.get("corner_mask_reveal")
            )
            config["subtitle_masks"] = normalize_subtitle_masks(
                config.get("subtitle_masks")
            )
            initialize_queue_run_state(
                run_id,
                config,
                output_path,
                compliance_path,
            )
            bind_task_run_state(run_id)
            store.update_stage(run_id, "正在制作")
            run_job(
                run_id,
                int(config["customer_id"]),
                str(config["customer_name"]),
                list(config["face_effects"]),
                dict(config["sticker_settings"]),
                bool(config["price_filter"]),
                float(config["target_duration"]),
                dict(config["timeline_budgets"]),
                int(config["fission_count"]),
                str(config["sync_mode"]),
                bool(config["full_spec_mode"]),
                {
                    pool: list(config["selected_materials"].get(pool, []))
                    for pool in POOLS
                },
                str(config["vision_provider"]),
                tuple(config["dedup_style_plan"]),
                str(config["dedup_style_source"]),
                clone_timepin_zoom_settings(config["timepin_zoom"]),
                clone_corner_mask_reveal_settings(config["corner_mask_reveal"]),
                single_output_path=output_path,
                single_compliance_path=compliance_path,
                stall_timeout_seconds=float(config["stall_timeout_seconds"]),
                auto_save_directory=str(
                    config.get("auto_save_directory") or ""
                ),
                material_base_dir=material_base_dir,
                slice_seconds=config.get(
                    "slice_seconds", hardcut_audio.DEFAULT_SLICE_SECONDS
                ),
                audio_dub_settings=config.get("audio_dub"),
                edition_mode=config.get("edition_mode", "original"),
                subtitle_masks=clone_subtitle_masks(config["subtitle_masks"]),
            )
            job_state = snapshot_state(run_id)
            queue_record = retry_queue_store_operation(
                lambda: store.get(run_id),
                run_id,
                "读取任务收尾状态",
            )
            was_skipped = queue_skip_requested(run_id) or (
                queue_record and queue_record.get("status") == "skip_requested"
            )
            if was_skipped:
                if (
                    int(config["fission_count"]) == 1
                    and (queue_record or {}).get("status") != "finalizing"
                ):
                    cleanup_failed_queue_single(run_id)
                durable_queue_finish(
                    store,
                    run_id,
                    "skipped",
                    "本条已跳过，队列继续运行",
                    result={},
                )
            elif job_state.get("status") in {"succeeded", "review_required"}:
                result = (
                    (queue_record or {}).get("result")
                    or queue_result_for_run(run_id, config, job_state, output_path)
                )
                result = dict(result)
                auto_save = result.get("auto_save")
                if (
                    str(config.get("auto_save_directory") or "").strip()
                    and (
                        not isinstance(auto_save, dict)
                        or auto_save.get("status") == "pending"
                    )
                ):
                    store.update_stage(run_id, "成片已生成，正在自动保存到所选文件夹")
                    result["auto_save"] = best_effort_auto_save_task(
                        run_id,
                        config,
                        result,
                    )
                    try:
                        retry_queue_store_operation(
                            lambda: store.update_preserved_result(run_id, result),
                            run_id,
                            "保存自动保存结果",
                        )
                    except Exception:
                        # The terminal transition below writes the same result
                        # again.  A metadata write failure never deletes or
                        # regenerates a valid output.
                        pass
                billing_state = (queue_record or {}).get("billing_state") or (
                    "uncertain" if CUSTOMER_BILLING_REQUIRED else "not_required"
                )
                erp_relay = (
                    result.get("erp_relay")
                    if isinstance(result.get("erp_relay"), dict)
                    else {}
                )
                erp_relay_confirmed = bool(
                    not STRICT_ERP_RELAY
                    or erp_relay.get("state")
                    in {
                        "confirmed",
                        "database_confirmed_direct_deferred",
                        "direct_deferred",
                        "direct_confirmed_backup_pending",
                        "direct_deferred_backup_pending",
                    }
                )
                if (
                    job_state.get("status") == "succeeded"
                    and billing_state in {"confirmed", "not_required"}
                    and erp_relay_confirmed
                ):
                    durable_queue_finish(
                        store,
                        run_id,
                        "succeeded",
                        "制作完成",
                        result=result,
                    )
                else:
                    durable_queue_finish(
                        store,
                        run_id,
                        "review_required",
                        "成品已保留，ERP 或收尾状态待核对",
                        error=(
                            "成品已经生成；严格传输或收尾确认不完整。"
                            "为避免重复制作或重复传输，本条不可自动重试。"
                        ),
                        result=result,
                    )
                try:
                    released_bytes = release_internal_delivery_copies(
                        {
                            "task_id": run_id,
                            "config": config,
                            "result": result,
                        }
                    )
                    if released_bytes > 0:
                        append_log(
                            "-> 外部保存文件已逐个校验，已释放应用内重复成片 "
                            f"{released_bytes / GIB_BYTES:.2f} GiB。",
                            run_id,
                        )
                except Exception as exc:
                    append_log(
                        "-> 外部成片已保存；应用内副本暂未清理，可稍后在存储管理中重试："
                        f"{redact_local_paths(exc)}",
                        run_id,
                    )
            else:
                failure_text = str(job_state.get("stage") or "制作失败")
                partial_result = None
                if (
                    int(config["fission_count"]) > 1
                    and job_state.get("fission_ready")
                    and job_state.get("fission_outputs")
                ):
                    candidate_result = queue_result_for_run(
                        run_id,
                        config,
                        job_state,
                        output_path,
                    )
                    if candidate_result.get("delivery_state") == "partial":
                        partial_result = candidate_result
                        if str(config.get("auto_save_directory") or "").strip():
                            store.update_stage(
                                run_id,
                                "部分成片已保留，正在自动保存到所选文件夹",
                            )
                            partial_result["auto_save"] = best_effort_auto_save_task(
                                run_id,
                                config,
                                partial_result,
                            )
                if (
                    int(config["fission_count"]) == 1
                    and (queue_record or {}).get("status") != "finalizing"
                ):
                    cleanup_failed_queue_single(run_id)
                timed_out = bool(
                    re.search(r"没有新的制作进展|渲染超过|超时", failure_text)
                )
                durable_queue_finish(
                    store,
                    run_id,
                    "timed_out" if timed_out else "failed",
                    (
                        f"部分完成：已保留 {partial_result['completed_count']}/"
                        f"{partial_result['requested_count']} 条，已自动继续下一条"
                        if partial_result
                        else (
                            "卡住超时，已自动继续下一条"
                            if timed_out
                            else "制作失败，已自动继续下一条"
                        )
                    ),
                    error=failure_text,
                    result=partial_result,
                )
                if partial_result:
                    try:
                        released_bytes = release_internal_delivery_copies(
                            {
                                "task_id": run_id,
                                "config": config,
                                "result": partial_result,
                            }
                        )
                        if released_bytes > 0:
                            append_log(
                                "-> 部分成片已校验保存，已释放应用内重复副本 "
                                f"{released_bytes / GIB_BYTES:.2f} GiB。",
                                run_id,
                            )
                    except Exception:
                        pass
        except Exception as exc:
            public_error = redact_local_paths(exc)
            try:
                current_record = retry_queue_store_operation(
                    lambda: store.get(run_id),
                    run_id,
                    "核对异常任务状态",
                )
            except Exception:
                current_record = None
            preserve_output = bool(
                current_record
                and (
                    current_record.get("status")
                    in {"finalizing", "succeeded", "review_required"}
                    or current_record.get("result")
                )
            )
            if preserve_output:
                preserved_result = dict(current_record.get("result") or {})
                auto_save = preserved_result.get("auto_save")
                if (
                    isinstance(config, dict)
                    and str(config.get("auto_save_directory") or "").strip()
                    and isinstance(auto_save, dict)
                    and auto_save.get("status") == "pending"
                ):
                    preserved_result["auto_save"] = best_effort_auto_save_task(
                        run_id,
                        config,
                        preserved_result,
                    )
                    try:
                        retry_queue_store_operation(
                            lambda: store.update_preserved_result(
                                run_id,
                                preserved_result,
                            ),
                            run_id,
                            "保存异常任务的自动保存结果",
                        )
                    except Exception:
                        pass
                if current_record.get("status") == "finalizing":
                    try:
                        durable_queue_finish(
                            store,
                            run_id,
                            "review_required",
                            "成品已保留，收尾状态待核对",
                            error=(
                                "成品生成后的收尾发生异常；为避免重复制作或重复传输，"
                                "本条不可自动重试。"
                            ),
                            result=preserved_result,
                        )
                    except Exception:
                        pass
                with state_lock:
                    run_state = _task_state_for_run_locked(
                        run_id, fallback_to_base=False
                    )
                    if run_state is not None:
                        run_state.update(
                            {
                                "running": False,
                                "status": "review_required",
                                "stage": "成品已保留，收尾状态待核对",
                                "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                                "returncode": 0,
                            }
                        )
                continue
            if isinstance(config, dict) and config.get("fission_count", 1) in {1, "1"}:
                cleanup_failed_queue_single(run_id)
            try:
                durable_queue_finish(
                    store,
                    run_id,
                    "failed",
                    "任务准备失败，已自动继续下一条",
                    error=public_error,
                )
            except Exception:
                pass
            with state_lock:
                run_state = _task_state_for_run_locked(
                    run_id, fallback_to_base=False
                )
                if run_state is not None:
                    run_state.update(
                        {
                            "running": False,
                            "status": "failed",
                            "stage": f"制作失败：{public_error}",
                            "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                            "returncode": -2,
                        }
                    )
        finally:
            try:
                clear_queue_skip(run_id)
                # Every terminal path retries duplicate-output release.  The
                # existing manifest/SHA-256 verification is the deletion gate.
                best_effort_release_saved_internal_outputs(
                    store,
                    task_id=run_id,
                    run_id=run_id,
                    **_current_cleanup_scope_kwargs(),
                )
                if isinstance(config, dict) and config.get("asset_set_id"):
                    # Safe terminal sets remain for three hours; failed-only
                    # sets remain retryable.
                    best_effort_reclaim_task_asset_sets(
                        store,
                        config.get("asset_set_id"),
                        run_id=run_id,
                        **_current_cleanup_scope_kwargs(),
                    )
            finally:
                unbind_task_run_state(run_id)
                if render_slot_lease is not None:
                    lease_to_close = render_slot_lease
                    render_slot_lease = None
                    lease_to_close.close()
                schedule_bounded_retention_maintenance(store)


def run_persistent_task_queue(worker_index=0):
    """Keep one production lane alive until this backend is intentionally stopped.

    Normal task failures are settled inside the worker loop.  This outer guard
    is the final production-continuity boundary for unexpected ``BaseException``
    failures: release/cleanup ``finally`` blocks have already run, so the lane
    can continue with the next durable FIFO item without taking the other lanes
    down.  A real service shutdown still exits immediately.
    """

    while not task_queue_shutdown_event.is_set():
        try:
            _run_persistent_task_queue_worker(worker_index)
        except BaseException as exc:
            if task_queue_shutdown_event.is_set():
                return
            try:
                append_log(
                    "-> 制作通道发生未预期异常，已隔离本条并自动恢复后续排队："
                    f"{redact_local_paths(exc)}"
                )
            except BaseException:
                pass
            # Bound restart churn while remaining responsive to shutdown.
            if task_queue_shutdown_event.wait(timeout=1.0):
                return
            task_queue_wakeup.clear()
        else:
            # The inner worker returns only for shutdown.  Keep this defensive
            # branch fail-open in case a future change introduces an early
            # return without closing production admission.
            if task_queue_shutdown_event.is_set():
                return
            if task_queue_shutdown_event.wait(timeout=0.25):
                return


def _daily_completed_output_cleanup_loop(store):
    """Poll the durable daily deadline independently of render throughput."""
    while not task_queue_shutdown_event.is_set():
        try:
            client_save_sessions.expire()
            run_daily_completed_output_cleanup_if_due(store)
        except BaseException:
            # Destructive maintenance is fail-closed and must never terminate
            # queue production.  The unchanged durable deadline causes retry.
            pass
        if task_queue_shutdown_event.wait(
            timeout=DAILY_COMPLETED_OUTPUT_CLEANUP_POLL_SECONDS
        ):
            return


def ensure_daily_completed_output_cleanup_worker(store):
    global daily_completed_output_cleanup_thread
    current = daily_completed_output_cleanup_thread
    if current is not None and current.is_alive():
        return True
    worker = threading.Thread(
        target=_daily_completed_output_cleanup_loop,
        args=(store,),
        name="v17-daily-succeeded-output-cleanup",
        daemon=True,
    )
    daily_completed_output_cleanup_thread = worker
    try:
        worker.start()
    except RuntimeError:
        daily_completed_output_cleanup_thread = None
        return False
    return True


def ensure_task_queue_worker(create=False):
    global task_queue_worker_threads
    if task_queue_shutdown_event.is_set():
        return False
    store = get_task_queue_store(create=create)
    if store is None:
        return False
    with task_queue_worker_lock:
        while len(task_queue_worker_threads) < TASK_QUEUE_WORKER_COUNT:
            task_queue_worker_threads.append(None)
        for worker_index in range(TASK_QUEUE_WORKER_COUNT):
            current = task_queue_worker_threads[worker_index]
            if current is not None and current.is_alive():
                continue
            worker = threading.Thread(
                target=run_persistent_task_queue,
                args=(worker_index,),
                name=f"v17-persistent-task-queue-{worker_index + 1}",
                daemon=True,
            )
            task_queue_worker_threads[worker_index] = worker
            try:
                worker.start()
            except RuntimeError:
                task_queue_worker_threads[worker_index] = None
        ensure_daily_completed_output_cleanup_worker(store)
        task_queue_wakeup.set()
        return any(
            worker is not None and worker.is_alive()
            for worker in task_queue_worker_threads[:TASK_QUEUE_WORKER_COUNT]
        )


