def _is_valid_local_csrf(submitted_token: str) -> bool:
    token_str = str(submitted_token or "")
    if hmac.compare_digest(token_str, CSRF_TOKEN):
        return True
    if TENANT_BACKEND_MODE or request.remote_addr not in {"127.0.0.1", "::1"}:
        return False
    host = (request.headers.get("Host") or "").strip()
    origin = (request.headers.get("Origin") or "").strip()
    allowed_origins = {f"http://{host}", "http://127.0.0.1:8038", "http://localhost:8038"}
    if not origin or origin not in allowed_origins:
        return False
    if (
        request.headers.get("X-Requested-With") == "fetch"
        or request.headers.get("Sec-Fetch-Site") == "same-origin"
    ):
        return bool(re.fullmatch(r"[A-Za-z0-9_-]{32,64}", token_str))
    return False


@app.post("/save-location/choose")
def choose_save_location():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="save-location",
            state=snapshot_state(),
        )
    if TENANT_BACKEND_MODE:
        return action_response(
            "多用户网页会把成片下载到访问者自己的电脑；"
            "服务器只使用当前账号隔离的临时交付缓存，不能从网页选择客户盘符。",
            ok=True,
            status_code=200,
            anchor="save-location",
            state=snapshot_state(),
        )
    try:
        selected = choose_auto_save_directory()
    except (OSError, RuntimeError, subprocess.TimeoutExpired) as exc:
        return action_response(
            f"无法打开文件夹选择窗口：{redact_local_paths(exc)}",
            ok=False,
            status_code=500,
            level="error",
            anchor="save-location",
            state=snapshot_state(),
        )
    if selected is None:
        return action_response(
            "已取消选择，原来的保存位置没有改变。",
            ok=True,
            status_code=200,
            anchor="save-location",
            state=snapshot_state(),
        )
    try:
        normalized = save_auto_save_directory(selected)
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="save-location",
            state=snapshot_state(),
        )
    except OSError as exc:
        return action_response(
            f"保存位置记录失败：{redact_local_paths(exc)}",
            ok=False,
            status_code=500,
            level="error",
            anchor="save-location",
            state=snapshot_state(),
        )
    return action_response(
        f"已选择自动保存位置：{Path(normalized).name or normalized}",
        ok=True,
        status_code=200,
        anchor="save-location",
        state=snapshot_state(),
    )


