@app.post("/queue/submission-status")
def queue_submission_status_route():
    """Confirm a committed submission without enqueueing, probing media or recovery.

    A missing row is only a point-in-time observation: an earlier /run request
    may still be processing. The browser must retain the same submission key.
    Use a genuinely read-only connection: even a cold tenant must not migrate
    a database or launch a worker just to answer this small recovery probe.
    """
    csrf_error = _task_draft_csrf_error()
    if csrf_error is not None:
        return csrf_error
    try:
        submission_key = parse_queue_request_token("submission_key")
    except ValueError as exc:
        return action_response(str(exc), ok=False, status_code=422, level="error")
    if TENANT_BACKEND_MODE and (not TENANT_USER_ID or not TENANT_ID):
        abort(403)
    row = None
    try:
        database = _task_queue_database_path()
        if database.is_file():
            connection = sqlite3.connect(
                database.as_uri() + "?mode=ro", uri=True, timeout=0.75,
            )
            try:
                if TENANT_BACKEND_MODE:
                    row = connection.execute(
                        "SELECT task_id,status FROM task_queue "
                        "WHERE submission_key=? AND owner_user_id=? AND tenant_id=? LIMIT 1",
                        (submission_key, TENANT_USER_ID, TENANT_ID),
                    ).fetchone()
                else:
                    row = connection.execute(
                        "SELECT task_id,status FROM task_queue WHERE submission_key=? LIMIT 1",
                        (submission_key,),
                    ).fetchone()
            finally:
                connection.close()
    except (OSError, sqlite3.Error):
        response = jsonify(ok=False, message="暂时无法读取队列，请稍后核对同一次提交；不要重复新建任务。")
        response.status_code = 503
    else:
        payload = {"ok": True, "found": row is not None}
        if row is not None:
            payload.update(
                task_id=str(row[0]), task_status=str(row[1]),
                message="已确认这次提交已加入队列，没有重复创建任务。",
            )
        response = jsonify(payload)
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


