@app.get("/task-drafts/<draft_id>/corner-preview/<path:name>")
def corner_sticker_preview_route(draft_id, name):
    """Serve only a PNG that belongs to this still-mutable task draft."""
    try:
        draft_id = _valid_task_asset_id(draft_id)
        name = str(name or "")
        if Path(name).name != name or Path(name).suffix.lower() != CORNER_STICKER_SUFFIX:
            raise ValueError("四角贴纸预览文件无效。")
        with task_asset_lock:
            directory, manifest = _read_task_asset_manifest("draft", draft_id)
            if name not in manifest["pools"].get("贴纸素材池", []):
                raise FileNotFoundError("这个四角贴纸已经不在当前任务中。")
            preview_path = _task_asset_file_path(directory, "贴纸素材池", name)
            if not preview_path.is_file():
                raise FileNotFoundError("这个四角贴纸已经不存在。")
    except (FileNotFoundError, ValueError):
        abort(404)
    response = send_file(
        preview_path,
        mimetype="image/png",
        conditional=True,
        max_age=0,
    )
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


@app.get("/pool-media/<pool>/<path:name>")
def pool_media_preview_route(pool, name):
    """Serve a video from a main material pool with HTTP Range scrubbing support."""
    try:
        pool = str(pool or "")
        name = str(name or "")
        if pool not in {"打乱素材池", "核心素材", "开头视频"}:
            raise ValueError("不支持预览该素材池。")
        if Path(name).name != name or Path(name).suffix.lower() not in {".mp4", ".mov"}:
            raise ValueError("视频预览文件名无效。")
        pool_dir = (BASE_DIR / pool).resolve(strict=True)
        candidate = BASE_DIR / pool / name
        if candidate.is_symlink() or not candidate.is_file():
            raise FileNotFoundError("视频文件不存在。")
        resolved = candidate.resolve(strict=True)
        if resolved.parent != pool_dir:
            raise ValueError("视频预览路径越界。")
    except (FileNotFoundError, OSError, ValueError):
        abort(404)
    mime = "video/quicktime" if resolved.suffix.lower() == ".mov" else "video/mp4"
    response = send_file(
        resolved,
        mimetype=mime,
        conditional=True,
        max_age=0,
    )
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


