@app.post("/upload")
def upload():
    upload_reservation = begin_renderer_sensitive_upload(request.content_length)
    if not upload_reservation:
        return action_response(
            "素材上传最多同时进行 2 个；请求必须提供可核对的 Content-Length，"
            "并为全部在途上传预留足够磁盘空间。请稍后或清理磁盘后重试。",
            ok=False,
            status_code=409,
            level="warn",
        )
    try:
        return _upload_shared_pool_route_impl()
    finally:
        finish_renderer_sensitive_upload(upload_reservation)


def _upload_shared_pool_route_impl():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response("页面校验已失效，请刷新后重试。", ok=False, status_code=403, level="error")

    pool = request.form.get("pool", "")
    if pool not in POOLS:
        return action_response("素材池无效，未上传文件。", ok=False, status_code=400, level="error")

    with operation_lock:
        if task_queue_has_unfinished():
            return action_response(
                "制作队列还没有清空。为保证已经排队的素材不变，请等队列完成后再上传。",
                ok=False,
                status_code=409,
                level="warn",
            )

        target = BASE_DIR / pool
        target.mkdir(exist_ok=True)
        temp_dir = BASE_DIR / ".upload_tmp"
        temp_dir.mkdir(exist_ok=True)
        allowed = {f".{ext.lower()}" for ext in POOLS[pool]}
        uploaded = []
        rejected = []
        renamed = []

        for storage in request.files.getlist("files"):
            raw_name = (storage.filename or "").strip()
            if (
                not raw_name
                or raw_name in {".", ".."}
                or "/" in raw_name
                or "\\" in raw_name
                or "\x00" in raw_name
                or Path(raw_name).name != raw_name
            ):
                rejected.append({"name": raw_name or "未命名文件", "reason": "文件名无效"})
                continue
            suffix = Path(raw_name).suffix.lower()
            if suffix not in allowed:
                rejected.append({"name": raw_name, "reason": f"此素材池不支持 {suffix or '无扩展名'} 格式"})
                continue

            destination = unique_upload_path(target, raw_name)
            temp_path = temp_dir / f"{uuid.uuid4().hex}{suffix}.part"
            try:
                storage.save(temp_path)
                temp_path.replace(destination)
                uploaded.append(destination.name)
                if destination.name != raw_name:
                    renamed.append({"from": raw_name, "to": destination.name})
            except OSError as exc:
                rejected.append({"name": raw_name, "reason": f"保存失败：{exc}"})
                try:
                    temp_path.unlink(missing_ok=True)
                except OSError:
                    pass

        pool_count = len(
            [path for path in target.iterdir() if path.is_file() and path.suffix.lower() in allowed]
        )
        append_uploaded_files(pool, uploaded)

    if uploaded:
        message = f"已上传 {len(uploaded)} 个素材到“{pool}”"
        if renamed:
            message += f"，其中 {len(renamed)} 个同名文件已自动改名"
        if rejected:
            message += f"；另有 {len(rejected)} 个文件未上传"
        return action_response(
            message,
            ok=True,
            status_code=207 if rejected else 201,
            level="warn" if rejected else "ok",
            uploaded=uploaded,
            rejected=rejected,
            renamed=renamed,
            pool_count=pool_count,
        )

    message = "没有可上传的文件。请确认已选择文件，并且格式适合当前素材池。"
    if rejected:
        message = "；".join(f"{item['name']}：{item['reason']}" for item in rejected[:3])
    return action_response(
        message,
        ok=False,
        status_code=422,
        level="error",
        uploaded=[],
        rejected=rejected,
        renamed=[],
        pool_count=pool_count,
    )


@app.post("/cleanup")
def cleanup():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return notice_redirect("页面校验已失效，请刷新页面后重试。", "error")

    pool = request.form.get("pool", "")
    action = request.form.get("action", "")
    with operation_lock:
        if task_queue_has_unfinished():
            return notice_redirect(
                "制作队列还没有清空。为保证排队任务能找到原素材，暂时不能删除素材。",
                "error",
            )
        try:
            targets = cleanup_targets(pool, action, request.form.getlist("files"))
        except ValueError as exc:
            return notice_redirect(str(exc), "error")

        if not targets:
            return notice_redirect(f"“{pool}”中没有可清理的素材。", "warn")

        try:
            batch_dir, moved, failures = move_to_trash(pool, targets)
        except OSError as exc:
            return notice_redirect(f"无法创建素材回收目录，未执行清理：{exc}", "error")
        order_sync_error = None
        try:
            sync_upload_order_after_cleanup()
        except OSError as exc:
            order_sync_error = exc

    if failures or order_sync_error:
        message = f"已将 {len(moved)} 个素材移到 {batch_dir.relative_to(BASE_DIR)}"
        if failures:
            message += f"；另有 {len(failures)} 个移动失败"
        if order_sync_error:
            message += "；顺序清单暂未写入，刷新页面时会自动重试"
        message += "。"
        return notice_redirect(message, "warn")
    return notice_redirect(f"已将 {len(moved)} 个素材移到 {batch_dir.relative_to(BASE_DIR)}，需要时可恢复。")


