@app.post("/run")
def run():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )

    try:
        submission_key = parse_queue_request_token("submission_key")
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )

    # A browser may retry after the first response was lost.  Resolve that
    # exact click before any slow validation, model selection, or balance check.
    try:
        early_store = get_task_queue_store(create=True)
        existing_submission = _public_submission_get(
            early_store,
            submission_key,
        )
    except (OSError, sqlite3.Error) as exc:
        return action_response(
            f"暂时无法读取制作队列：{redact_local_paths(exc)}",
            ok=False,
            status_code=500,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if existing_submission is not None:
        ensure_task_queue_worker(create=True)
        return action_response(
            "这次操作已经加入过队列，没有重复创建任务。",
            ok=True,
            status_code=200,
            level="ok",
            anchor="queue-panel",
            task_id=existing_submission["task_id"],
            state=snapshot_state(),
        )

    strict_readiness_error = strict_erp_readiness_error()
    if strict_readiness_error:
        return action_response(
            strict_readiness_error,
            ok=False,
            status_code=503,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )

    task_draft_id = str(request.form.get("task_draft_id", "") or "").strip()
    task_owned_materials = bool(task_draft_id)
    run_id = (
        uuid.uuid5(uuid.NAMESPACE_URL, f"v17-8038-task:{submission_key}").hex
        if task_owned_materials
        else uuid.uuid4().hex
    )
    try:
        task_name = parse_task_name()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )

    if (
        ERP_DIRECT_ENABLED
        and not LOCAL_NO_VALIDATION
        and not _read_erp_bearer_token()
    ):
        return action_response(
            "请先完成启动时的 ERP 钉钉扫码登录。",
            ok=False,
            status_code=401,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )

    try:
        edition_mode = parse_edition_mode_form()
        slice_seconds = parse_slice_seconds_form()
        audio_dub = parse_audio_dub_form()
        subtitle_masks = parse_subtitle_masks_form()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="task-modal" if task_owned_materials else "launch",
            state=snapshot_state(),
        )

    _raw_submitted_vkey = (request.form.get("vision_api_key", "") or "").strip()
    if not _raw_submitted_vkey:
        vision_provider, vision_api_key = "qwen", ""
    else:
        try:
            vision_provider, vision_api_key = parse_external_api_keys()
        except ValueError as exc:
            return action_response(
                str(exc),
                ok=False,
                status_code=422,
                level="error",
                anchor="launch",
                state=snapshot_state(),
            )

        try:
            validate_external_api_keys(vision_provider, vision_api_key)
        except ValueError as exc:
            return action_response(
                str(exc),
                ok=False,
                status_code=422,
                level="error",
                anchor="launch",
                state=snapshot_state(),
            )

    try:
        face_effects = parse_face_effects()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    sticker_settings = None
    if not task_owned_materials:
        try:
            sticker_settings = parse_sticker_settings()
        except ValueError as exc:
            return action_response(
                str(exc),
                ok=False,
                status_code=422,
                level="error",
                anchor="launch",
                state=snapshot_state(),
            )
    try:
        timepin_zoom = parse_timepin_zoom_settings()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    try:
        corner_mask_reveal = parse_corner_mask_reveal_settings()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    full_spec_mode = False
    try:
        duration_multiplier = parse_duration_multiplier()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    try:
        fission_count = parse_fission_count()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    try:
        queue_stall_minutes = parse_queue_stall_minutes()
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    is_v2_edition = edition_mode == "v2"
    use_hardcut_budget = bool(is_v2_edition)
    sync_mode = "video_to_script"

    def _dubbing_material_error(materials):
        if not is_v2_edition:
            return ""
        mode = audio_dub.get("voice_mode", "none")
        if mode == "upload" and not materials.get("配音音频"):
            return "你选择了“使用已上传配音音频”，请先上传 1 条配音音频文件（或切换为“不加配音”）。"
        if mode == "tts":
            if not str(audio_dub.get("voice_text") or "").strip():
                return "你选择了“文案合成配音 / 克隆音色”，请先输入配音台词（或切换为“不加配音”）。"
            if audio_dub.get("voice_preset") == "custom_clone" and not materials.get("参考音色"):
                return "你选择了“导入参考音色克隆”，请先上传 1 条 3–10 秒参考音色音频。"
        return ""

    material_root = BASE_DIR
    asset_snapshot = None
    asset_set_ready = False
    material_anchor = "task-modal" if task_owned_materials else "pools"
    try:
        if task_owned_materials:
            asset_set_path = _task_asset_directory("set", run_id)
            if asset_set_path.is_dir():
                _directory, asset_manifest = _read_task_asset_manifest(
                    "set", run_id
                )
                if asset_manifest.get("submission_key") != submission_key:
                    raise ValueError("任务素材编号发生冲突，请重新新建任务。")
                asset_snapshot = task_asset_snapshot("set", run_id)
                material_root = asset_set_path
                asset_set_ready = True
            else:
                asset_snapshot = task_asset_snapshot("draft", task_draft_id)
                material_root = _task_asset_directory("draft", task_draft_id)
            selected_materials = task_asset_selected_materials(asset_snapshot)
            if not is_v2_edition:
                for audio_pool_name in AUDIO_POOLS:
                    selected_materials[audio_pool_name] = []
            sticker_settings = parse_task_sticker_settings(selected_materials)
        else:
            selected_materials = parse_selected_materials(
                ignore_pools=AUDIO_POOLS if not is_v2_edition else None
            )
            if not is_v2_edition:
                for audio_pool_name in AUDIO_POOLS:
                    selected_materials[audio_pool_name] = []
    except (FileNotFoundError, OSError, RuntimeError, ValueError) as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor=material_anchor,
            state=snapshot_state(),
        )
    if not selected_materials.get("核心素材"):
        return action_response(
            "请给这个任务添加至少 1 个核心视频。"
            if task_owned_materials
            else "请先勾选至少 1 条核心素材。",
            ok=False,
            status_code=422,
            level="error",
            anchor=material_anchor,
            state=snapshot_state(),
        )
    dub_error = _dubbing_material_error(selected_materials)
    if dub_error:
        return action_response(
            dub_error,
            ok=False,
            status_code=422,
            level="error",
            anchor=material_anchor,
            state=snapshot_state(),
        )
    try:
        if task_owned_materials:
            timeline_budgets = selected_timeline_budgets(
                selected_materials,
                duration_multiplier,
                material_root=material_root,
                slice_seconds=slice_seconds,
                use_hardcut=use_hardcut_budget,
            )
        else:
            timeline_budgets = selected_timeline_budgets(
                selected_materials,
                duration_multiplier,
                slice_seconds=slice_seconds,
                use_hardcut=use_hardcut_budget,
            )
    except (OSError, RuntimeError, ValueError) as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor=material_anchor,
            state=snapshot_state(),
        )
    target_duration = timeline_budgets["target"]
    material_error = fission_material_error(selected_materials, fission_count)
    if material_error:
        return action_response(
            material_error,
            ok=False,
            status_code=422,
            level="error",
            anchor=material_anchor,
            state=snapshot_state(),
        )

    price_filter = request.form.get("price_filter") == "on"
    dependency_error = runtime_dependency_error(price_filter=price_filter)
    if dependency_error:
        return action_response(
            dependency_error,
            ok=False,
            status_code=422,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    try:
        customer = resolve_run_customer()
    except BillingError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=402,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )

    # A new-style queue task owns an immutable material set.  Freeze only
    # after the inexpensive request checks have passed, then recompute every
    # duration from the frozen files so a simultaneous upload can never change
    # what the queued task will render.
    if task_owned_materials:
        try:
            if not asset_set_ready:
                freeze_task_asset_draft(
                    task_draft_id,
                    run_id,
                    submission_key,
                )
            material_root = resolve_task_material_root(
                {
                    "config_version": 2,
                    "asset_set_id": run_id,
                    "submission_key": submission_key,
                },
                run_id,
            )
            asset_snapshot = task_asset_snapshot("set", run_id)
            selected_materials = task_asset_selected_materials(asset_snapshot)
            if not is_v2_edition:
                for audio_pool_name in AUDIO_POOLS:
                    selected_materials[audio_pool_name] = []
            sticker_settings = parse_task_sticker_settings(selected_materials)
            frozen_dub_error = _dubbing_material_error(selected_materials)
            if frozen_dub_error:
                raise ValueError(frozen_dub_error)
            timeline_budgets = selected_timeline_budgets(
                selected_materials,
                duration_multiplier,
                material_root=material_root,
                slice_seconds=slice_seconds,
                use_hardcut=use_hardcut_budget,
            )
            target_duration = timeline_budgets["target"]
            material_error = fission_material_error(
                selected_materials,
                fission_count,
            )
            if material_error:
                raise ValueError(material_error)
        except (FileNotFoundError, OSError, RuntimeError, ValueError) as exc:
            return action_response(
                str(exc),
                ok=False,
                status_code=422,
                level="error",
                anchor="task-modal",
                state=snapshot_state(),
            )

    # Visible retry styles are retired. The model/provider remains available to
    # the rest of the workflow, but it is never asked to choose destructive
    # silhouette/ink/comic filters for production candidates.
    dedup_style_plan = ("clean", "clean", "clean")
    dedup_style_source = VISUAL_QUALITY_POLICY
    # Department credentials are intentionally never retained by the worker.
    vision_api_key = ""

    task_config = {
        "config_version": 2 if task_owned_materials else 1,
        "task_name": task_name,
        "edition_mode": edition_mode,
        "auto_save_folder_scheme": 3,
        "delivery_policy": DELIVERY_POLICY_DIRECT_FILES_V3,
        "submission_key": submission_key,
        "customer_id": int(customer["id"]),
        "customer_name": str(customer["name"]),
        "face_effects": list(face_effects),
        "sticker_settings": {
            "size_percent": int(sticker_settings.get("size_percent", 100)),
            "corners": dict(sticker_settings.get("corners", {})),
            "fullscreen": dict(sticker_settings.get("fullscreen", {})),
        },
        "price_filter": bool(price_filter),
        "target_duration": float(target_duration),
        "duration_multiplier": float(duration_multiplier),
        "slice_seconds": float(slice_seconds),
        "audio_dub": dict(audio_dub),
        "subtitle_masks": clone_subtitle_masks(subtitle_masks),
        "timeline_budgets": {
            key: float(value) for key, value in timeline_budgets.items()
        },
        "fission_count": int(fission_count),
        "sync_mode": sync_mode,
        "full_spec_mode": bool(full_spec_mode),
        "selected_materials": {
            pool: list(selected_materials.get(pool, [])) for pool in POOLS
        },
        "vision_provider": vision_provider,
        "dedup_style_plan": list(dedup_style_plan),
        "dedup_style_source": dedup_style_source,
        "visual_quality_policy": VISUAL_QUALITY_POLICY,
        "core_window_policy": CORE_WINDOW_POLICY,
        "shuffle_window_policy": SHUFFLE_WINDOW_POLICY,
        "timepin_zoom": clone_timepin_zoom_settings(timepin_zoom),
        "corner_mask_reveal": clone_corner_mask_reveal_settings(
            corner_mask_reveal
        ),
        "stall_timeout_seconds": int(queue_stall_minutes * 60),
        # Read only the server-side preference.  The browser never submits an
        # arbitrary filesystem path, and each queued task keeps this snapshot.
        "auto_save_directory": load_auto_save_directory(),
    }
    if task_owned_materials:
        task_config["asset_set_id"] = run_id
        task_config["material_summary"] = task_asset_material_summary(
            asset_snapshot
        )
    was_duplicate = False
    try:
        with operation_lock:
            store = get_task_queue_store(create=True)
            enqueued = _public_submission_get(store, submission_key)
            if enqueued is not None:
                was_duplicate = True
            else:
                if CUSTOMER_BILLING_REQUIRED:
                    fresh_customer = resolve_run_customer()
                    if int(fresh_customer["id"]) != int(customer["id"]):
                        raise BillingError(
                            "客户身份在提交期间发生变化，请重新确认后再试。"
                        )
                    customer = fresh_customer
                    task_config["customer_id"] = int(customer["id"])
                    task_config["customer_name"] = str(customer["name"])
                    reserved_units = store.reserved_units_for_customer(
                        customer["id"]
                    )
                    available_units = int(customer.get("balance", 0))
                    required_units = reserved_units + int(fission_count)
                    if available_units < required_units:
                        raise BillingError(
                            f"余额不足：当前剩余 {available_units} 次，"
                            f"队列已预留 {reserved_units} 次，本条还需要 {fission_count} 次。"
                        )
                try:
                    if TENANT_BACKEND_MODE:
                        enqueued = store.enqueue(
                            queue_task_title(task_config),
                            task_config,
                            task_id=run_id,
                            submission_key=submission_key,
                            owner_user_id=TENANT_USER_ID,
                            tenant_id=TENANT_ID,
                        )
                    else:
                        enqueued = store.enqueue_legacy_internal(
                            queue_task_title(task_config),
                            task_config,
                            task_id=run_id,
                            submission_key=submission_key,
                        )
                except (OSError, sqlite3.Error):
                    # If SQLite committed but the response path failed, the
                    # submission key recovers the original row safely.
                    enqueued = _public_submission_get(store, submission_key)
                    if enqueued is None:
                        raise
            run_id = str(enqueued["task_id"])
            if GLOBAL_FIFO_COORDINATOR is not None:
                try:
                    _publish_current_global_fifo_head(store)
                except (OSError, sqlite3.Error, RuntimeError, TypeError, ValueError):
                    # The durable tenant row already committed.  Workers retry
                    # this metadata-only publication fail-closed; never create
                    # a duplicate submission merely because the broker is busy.
                    pass
            ensure_task_queue_worker(create=True)
    except BillingError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=402,
            level="error",
            anchor="launch",
            state=snapshot_state(),
        )
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        return action_response(
            f"无法加入制作队列：{redact_local_paths(exc)}",
            ok=False,
            status_code=500,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )

    message = (
        "这次操作已经加入过队列，没有重复创建任务。"
        if was_duplicate
        else "已加入制作队列；" + QUEUE_POLICY_TEXT
    )
    return action_response(
        message,
        ok=True,
        status_code=202,
        level="ok",
        anchor="queue-panel",
        task_id=run_id,
        state=snapshot_state(),
    )


@app.get("/status")
def status():
    ensure_task_queue_worker(create=False)
    payload = snapshot_state()
    if TENANT_BACKEND_MODE:
        payload["tenant_backend"] = True
        payload["tenant_user_id"] = TENANT_USER_ID
        payload["tenant_id"] = TENANT_ID
    response = jsonify(payload)
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


@app.get("/download")
def download():
    with state_lock:
        selected_state = _representative_task_state_locked()
        output_path = Path(selected_state.get("output_path") or OUT_FILE)
        output_ready = bool(selected_state.get("output_ready"))
        run_id = str(selected_state.get("run_id") or "")
    if not output_ready and not re.fullmatch(r"[0-9a-f]{32}", run_id):
        return redirect(url_for("index"))
    task_name = "快手成片"
    store = get_task_queue_store(create=False)
    try:
        item = (
            _public_queue_get(store, run_id, include_config=True)
            if store is not None
            else None
        )
        if isinstance(item, dict) and isinstance(item.get("config"), dict):
            task_name = item["config"].get("task_name") or task_name
    except (OSError, sqlite3.Error):
        pass
    download_name = (
        delivery_video_name(task_name, run_id)
        if re.fullmatch(r"[0-9a-f]{32}", run_id)
        else "快手成片.mp4"
    )
    if re.fullmatch(r"[0-9a-f]{32}", run_id):
        try:
            return _guard_output_download_response(
                (run_id,),
                lambda: _send_tracked_artifact(
                    queue_delivery_artifact(
                        _queue_record_for_delivery(run_id),
                        "video",
                    ),
                    run_id,
                ),
            )
        except (NotFound, OSError, ValueError, FileNotFoundError, StopIteration):
            return redirect(url_for("index"))
    if output_ready and output_path.is_file():
        return send_file(
            output_path,
            as_attachment=True,
            download_name=download_name,
            mimetype="video/mp4",
        )
    return redirect(url_for("index"))


def queue_record_or_404(task_id, include_config=False):
    if not re.fullmatch(r"[0-9a-f]{32}", task_id or ""):
        abort(404)
    store = get_task_queue_store(create=False)
    if store is None:
        abort(404)
    try:
        item = _public_queue_get(
            store,
            task_id,
            include_config=include_config,
        )
    except (OSError, sqlite3.Error):
        abort(404)
    if not item:
        abort(404)
    return store, item


@app.get("/client-save-browser.js")
def client_save_browser_script():
    return send_file(CODE_DIR / "client_save_browser.js", mimetype="application/javascript", max_age=0)


def _client_save_record(task_id, session_id):
    queue_record_or_404(task_id)
    try:
        return client_save_sessions.get(session_id, task_id)
    except ValueError as exc:
        abort(410, description=str(exc))


def _client_save_csrf_error():
    if not _is_valid_local_csrf(request.form.get("csrf_token", "")):
        return jsonify(ok=False, message="页面校验已失效，请刷新后再试。"), 403
    return None


@app.post("/queue/<task_id>/client-save")
def create_client_save(task_id):
    error = _client_save_csrf_error()
    if error is not None:
        return error
    _store, item = queue_record_or_404(task_id, include_config=True)
    if item.get("status") not in {"succeeded", "review_required"}:
        return jsonify(ok=False, message="只有已生成的任务可以保存，排队和制作中的任务不会清理。"), 409
    if item.get("output_retention_state") == "expired":
        return jsonify(ok=False, message="服务器成片已清理，不能下载；可尝试一键重做。"), 410
    guard = _mark_output_download_tasks([task_id])
    try:
        artifacts = queue_delivery_artifacts(item, include_reports=True)
        if not any(artifact.get("role") == "video" for artifact in artifacts):
            raise ValueError("没有可保存的视频")
        for artifact in artifacts:
            artifact["save_identity"] = _bundle_member_identity(Path(artifact["path"]))
        save = client_save_sessions.create(task_id, artifacts)
        files = [
            {"index": index, "name": artifact["delivery_name"],
             "size": artifact["save_identity"]["size"],
             "url": f"/queue/{task_id}/client-save/{save['id']}/file/{index}"}
            for index, artifact in enumerate(artifacts)
        ]
        response = jsonify(
            ok=True, session_id=save["id"], files=files, expires_in=7200,
            bundle_url=f"/queue/{task_id}/client-save/{save['id']}/bundle",
            folder_name=f"快手成片_{task_id[:8]}_{save['id'][:12]}",
        )
        response.headers["Cache-Control"] = "no-store"
        return response
    except (OSError, ValueError, NotFound) as exc:
        return jsonify(ok=False, message=redact_local_paths(exc)), 409
    finally:
        _release_output_download_tasks(guard)


@app.post("/queue/client-save-status")
def client_save_status():
    error = _client_save_csrf_error()
    if error is not None:
        return error
    if not TENANT_BACKEND_MODE or not TENANT_USER_ID or not TENANT_ID:
        abort(403)
    try:
        task_ids = json.loads(request.form.get("task_ids", "[]"))
        store = get_task_queue_store(create=False)
        if store is None:
            return jsonify(ok=False, message="任务队列暂不可用，请稍后重新开启自动保存。"), 503
        tasks = store.local_save_status_owned(TENANT_USER_ID, task_ids, tenant_id=TENANT_ID)
        response = jsonify(ok=True, tasks=tasks)
        response.headers["Cache-Control"] = "no-store"
        return response
    except (TypeError, ValueError):
        return jsonify(ok=False, message="自动保存任务编号无效或超过单次200项限制。"), 400
    except (OSError, sqlite3.Error):
        return jsonify(ok=False, message="读取任务状态失败，尚未记录本机保存状态，服务器成片仍保留48小时。"), 503


@app.get("/queue/<task_id>/client-save/<session_id>/file/<int:index>")
def client_save_file(task_id, session_id, index):
    save = _client_save_record(task_id, session_id)
    if save["released"] or index < 0 or index >= len(save["artifacts"]):
        abort(410)
    def build_response():
        artifact = save["artifacts"][index]
        if _bundle_member_identity(Path(artifact["path"])) != artifact["save_identity"]:
            abort(409)
        response = _send_tracked_artifact(artifact, task_id, record_completion=False)
        return _track_complete_get_response(
            response, artifact["save_identity"]["size"], [],
            on_complete=lambda: client_save_sessions.transferred(session_id, [index]),
        )
    return _guard_output_download_response([task_id], build_response)


@app.get("/queue/<task_id>/client-save/<session_id>/bundle")
def client_save_bundle(task_id, session_id):
    save = _client_save_record(task_id, session_id)
    if save["released"]:
        abort(410)
    def build_response():
        for artifact in save["artifacts"]:
            if _bundle_member_identity(Path(artifact["path"])) != artifact["save_identity"]:
                abort(409)
        keys = [a["internal_name"] for a in save["artifacts"] if a.get("role") == "video"]
        response = cached_zip_response(
            save["artifacts"], f"快手成片_{task_id[:8]}.zip", f"client-save:{session_id}",
            [(task_id, keys)], record_completion=False,
            on_transfer_complete=lambda _path: client_save_sessions.transferred(session_id, range(len(save["artifacts"]))),
        )
        path = response._client_save_cache_path
        identity = _bundle_member_identity(path)
        with client_save_sessions.lock:
            if not any(existing[0] == path for existing in save["bundles"]):
                save["bundles"].append((path, identity))
        return response
    return _guard_output_download_response([task_id], build_response)


@app.post("/queue/<task_id>/client-save/<session_id>/confirm")
def confirm_client_save(task_id, session_id):
    error = _client_save_csrf_error()
    if error is not None:
        return error
    save = _client_save_record(task_id, session_id)
    if save["confirmed"]:
        return jsonify(ok=True, message="本次保存已经确认，服务器成片仍从实际完成起保留48小时。")
    if save["released"]:
        return jsonify(ok=False, message="保存已取消或失效，服务器成片仍从实际完成起保留48小时。"), 410
    mode = request.form.get("mode", "")
    try:
        supplied = json.loads(request.form.get("files", "[]"))
        expected = [{"index": i, "size": a["save_identity"]["size"]} for i, a in enumerate(save["artifacts"])]
        if supplied != expected:
            raise ValueError("必须确认该任务的全部文件均已保存。")
        if mode == "filesystem":
            if save["transferred"] != set(range(len(expected))):
                raise ValueError("文件尚未全部完整传输，不能清理。")
        elif mode != "user-confirmed" or request.form.get("confirmed") != "yes":
            raise ValueError("请先核对本机全部文件，再明确确认已保存；服务器仍保留48小时。")
        for artifact in save["artifacts"]:
            if _bundle_member_identity(Path(artifact["path"])) != artifact["save_identity"]:
                raise ValueError("服务器文件已变化，已停止清理。")
        keys = [a["internal_name"] for a in save["artifacts"] if a.get("role") == "video"]
        if not _record_completed_download_receipts([(task_id, keys)]):
            return jsonify(ok=False, message="本机文件已保存，但服务器暂时无法记录确认；请稍后重试确认，不必重新下载。"), 503
        for path, identity in save["bundles"]:
            if path.is_file() and _bundle_member_identity(path) == identity:
                _persist_bundle_ownership(path, [(task_id, keys)], completed=True)
        client_save_sessions.finish(session_id, confirmed=True)
        for path, _identity in save["bundles"]:
            _delete_completed_bundle_cache(path)
        return jsonify(ok=True, message="已记录保存到本机；服务器副本仍保留到任务实际完成满48小时，不会因下载而提前删除。")
    except (OSError, TypeError, ValueError) as exc:
        return jsonify(ok=False, message=redact_local_paths(exc)), 409


@app.post("/queue/<task_id>/client-save/<session_id>/cancel")
def cancel_client_save(task_id, session_id):
    error = _client_save_csrf_error()
    if error is not None:
        return error
    _client_save_record(task_id, session_id)
    client_save_sessions.finish(session_id)
    return jsonify(ok=True, message="已取消本次保存，不标记已下载，未提前清理成片。")


def _valid_queue_control_csrf():
    return _is_valid_local_csrf(request.form.get("csrf_token", ""))


@app.post("/queue/<task_id>/pause")
def pause_queue_task(task_id):
    if not _valid_queue_control_csrf():
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    store, item = queue_record_or_404(task_id)
    if not renderer_pause_supported():
        return action_response(
            "当前系统暂不支持安全暂停；没有假装暂停，制作仍按原状态运行。",
            ok=False,
            status_code=503,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if item.get("status") != "running":
        return action_response(
            "只有正在制作的任务可以暂停；等待、停止或保存中的任务不会被改动。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    control_state = str(item.get("control_state") or "active")
    if control_state == "paused":
        return action_response(
            "这条已经暂停，点击“继续制作”即可接着做。",
            ok=True,
            status_code=200,
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if control_state == "pause_requested":
        task_queue_control_wakeup.set()
        return action_response(
            "正在暂停，请稍候；进度和当前成片现场都会保留。",
            ok=True,
            status_code=202,
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if control_state == "resume_requested":
        return action_response(
            "这条正在恢复，请恢复完成后再暂停。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if not store.request_pause(task_id):
        return action_response(
            "任务状态刚刚发生变化，请稍后再试。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    task_queue_control_wakeup.set()
    return action_response(
        "已收到暂停请求；系统正在停住当前制作进程。",
        ok=True,
        status_code=202,
        anchor="queue-panel",
        state=snapshot_state(),
    )


@app.post("/queue/<task_id>/resume")
def resume_queue_task(task_id):
    if not _valid_queue_control_csrf():
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    store, item = queue_record_or_404(task_id)
    if not renderer_pause_supported():
        return action_response(
            "当前系统没有安全的进程恢复能力。",
            ok=False,
            status_code=503,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if item.get("status") != "running":
        return action_response(
            "这条已经不在可继续的制作阶段。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    control_state = str(item.get("control_state") or "active")
    if control_state == "active":
        return action_response(
            "这条已经在制作。",
            ok=True,
            status_code=200,
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if control_state == "resume_requested":
        task_queue_control_wakeup.set()
        return action_response(
            "正在继续制作，请稍候。",
            ok=True,
            status_code=202,
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if control_state == "pause_requested":
        if not store.normalize_control(task_id, "正在制作"):
            return action_response(
                "暂停状态刚刚发生变化，请稍后再试。",
                ok=False,
                status_code=409,
                level="warn",
                anchor="queue-panel",
                state=snapshot_state(),
            )
    elif not store.request_resume(task_id):
        return action_response(
            "暂停状态刚刚发生变化，请稍后再试。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    task_queue_control_wakeup.set()
    return action_response(
        "正在继续制作；会从暂停的位置接着运行。",
        ok=True,
        status_code=202,
        anchor="queue-panel",
        state=snapshot_state(),
    )


@app.post("/queue/<task_id>/cancel")
def cancel_queue_task(task_id):
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    store, item = queue_record_or_404(task_id, include_config=True)
    status_name = item.get("status")
    if status_name == "waiting" and store.cancel_waiting(task_id):
        config = item.get("config")
        if isinstance(config, dict) and config.get("asset_set_id"):
            best_effort_reclaim_task_asset_sets(
                store,
                config.get("asset_set_id"),
                **_current_cleanup_scope_kwargs(),
            )
        return action_response(
            "这条等待任务已取消。",
            ok=True,
            status_code=200,
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if status_name in {"running", "skip_requested"}:
        if status_name == "running" and not store.request_skip(task_id):
            return action_response(
                "任务状态刚刚发生变化，请稍后再试。",
                ok=False,
                status_code=409,
                level="warn",
                anchor="queue-panel",
                state=snapshot_state(),
            )
        request_queue_skip(task_id)
        task_queue_wakeup.set()
        return action_response(
            "正在停止这条；停止后会自动制作下一条。",
            ok=True,
            status_code=202,
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if status_name == "finalizing":
        return action_response(
            "成品已经生成，正在验收和保存记录，现在不能再跳过。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    return action_response(
        "这条任务已经结束，不需要再取消。",
        ok=False,
        status_code=409,
        level="warn",
        anchor="queue-panel",
        state=snapshot_state(),
    )


@app.post("/queue/<task_id>/retry")
def retry_queue_task(task_id):
    return _requeue_original_task(task_id)


@app.post("/queue/<task_id>/redo")
def redo_queue_task(task_id):
    return _requeue_original_task(task_id, redo=True)


def _requeue_original_task(task_id, *, redo=False):
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    store, item = queue_record_or_404(task_id, include_config=True)
    allowed = {"succeeded", "review_required"} if redo else {
        "failed",
        "timed_out",
        "skipped",
        "canceled",
        "interrupted",
    }
    if item.get("status") not in allowed:
        return action_response(
            "这条任务还没有结束，暂时不能重新排队。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    original_config = item.get("config")
    asset_validator = ensure_redo_task_assets_available if redo else ensure_retry_task_assets_available
    if not isinstance(original_config, dict):
        return action_response(
            "原任务设置已经损坏，不能重新排队。",
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    # Idempotency belongs to the source task, not to one browser tab's random
    # request token.  Two browsers logged in as the same user must never create
    # two retry children for the same failed task.
    retry_submission_key = f"retry:{task_id}"
    if redo:
        if not TENANT_BACKEND_MODE:
            return action_response("重做需要登录当前用户空间。", ok=False, status_code=403)
        try:
            token = parse_queue_request_token("request_token")
            if not token:
                raise ValueError("重做操作缺少防重复标识，请刷新页面。")
            retry_submission_key = f"redo:{task_id}:{token}"
        except ValueError as exc:
            return action_response(str(exc), ok=False, status_code=422)
    try:
        existing_retry = _public_submission_get(store, retry_submission_key)
    except (OSError, sqlite3.Error) as exc:
        return action_response(
            f"暂时无法读取制作队列：{redact_local_paths(exc)}",
            ok=False,
            status_code=500,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if existing_retry is not None:
        ensure_task_queue_worker(create=True)
        return action_response(
            "这次重试已经加入过队列，没有重复创建任务。",
            ok=True,
            status_code=200,
            anchor="queue-panel",
            task_id=existing_retry["task_id"],
            state=snapshot_state(),
        )
    strict_readiness_error = strict_erp_readiness_error()
    if strict_readiness_error:
        return action_response(
            strict_readiness_error,
            ok=False,
            status_code=503,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    try:
        asset_validator(original_config)
    except TaskAssetUnavailableError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    try:
        customer = resolve_run_customer()
    except BillingError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=402,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    if (
        CUSTOMER_BILLING_REQUIRED
        and int(original_config.get("customer_id", -1)) != int(customer["id"])
    ):
        return action_response(
            "这条任务不属于当前客户，不能重新排队。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    try:
        with operation_lock:
            retried = _public_submission_get(store, retry_submission_key)
            if retried is None:
                # Recheck under the same lock used by successful-set GC.  This
                # closes the race between validating a retry and releasing the
                # last task-private material reference.
                asset_validator(original_config)
                if CUSTOMER_BILLING_REQUIRED:
                    fresh_customer = resolve_run_customer()
                    if int(fresh_customer["id"]) != int(customer["id"]):
                        raise BillingError(
                            "客户身份在重试期间发生变化，请重新确认后再试。"
                        )
                    customer = fresh_customer
                    units = max(1, int(original_config.get("fission_count", 1)))
                    reserved_units = store.reserved_units_for_customer(customer["id"])
                    available_units = int(customer.get("balance", 0))
                    if available_units < reserved_units + units:
                        raise BillingError(
                            f"余额不足：当前剩余 {available_units} 次，"
                            f"队列已预留 {reserved_units} 次，重试还需要 {units} 次。"
                        )
                if redo:
                    retried = store.redo_completed_owned(
                        TENANT_USER_ID, task_id, tenant_id=TENANT_ID,
                        submission_key=retry_submission_key,
                        validate_config=asset_validator,
                    )
                elif TENANT_BACKEND_MODE:
                    retried = store.retry_owned(
                        TENANT_USER_ID,
                        task_id,
                        submission_key=retry_submission_key,
                        tenant_id=TENANT_ID,
                    )
                else:
                    retried = store.retry(
                        task_id,
                        submission_key=retry_submission_key,
                    )
                if not retried:
                    raise RuntimeError("原任务配置无法读取")
            if GLOBAL_FIFO_COORDINATOR is not None:
                try:
                    _publish_current_global_fifo_head(store)
                except (OSError, sqlite3.Error, RuntimeError, TypeError, ValueError):
                    pass
            ensure_task_queue_worker(create=True)
    except TaskAssetUnavailableError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=409,
            level="warn",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    except BillingError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=402,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    except (OSError, sqlite3.Error, RuntimeError, TypeError, ValueError) as exc:
        return action_response(
            f"重新排队失败：{redact_local_paths(exc)}",
            ok=False,
            status_code=500,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    return action_response(
        "已按原设置重新排到队尾。",
        ok=True,
        status_code=202,
        anchor="queue-panel",
        task_id=retried["task_id"],
        state=snapshot_state(),
    )


