def _parse_selected_task_ids(field_name="task_ids"):
    try:
        raw_task_ids = json.loads(request.form.get(field_name, "[]"))
    except (TypeError, json.JSONDecodeError):
        raw_task_ids = None
    if not isinstance(raw_task_ids, list):
        raise ValueError("请选择有效的完成任务。")
    task_ids = list(
        dict.fromkeys(str(task_id or "").strip().lower() for task_id in raw_task_ids)
    )
    if (
        not task_ids
        or len(task_ids) > 100
        or any(not re.fullmatch(r"[0-9a-f]{32}", task_id) for task_id in task_ids)
    ):
        raise ValueError("请选择 1–100 条有效完成任务。")
    return task_ids


def _urlsafe_ticket_part(raw):
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def _decode_urlsafe_ticket_part(value):
    text = str(value or "")
    return base64.urlsafe_b64decode(text + ("=" * (-len(text) % 4)))


def _make_batch_download_ticket(task_ids):
    payload = {
        "v": 1,
        "exp": int(time.time()) + BATCH_DOWNLOAD_TICKET_SECONDS,
        "task_ids": list(task_ids),
        "owner_user_id": TENANT_USER_ID,
        "tenant_id": TENANT_ID,
    }
    packed = zlib.compress(
        json.dumps(payload, ensure_ascii=True, separators=(",", ":")).encode(
            "utf-8"
        ),
        level=9,
    )
    signature = hmac.new(
        CSRF_TOKEN.encode("utf-8"), packed, hashlib.sha256
    ).digest()
    return f"{_urlsafe_ticket_part(packed)}.{_urlsafe_ticket_part(signature)}"


def _read_batch_download_ticket(ticket):
    try:
        packed_part, signature_part = str(ticket or "").split(".", 1)
        if len(packed_part) > 8192 or len(signature_part) > 128:
            raise ValueError("下载凭据过长")
        packed = _decode_urlsafe_ticket_part(packed_part)
        signature = _decode_urlsafe_ticket_part(signature_part)
        expected = hmac.new(
            CSRF_TOKEN.encode("utf-8"), packed, hashlib.sha256
        ).digest()
        if not hmac.compare_digest(signature, expected):
            raise ValueError("下载凭据签名无效")
        inflater = zlib.decompressobj()
        decoded = inflater.decompress(packed, (32 * 1024) + 1)
        if len(decoded) > 32 * 1024 or inflater.unconsumed_tail or not inflater.eof:
            raise ValueError("下载凭据内容过长")
        payload = json.loads(decoded)
        if not isinstance(payload, dict):
            raise ValueError("下载凭据结构无效")
        task_ids = payload.get("task_ids")
        if (
            payload.get("v") != 1
            or int(payload.get("exp") or 0) < int(time.time())
            or payload.get("owner_user_id") != TENANT_USER_ID
            or payload.get("tenant_id") != TENANT_ID
            or not isinstance(task_ids, list)
        ):
            raise ValueError("下载凭据已过期")
        normalized = list(
            dict.fromkeys(str(task_id or "").strip().lower() for task_id in task_ids)
        )
        if (
            not normalized
            or len(normalized) > 100
            or any(
                not re.fullmatch(r"[0-9a-f]{32}", task_id)
                for task_id in normalized
            )
        ):
            raise ValueError("下载凭据任务无效")
        return normalized
    except (
        ValueError,
        TypeError,
        OverflowError,
        UnicodeError,
        zlib.error,
        json.JSONDecodeError,
    ):
        abort(403)


def _queue_record_for_delivery(task_id):
    store = get_task_queue_store(create=False)
    try:
        item = (
            _public_queue_get(store, task_id, include_config=True)
            if store is not None
            else None
        )
    except (OSError, sqlite3.Error):
        item = None
    if not isinstance(item, dict):
        abort(404)
    if str(item.get("output_retention_state") or "") == "expired":
        abort(410)
    result = item.get("result") if isinstance(item.get("result"), dict) else {}
    status_name = str(item.get("status") or "")
    if status_name not in {
        "succeeded",
        "review_required",
        "failed",
        "timed_out",
        "interrupted",
    } or result.get("kind") not in {"single", "fission"}:
        abort(404)
    if status_name not in {"succeeded", "review_required"} and not (
        result.get("kind") == "fission"
        and result.get("delivery_state") == "partial"
        and result.get("outputs")
    ):
        abort(404)
    return item


@app.post("/queue/batch-download")
def batch_download_queue_tasks():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        abort(403)
    try:
        task_ids = _parse_selected_task_ids()
    except ValueError:
        abort(400)
    return redirect(
        url_for(
            "batch_download_queue_tasks_get",
            ticket=_make_batch_download_ticket(task_ids),
        ),
        code=303,
    )


@app.get("/queue/batch-download/file")
def batch_download_queue_tasks_get():
    try:
        task_ids = _read_batch_download_ticket(request.args.get("ticket", ""))
        def build_response():
            artifacts = []
            completion_receipts = []
            delivered_task_count = 0
            expired_task_count = 0
            for task_id in task_ids:
                try:
                    task_artifacts = queue_delivery_artifacts(
                        _queue_record_for_delivery(task_id), include_reports=True
                    )
                except Gone:
                    expired_task_count += 1
                    continue
                except (NotFound, OSError, ValueError, FileNotFoundError):
                    continue
                if not task_artifacts:
                    continue
                artifacts.extend(task_artifacts)
                completion_receipts.append(
                    (
                        task_id,
                        [
                            artifact["internal_name"]
                            for artifact in task_artifacts
                            if artifact.get("role") == "video"
                        ],
                    )
                )
                delivered_task_count += 1
            if not artifacts:
                if expired_task_count:
                    abort(410, description="所选成片已清理，无法重新下载；请重新选择仍保留的成片。")
                raise FileNotFoundError("所选任务没有可下载成片")
            skipped_task_count = len(task_ids) - delivered_task_count
            skipped_label = f"_已跳过{skipped_task_count}个不可用任务" if skipped_task_count else ""
            bundle_name = (
                f"快手成片_批量{delivered_task_count}个任务{skipped_label}_"
                f"{time.strftime('%Y%m%d_%H%M%S')}.zip"
            )
            response = cached_zip_response(
                artifacts,
                bundle_name,
                "batch:" + ",".join(task_ids),
                completion_receipts=completion_receipts,
            )
            response.headers["X-V17-Delivered-Tasks"] = str(delivered_task_count)
            response.headers["X-V17-Skipped-Tasks"] = str(skipped_task_count)
            return response

        return _guard_output_download_response(
            task_ids,
            build_response,
        )
    except (OSError, ValueError, FileNotFoundError):
        abort(404)


@app.post("/queue/batch-save")
def batch_save_queue_tasks():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    try:
        task_ids = _parse_selected_task_ids()
        save_root = str(validate_auto_save_directory(load_auto_save_directory()))
    except ValueError as exc:
        return action_response(
            str(exc),
            ok=False,
            status_code=422,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    store = get_task_queue_store(create=False)
    saved_count = 0
    released_bytes = 0
    failures = []
    for task_id in task_ids:
        try:
            item = (
                _public_queue_get(store, task_id, include_config=True)
                if store is not None
                else None
            )
            if not isinstance(item, dict) or item.get("status") not in {
                "succeeded",
                "review_required",
            }:
                raise ValueError("任务不是可直接保存的完成状态")
            config = dict(item.get("config") or {})
            result = dict(item.get("result") or {})
            # Resolve and verify the current source before changing the saved
            # destination.  It may be the private C-drive copy or an earlier
            # SHA-256-anchored export whose private copy has been released.
            source_overrides = {
                artifact["internal_name"]: artifact["path"]
                for artifact in queue_delivery_artifacts(
                    item,
                    include_reports=True,
                )
            }
            config.update(
                {
                    "auto_save_directory": save_root,
                    "auto_save_folder_scheme": 3,
                    "delivery_policy": DELIVERY_POLICY_DIRECT_FILES_V3,
                }
            )
            result["auto_save"] = best_effort_auto_save_task(
                task_id,
                config,
                result,
                source_overrides=source_overrides,
            )
            if result["auto_save"].get("status") != "saved":
                raise RuntimeError(result["auto_save"].get("message") or "保存失败")
            if not store.update_terminal_delivery(task_id, config, result):
                raise RuntimeError("完成记录状态刚刚发生变化")
            item.update({"config": config, "result": result})
            released_bytes += release_internal_delivery_copies(item)
            saved_count += 1
        except Exception as exc:
            failures.append(redact_local_paths(exc, save_root))
    storage_scan_cache["checked_monotonic"] = 0.0
    if saved_count <= 0:
        return action_response(
            f"所选任务都没有保存成功：{failures[0] if failures else '没有可保存成片'}",
            ok=False,
            status_code=409,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    failure_suffix = f"；另有 {len(failures)} 条未完成" if failures else ""
    return action_response(
        f"已把 {saved_count} 个任务直接保存为独立文件，不需要解压；"
        f"并安全释放应用内重复副本 {released_bytes / GIB_BYTES:.2f} GiB"
        f"{failure_suffix}。",
        ok=True,
        status_code=200,
        anchor="queue-panel",
        state=snapshot_state(),
    )


@app.post("/storage/cleanup-safe")
def cleanup_safe_storage_route():
    submitted_token = request.form.get("csrf_token", "")
    if not _is_valid_local_csrf(submitted_token):
        return action_response(
            "页面校验已失效，请刷新后重试。",
            ok=False,
            status_code=403,
            level="error",
            anchor="queue-panel",
            state=snapshot_state(),
        )
    store = get_task_queue_store(create=False)
    output_cleanup = {
        "released_bytes": 0,
        "examined_count": 0,
        "failure_count": 0,
    }
    asset_outcomes = []
    if store is not None:
        output_cleanup = best_effort_release_saved_internal_outputs(
            store,
            **_current_cleanup_scope_kwargs(),
        )
        asset_outcomes = best_effort_reclaim_task_asset_sets(
            store,
            **_current_cleanup_scope_kwargs(),
        )
    result = cleanup_safe_managed_storage()
    bundle_cleanup = cleanup_bundle_download_cache()
    total_released = int(result["released_bytes"]) + int(
        output_cleanup["released_bytes"]
    ) + int(bundle_cleanup["released_bytes"])
    released_asset_sets = sum(
        1 for outcome in asset_outcomes if outcome.get("released")
    )
    return action_response(
        "安全清理完成：删除了 "
        f"{result['removed_zip_count']} 个逐字节验证的重复压缩包、"
        f"{result['removed_partial_count']} 个超过 24 小时的中断临时文件，"
        f"{bundle_cleanup['removed_count']} 个已确认完整传输的下载整包（未完成打包保留），"
        f"{released_asset_sets} 套已保留满 3 小时的任务私有素材，"
        f"并检查 {output_cleanup['examined_count']} 个临时交付任务；"
        f"共释放 {total_released / GIB_BYTES:.2f} GiB。"
        "原始素材、数据库以及仍在保留期内的唯一成片都没有删除。",
        ok=True,
        status_code=200,
        anchor="queue-panel",
        state=snapshot_state(),
    )


