def completed_fission_run_dir(run_id, require_bundle=True):
    if not re.fullmatch(r"[0-9a-f]{32}", run_id or ""):
        abort(404)
    root = FISSION_OUTPUT_ROOT.resolve()
    unresolved_run_dir = root / run_id
    if unresolved_run_dir.is_symlink():
        abort(404)
    run_dir = unresolved_run_dir.resolve()
    if run_dir.parent != root or run_dir.name != run_id or not run_dir.is_dir():
        abort(404)
    report_path = run_dir / "裂变相似度报告.json"
    if report_path.is_symlink() or not report_path.is_file():
        abort(404)
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        abort(404)
    if report.get("run_id") != run_id:
        abort(404)
    try:
        requested_count = int(report.get("video_count", 0))
    except (TypeError, ValueError):
        abort(404)
    if requested_count not in {3, 4, 5}:
        abort(404)
    if report.get("passed") is True:
        completed_count = requested_count
    elif (
        report.get("delivery_state") == "partial"
        and report.get("batch_complete") is False
        and report.get("passed") is False
        and report.get("accepted_outputs_passed") is True
    ):
        try:
            completed_count = int(report.get("completed_count", 0))
            reported_requested_count = int(report.get("requested_count", 0))
            failed_variant = int(report.get("failed_variant", 0))
        except (TypeError, ValueError):
            abort(404)
        if (
            reported_requested_count != requested_count
            or not 1 <= completed_count < requested_count
            or failed_variant != completed_count + 1
        ):
            abort(404)
    else:
        abort(404)
    expected_outputs = [
        f"V17裂变成片_第{index:02d}条.mp4"
        for index in range(1, completed_count + 1)
    ]
    if report.get("outputs") != expected_outputs:
        abort(404)
    for name in expected_outputs:
        output_path = run_dir / name
        if (
            output_path.is_symlink()
            or not output_path.is_file()
            or output_path.stat().st_size <= 0
        ):
            abort(404)
    zip_path = run_dir / "V17页面裂变成片_同时间轴相似度40以下.zip"
    if require_bundle and (
        zip_path.is_symlink()
        or not zip_path.is_file()
        or zip_path.stat().st_size <= 0
    ):
        abort(404)
    if require_bundle:
        expected_members = set(expected_outputs) | {report_path.name}
        try:
            with zipfile.ZipFile(zip_path) as archive:
                members = archive.infolist()
                member_names = [item.filename for item in members]
                if (
                    len(member_names) != len(expected_members)
                    or set(member_names) != expected_members
                    or any(item.is_dir() or item.flag_bits & 0x1 for item in members)
                    or any(PurePosixPath(name).name != name for name in member_names)
                ):
                    abort(404)
                for item in members:
                    if item.filename in expected_outputs and item.file_size <= 0:
                        abort(404)
        except (OSError, ValueError, zipfile.BadZipFile):
            abort(404)
    return run_dir, completed_count


