@app.get("/download-fission/<run_id>/bundle")
def download_fission_bundle(run_id):
    def build_response():
        item = _queue_record_for_delivery(run_id)
        artifacts = queue_delivery_artifacts(item, include_reports=True)
        videos = [artifact for artifact in artifacts if artifact["role"] == "video"]
        if not videos:
            raise FileNotFoundError("没有裂变成片")
        config = item.get("config") if isinstance(item.get("config"), dict) else {}
        result = item.get("result") if isinstance(item.get("result"), dict) else {}
        requested_count = int(
            result.get("requested_count") or result.get("count") or len(videos)
        )
        if len(videos) == requested_count and requested_count in {3, 4, 5}:
            bundle_name = delivery_bundle_name(
                config.get("task_name"), run_id, requested_count
            )
        else:
            bundle_name = (
                f"{task_delivery_stem(config.get('task_name'), run_id)}_"
                f"已完成{len(videos)}条.zip"
            )
        return cached_zip_response(
            artifacts,
            bundle_name,
            f"task:{run_id}",
            completion_receipts=[
                (
                    run_id,
                    [artifact["internal_name"] for artifact in videos],
                )
            ],
        )

    try:
        return _guard_output_download_response(
            (run_id,),
            build_response,
        )
    except (OSError, ValueError, FileNotFoundError):
        abort(404)


@app.get("/download-compliance")
def download_compliance():
    with state_lock:
        selected_state = _representative_task_state_locked()
        compliance_path = Path(
            selected_state.get("compliance_path") or COMPLIANCE_REPORT_FILE
        )
        output_ready = bool(selected_state.get("output_ready"))
        run_id = str(selected_state.get("run_id") or "")
    if not output_ready and not re.fullmatch(r"[0-9a-f]{32}", run_id):
        return redirect(url_for("index"))
    task_name = "快手成片"
    store = get_task_queue_store(create=False)
    try:
        item = (
            _public_queue_get(store, run_id, include_config=True)
            if store is not None
            else None
        )
        if isinstance(item, dict) and isinstance(item.get("config"), dict):
            task_name = item["config"].get("task_name") or task_name
    except (OSError, sqlite3.Error):
        pass
    download_name = (
        delivery_report_name(task_name, run_id, fission=False)
        if re.fullmatch(r"[0-9a-f]{32}", run_id)
        else "快手成片_合规报告.json"
    )
    if re.fullmatch(r"[0-9a-f]{32}", run_id):
        try:
            return _guard_output_download_response(
                (run_id,),
                lambda: _send_tracked_artifact(
                    queue_delivery_artifact(
                        _queue_record_for_delivery(run_id),
                        "report",
                    ),
                    run_id,
                    record_completion=False,
                ),
            )
        except (NotFound, OSError, ValueError, FileNotFoundError, StopIteration):
            return redirect(url_for("index"))
    if output_ready and compliance_path.is_file():
        return send_file(
            compliance_path,
            as_attachment=True,
            download_name=download_name,
            mimetype="application/json",
        )
    return redirect(url_for("index"))


