def shutdown_queue_runtime(join_timeout_seconds=5.0):
    """Atomically stop new renderer launches, then clean every owned group."""
    with task_queue_control_lock:
        task_queue_shutdown_event.set()
    task_queue_control_wakeup.set()
    task_queue_wakeup.set()
    with task_queue_recovery_condition:
        task_queue_recovery_condition.notify_all()
    terminate_all_queue_renderers()
    with task_queue_worker_lock:
        workers = list(task_queue_worker_threads)
        if daily_completed_output_cleanup_thread is not None:
            workers.append(daily_completed_output_cleanup_thread)
    deadline = time.monotonic() + max(0.0, float(join_timeout_seconds))
    current_thread = threading.current_thread()
    for worker in workers:
        if worker is None or worker is current_thread or not worker.is_alive():
            continue
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        worker.join(timeout=remaining)


atexit.register(shutdown_queue_runtime)


def _handle_service_shutdown(_signum, _frame):
    try:
        shutdown_queue_runtime()
    finally:
        # Process exit closes every remaining Windows Job handle; KILL_ON_CLOSE
        # therefore remains the last-resort tree cleanup even after an API error.
        raise SystemExit(0)


