if __name__ == "__main__":
    if not INSTANCE_ID:
        raise SystemExit(
            "请使用 8020 多用户服务器启动器启动，避免实例身份和数据目录错位。"
        )
    ensure_dirs()
    if os.environ.get("V16_INSTALLER_SELF_TEST") != "1":
        # Only a cold process with no owned renderers/reservations may remove
        # the shared root left by an interrupted previous process.
        cleanup_renderer_working_root_if_idle()
        ensure_task_queue_worker(create=True)
    if threading.current_thread() is threading.main_thread():
        signal.signal(signal.SIGTERM, _handle_service_shutdown)
        signal.signal(signal.SIGINT, _handle_service_shutdown)
        if hasattr(signal, "SIGHUP"):
            signal.signal(signal.SIGHUP, _handle_service_shutdown)
    app.run(host=os.environ.get("V16_HOST", "127.0.0.1"), port=int(os.environ.get("PORT", "8020")), debug=False)
